# ══════════════════════════════════════════════════════════
#  常用软件与系统重装
# ══════════════════════════════════════════════════════════

software_package_manager() {
    if command -v apt-get >/dev/null 2>&1; then echo apt
    elif command -v dnf >/dev/null 2>&1; then echo dnf
    elif command -v yum >/dev/null 2>&1; then echo yum
    elif command -v apk >/dev/null 2>&1; then echo apk
    elif command -v opkg >/dev/null 2>&1; then echo opkg
    elif command -v pacman >/dev/null 2>&1; then echo pacman
    else echo unknown
    fi
}

software_group_packages() {
    local PM="$1" GROUP="$2"
    case "$PM:$GROUP" in
        apt:base) echo "curl wget git jq unzip zip tar nano vim tmux screen ca-certificates" ;;
        apt:network) echo "iproute2 dnsutils mtr-tiny traceroute tcpdump netcat-openbsd socat nmap" ;;
        apt:monitor) echo "htop iftop iotop sysstat lsof ncdu" ;;
        apt:develop) echo "build-essential python3 python3-pip" ;;
        dnf:base|yum:base) echo "curl wget git jq unzip zip tar nano vim-enhanced tmux screen ca-certificates" ;;
        dnf:network|yum:network) echo "iproute bind-utils mtr traceroute tcpdump nmap-ncat socat nmap" ;;
        dnf:monitor|yum:monitor) echo "htop iftop iotop sysstat lsof ncdu" ;;
        dnf:develop|yum:develop) echo "gcc gcc-c++ make python3 python3-pip" ;;
        apk:base) echo "curl wget git jq unzip zip tar nano vim tmux screen ca-certificates" ;;
        apk:network) echo "iproute2 bind-tools mtr traceroute tcpdump netcat-openbsd socat nmap" ;;
        apk:monitor) echo "htop iftop iotop sysstat lsof ncdu" ;;
        apk:develop) echo "build-base python3 py3-pip" ;;
        opkg:base) echo "curl wget-ssl git git-http jq unzip zip tar nano-full vim-fuller tmux screen ca-bundle" ;;
        opkg:network) echo "ip-full bind-dig mtr traceroute tcpdump netcat socat nmap" ;;
        opkg:monitor) echo "htop iftop iotop sysstat lsof ncdu" ;;
        opkg:develop) echo "python3 python3-pip make gcc" ;;
        pacman:base) echo "curl wget git jq unzip zip tar nano vim tmux screen ca-certificates" ;;
        pacman:network) echo "iproute2 bind mtr traceroute tcpdump openbsd-netcat socat nmap" ;;
        pacman:monitor) echo "htop iftop iotop sysstat lsof ncdu" ;;
        pacman:develop) echo "base-devel python python-pip" ;;
    esac
}

software_refresh_index() {
    case "$1" in
        apt) apt-get update -qq ;;
        dnf) dnf makecache -q ;;
        yum) yum makecache -q ;;
        apk) apk update ;;
        opkg) opkg update ;;
        pacman) pacman -Sy --noconfirm ;;
        *) return 1 ;;
    esac
}

software_install_one() {
    local PM="$1" PKG="$2"
    case "$PM" in
        apt) DEBIAN_FRONTEND=noninteractive apt-get install -y "$PKG" ;;
        dnf) dnf install -y "$PKG" ;;
        yum) yum install -y "$PKG" ;;
        apk) apk add --no-cache "$PKG" ;;
        opkg) opkg install "$PKG" ;;
        pacman) pacman -S --noconfirm --needed "$PKG" ;;
        *) return 1 ;;
    esac
}

software_install_packages() {
    local PM="$1" PACKAGES="$2" PKG OK=0 FAILED=0 FAILED_LIST=""
    info "正在刷新软件包索引..."
    software_refresh_index "$PM" || warn "软件包索引刷新失败，将继续尝试安装"
    for PKG in $PACKAGES; do
        echo -e "  ${CYAN}›${NC} 安装 ${BOLD}$PKG${NC}"
        if software_install_one "$PM" "$PKG" >/dev/null 2>&1; then
            OK=$((OK+1))
        else
            FAILED=$((FAILED+1)); FAILED_LIST="${FAILED_LIST} ${PKG}"
        fi
    done
    echo ""; menu_div
    info "安装完成：成功 $OK 个，失败 $FAILED 个"
    [ "$FAILED" -gt 0 ] && warn "未安装：${FAILED_LIST# }"
    audit_action "安装常用软件：成功 $OK，失败 $FAILED" SUCCESS
}

common_software_menu() {
    while true; do
        print_header "安装常用软件"
        local PM; PM=$(software_package_manager)
        echo -e "  包管理器：${BOLD}$PM${NC}"
        ui_hint "可多选，例如 1 2 3；重复软件会自动去重"
        echo ""; menu_div
        menu_item "1" "基础工具  ${DIM}curl / wget / git / jq / tmux / 编辑器${NC}"
        menu_item "2" "网络诊断  ${DIM}mtr / tcpdump / socat / nmap / DNS${NC}"
        menu_item "3" "系统监控  ${DIM}htop / iftop / iotop / sysstat / ncdu${NC}"
        menu_item "4" "开发环境  ${DIM}编译工具 / Python / pip${NC}"
        menu_item "5" "全部推荐软件"
        menu_item "6" "安装自定义软件包"
        menu_item "0" "返回上级" "$RED"
        menu_div; echo ""
        read -rp "$(ui_prompt '选择分类 [0-6，可多选]: ')" CHOICES
        [ "$CHOICES" = "0" ] && return
        [ "$PM" != "unknown" ] || { error "未识别到支持的包管理器"; ui_pause; return; }

        local PACKAGES="" CH GROUP PKG
        CHOICES=${CHOICES//,/ }
        for CH in $CHOICES; do
            case "$CH" in
                1) GROUP="base" ;;
                2) GROUP="network" ;;
                3) GROUP="monitor" ;;
                4) GROUP="develop" ;;
                5) GROUP="base network monitor develop" ;;
                6)
                    read -rp "$(ui_prompt '输入软件包名称: ')" PKG
                    if ! echo "$PKG" | grep -qE '^[A-Za-z0-9.+_-]+$'; then error "软件包名称格式无效"; continue; fi
                    PACKAGES="$PACKAGES $PKG"; continue ;;
                *) warn "忽略无效分类：$CH"; continue ;;
            esac
            local G
            for G in $GROUP; do
                for PKG in $(software_group_packages "$PM" "$G"); do
                    case " $PACKAGES " in *" $PKG "*) ;; *) PACKAGES="$PACKAGES $PKG" ;; esac
                done
            done
        done
        PACKAGES=${PACKAGES# }
        [ -n "$PACKAGES" ] || { warn "没有选择可安装的软件"; sleep 1; continue; }
        echo ""; echo -e "  ${BOLD}准备安装：${NC}"
        echo "$PACKAGES" | fold -s -w "$((BOX_W-4))" | sed 's/^/  /'
        confirm_change_preview "安装常用软件" "包管理器：$PM" "软件包数量：$(echo "$PACKAGES" | wc -w | tr -d ' ')" || { warn "已取消"; continue; }
        software_install_packages "$PM" "$PACKAGES"
        ui_pause
    done
}

reinstall_is_container() {
    local VIRT=""
    command -v systemd-detect-virt >/dev/null 2>&1 && VIRT=$(systemd-detect-virt 2>/dev/null || true)
    case "$VIRT" in lxc|lxc-libvirt|openvz|docker|podman|container-other) return 0 ;; esac
    grep -qaE 'lxc|openvz|docker|kubepods|containerd' /proc/1/cgroup /proc/1/environ 2>/dev/null
}

reinstall_download_engine() {
    local DEST="$1"
    local URL="https://raw.githubusercontent.com/bin456789/reinstall/main/reinstall.sh"
    info "正在从官方仓库下载重装工具..."
    if command -v curl >/dev/null 2>&1; then
        curl -fL --retry 3 --connect-timeout 10 "$URL" -o "$DEST"
    elif command -v wget >/dev/null 2>&1; then
        wget -O "$DEST" "$URL"
    else
        error "需要先安装 curl 或 wget"
        return 1
    fi
    bash -n "$DEST" 2>/dev/null || { rm -f "$DEST"; error "下载脚本语法校验失败"; return 1; }
    chmod 700 "$DEST"
    local HASH; HASH=$(file_sha256 "$DEST" 2>/dev/null || echo "无法计算")
    info "下载完成，SHA256：$HASH"
}

reinstall_collect_auth_args() {
    REINSTALL_AUTH_ARGS=()
    local SSH_PORT KEY PASSWORD PASSWORD2
    SSH_PORT=$(get_config Port); SSH_PORT=${SSH_PORT:-22}
    KEY=$(grep -m1 -E '^(ssh-rsa|ssh-ed25519|ecdsa-sha2|sk-ssh|sk-ecdsa) ' "$AUTH_KEYS" 2>/dev/null || true)
    echo -e "  新系统 SSH 端口：${BOLD}$SSH_PORT${NC}"
    if [ -n "$KEY" ]; then
        info "检测到 SSH 公钥，新系统将继续使用该公钥"
        REINSTALL_AUTH_ARGS=(--ssh-port "$SSH_PORT" --ssh-key "$KEY")
        return 0
    fi
    warn "未检测到 SSH 公钥，需要为新系统设置 root 密码"
    read -rp "$(ui_prompt '输入新系统 root 密码（明文显示）: ')" PASSWORD
    read -rp "$(ui_prompt '再次输入密码: ')" PASSWORD2
    [ -n "$PASSWORD" ] && [ "$PASSWORD" = "$PASSWORD2" ] || { error "两次密码不一致或为空"; return 1; }
    REINSTALL_AUTH_ARGS=(--ssh-port "$SSH_PORT" --password "$PASSWORD")
}

reinstall_run_target() {
    local TARGET_LABEL="$1"; shift
    local SCRIPT="/root/reinstall.sh" ROOT_SOURCE ROOT_DISK VIRT ACTION="${1:-}" SSH_PORT
    if reinstall_is_container; then
        error "检测到容器环境，官方重装工具不支持 OpenVZ/LXC/Docker"
        return 1
    fi
    ROOT_SOURCE=$(findmnt -n -o SOURCE / 2>/dev/null || df / | awk 'END {print $1}')
    ROOT_DISK=$(lsblk -no PKNAME "$ROOT_SOURCE" 2>/dev/null | head -1)
    VIRT=$(systemd-detect-virt 2>/dev/null || echo "未知")
    print_header "系统重装最终确认"
    echo -e "  目标系统：${RED}${BOLD}$TARGET_LABEL${NC}"
    echo -e "  当前根分区：${BOLD}${ROOT_SOURCE:-未知}${NC}"
    echo -e "  系统磁盘：${BOLD}${ROOT_DISK:-自动识别}${NC}"
    echo -e "  虚拟化：${BOLD}${VIRT:-物理机}${NC}"
    echo ""
    error "继续操作将清空整块系统盘，现有系统和所有数据不可恢复"
    warn "请先确认商家控制台/VNC可用，并已在异地保存必要备份"
    echo ""
    read -rp "$(ui_prompt '输入 ERASE-ALL-DATA 确认: ')" CONFIRM
    [ "$CONFIRM" = "ERASE-ALL-DATA" ] || { warn "确认词不匹配，已取消"; return; }
    if [ "$ACTION" = "dd" ]; then
        SSH_PORT=$(get_config Port); SSH_PORT=${SSH_PORT:-22}
        REINSTALL_AUTH_ARGS=(--ssh-port "$SSH_PORT")
        warn "RAW 镜像保留镜像自身账户凭据，本脚本不会注入 SSH 公钥或 root 密码"
    else
        reinstall_collect_auth_args || return 1
    fi
    reinstall_download_engine "$SCRIPT" || return 1
    audit_action "启动系统重装：$TARGET_LABEL" DANGER
    echo ""; warn "即将交由第三方重装工具执行，请认真阅读其后续输出"
    sleep 2
    bash "$SCRIPT" "$@" "${REINSTALL_AUTH_ARGS[@]}"
}

system_reinstall_menu() {
    while true; do
        print_header "一键 DD / 系统重装"
        error "此功能会清空整块系统盘，仅适用于 KVM、VMware、Hyper-V 或独立服务器"
        ui_hint "使用 bin456789/reinstall 官方工具；OpenVZ/LXC 将被拒绝"
        echo ""; menu_div
        menu_pair "1" "Debian 12" "2" "Debian 13"
        menu_pair "3" "Ubuntu 22.04" "4" "Ubuntu 24.04"
        menu_pair "5" "Alpine 3.20" "6" "Alpine 3.22"
        menu_item "7" "Rocky Linux 9"
        menu_item "8" "DD 自定义 RAW 镜像" "$YELLOW"
        menu_item "9" "仅下载 / 更新重装工具"
        menu_item "0" "返回上级" "$RED"
        menu_div; echo ""
        read -rp "$(ui_prompt '选择目标系统 [0-9]: ')" CH
        case "$CH" in
            1) reinstall_run_target "Debian 12" debian 12 ;;
            2) reinstall_run_target "Debian 13" debian 13 ;;
            3) reinstall_run_target "Ubuntu 22.04" ubuntu 22.04 ;;
            4) reinstall_run_target "Ubuntu 24.04" ubuntu 24.04 ;;
            5) reinstall_run_target "Alpine 3.20" alpine 3.20 ;;
            6) reinstall_run_target "Alpine 3.22" alpine 3.22 ;;
            7) reinstall_run_target "Rocky Linux 9" rocky 9 ;;
            8)
                local IMG
                read -rp "$(ui_prompt '输入 RAW/VHD 镜像直链: ')" IMG
                echo "$IMG" | grep -qE '^https?://[^[:space:]]+$' || { error "镜像链接格式无效"; ui_pause; continue; }
                reinstall_run_target "自定义 RAW 镜像" dd --img "$IMG"
                ;;
            9) reinstall_download_engine /root/reinstall.sh ;;
            0) return ;;
            *) warn "无效选项"; sleep 1; continue ;;
        esac
        ui_pause
    done
}

software_reinstall_menu() {
    while true; do
        print_header "软件与系统重装"
        menu_item "1" "安装常用软件"
        menu_item "2" "一键 DD / 系统重装" "$RED"
        menu_item "0" "返回主菜单" "$RED"
        menu_div; echo ""
        read -rp "$(ui_prompt '选择功能 [0-2]: ')" CH
        case "$CH" in
            1) common_software_menu ;;
            2) system_reinstall_menu ;;
            0) return ;;
            *) warn "无效选项"; sleep 1 ;;
        esac
    done
}
# ============================================================
#  Docker 安装与容器管理
# ============================================================

docker_is_ready() {
    command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1
}

docker_status() {
    if ! command -v docker >/dev/null 2>&1; then echo not_installed
    elif docker info >/dev/null 2>&1; then echo running
    else echo stopped
    fi
}

docker_download_installer() {
    local DEST="$1" URL="https://get.docker.com"
    info "正在下载 Docker 官方安装脚本..."
    if command -v curl >/dev/null 2>&1; then
        curl -fL --retry 3 --connect-timeout 10 "$URL" -o "$DEST"
    elif command -v wget >/dev/null 2>&1; then
        wget -O "$DEST" "$URL"
    else
        error "需要先安装 curl 或 wget"
        return 1
    fi
    sh -n "$DEST" 2>/dev/null || { rm -f "$DEST"; error "Docker 安装脚本语法校验失败"; return 1; }
    chmod 700 "$DEST"
}

docker_download_file() {
    local URL="$1" DEST="$2"
    if command -v curl >/dev/null 2>&1; then
        curl -fL --retry 3 --connect-timeout 10 "$URL" -o "$DEST"
    elif command -v wget >/dev/null 2>&1; then
        wget -O "$DEST" "$URL"
    else
        error "需要先安装 curl 或 wget"
        return 1
    fi
}

docker_install() {
    local PM TMP SUDO_USER_NAME="${SUDO_USER:-}"
    if docker_is_ready; then
        info "Docker 已安装并正在运行：$(docker version --format '{{.Server.Version}}' 2>/dev/null)"
        return 0
    fi
    if command -v docker >/dev/null 2>&1; then
        info "检测到 Docker，正在尝试启动服务..."
        svc_enable docker
        svc_start docker || true
        if docker_is_ready; then
            info "Docker 服务已恢复运行"
            return 0
        fi
    fi
    PM=$(software_package_manager)
    confirm_change_preview "安装 Docker Engine" "来源：Docker 官方仓库" "同时安装 Docker Compose 插件" || return
    if [ "$PM" = "apk" ]; then
        info "正在通过 Alpine 软件仓库安装 Docker..."
        apk update && apk add --no-cache docker docker-cli-compose
        rc-update add docker default >/dev/null 2>&1 || true
    elif [ "$PM" = "opkg" ]; then
        error "暂不支持在 OpenWrt 上自动安装 Docker"
        return 1
    else
        TMP=$(mktemp "${TMPDIR:-/tmp}/docker-install.XXXXXX") || return 1
        docker_download_installer "$TMP" || { rm -f "$TMP"; return 1; }
        info "正在执行 Docker 官方安装脚本..."
        sh "$TMP"
        rm -f "$TMP"
    fi
    svc_enable docker
    svc_start docker || true
    if [ -n "$SUDO_USER_NAME" ] && [ "$SUDO_USER_NAME" != "root" ] && id "$SUDO_USER_NAME" >/dev/null 2>&1; then
        usermod -aG docker "$SUDO_USER_NAME" 2>/dev/null || true
        warn "用户 $SUDO_USER_NAME 已加入 docker 组，重新登录后生效"
    fi
    if docker_is_ready; then
        info "Docker 安装成功：$(docker version --format '{{.Server.Version}}' 2>/dev/null)"
        docker compose version 2>/dev/null || warn "Docker Compose 插件不可用，请检查软件源"
        audit_action "安装 Docker Engine" SUCCESS
    else
        error "Docker 已安装，但服务未能正常启动"
        audit_action "安装 Docker Engine" FAILED
        return 1
    fi
}

docker_require_ready() {
    docker_is_ready && return 0
    error "Docker 未安装或服务未运行，请先选择一键安装/修复"
    return 1
}

docker_list_containers() {
    docker ps -a --format 'table {{.Names}}\t{{.Image}}\t{{.Status}}\t{{.Ports}}'
}

docker_select_container() {
    local IDS=() NAMES=() ID NAME STATUS IMAGE I CH
    while IFS='|' read -r ID NAME STATUS IMAGE; do
        [ -n "$ID" ] || continue
        IDS+=("$ID"); NAMES+=("$NAME")
        printf '  %2d) %-20s %-18s %s\n' "${#IDS[@]}" "$NAME" "$STATUS" "$IMAGE"
    done < <(docker ps -a --format '{{.ID}}|{{.Names}}|{{.State}}|{{.Image}}')
    [ "${#IDS[@]}" -gt 0 ] || { warn "当前没有容器"; return 1; }
    echo ""
    read -rp "$(ui_prompt '选择容器编号（0 返回）: ')" CH
    [ "$CH" = "0" ] && return 1
    case "$CH" in ''|*[!0-9]*) error "编号无效"; return 1 ;; esac
    I=$((CH-1))
    [ "$I" -ge 0 ] && [ "$I" -lt "${#IDS[@]}" ] || { error "编号超出范围"; return 1; }
    DOCKER_SELECTED_ID="${IDS[$I]}"
    DOCKER_SELECTED_NAME="${NAMES[$I]}"
}

docker_container_details() {
    local ID="$1"
    docker inspect --format '名称: {{.Name}}
镜像: {{.Config.Image}}
状态: {{.State.Status}}
创建: {{.Created}}
重启策略: {{.HostConfig.RestartPolicy.Name}}
网络: {{range $k, $_ := .NetworkSettings.Networks}}{{$k}} {{end}}
挂载: {{range .Mounts}}{{.Source}} -> {{.Destination}} ({{.Type}}){{println}}{{end}}' "$ID" | sed 's#名称: /#名称: #'
}

docker_compose_available() {
    docker compose version >/dev/null 2>&1
}

docker_compose_basename() {
    local URL="$1" FILE
    FILE=${URL%%\?*}
    FILE=${FILE##*/}
    case "$FILE" in
        *.yml|*.yaml) printf '%s\n' "$FILE" ;;
        *) printf '%s\n' "compose.yaml" ;;
    esac
}

docker_compose_fetch_and_deploy() {
    local URL DEST_DIR FILE TMP PREVIEW
    docker_require_ready || return
    docker_compose_available || { error "缺少 Docker Compose 插件"; return 1; }
    read -rp "$(ui_prompt '输入 Compose 文件 URL: ')" URL
    echo "$URL" | grep -qE '^https?://[^[:space:]]+$' || { error "URL 格式无效"; return 1; }
    read -rp "$(ui_prompt '输入部署目录（默认 /opt/docker-compose）: ')" DEST_DIR
    DEST_DIR=${DEST_DIR:-/opt/docker-compose}
    mkdir -p "$DEST_DIR" || { error "无法创建目录：$DEST_DIR"; return 1; }
    FILE=$(docker_compose_basename "$URL")
    TMP=$(mktemp "${TMPDIR:-/tmp}/compose-file.XXXXXX") || return 1
    info "正在下载 Compose 文件..."
    if ! docker_download_file "$URL" "$TMP"; then
        rm -f "$TMP"
        return 1
    fi
    if ! docker compose -f "$TMP" config >/dev/null 2>&1; then
        rm -f "$TMP"
        error "Compose 文件校验失败"
        return 1
    fi
    PREVIEW=$(sed -n '1,120p' "$TMP")
    echo ""
    echo "$PREVIEW" | sed 's/^/  /'
    echo ""
    if ! confirm_change_preview "部署 Compose 文件" "来源：$URL" "目标目录：$DEST_DIR" "保存为：$FILE"; then
        rm -f "$TMP"
        return
    fi
    if ! cp "$TMP" "$DEST_DIR/$FILE"; then
        rm -f "$TMP"
        return 1
    fi
    rm -f "$TMP"
    if (cd "$DEST_DIR" && docker compose -f "$FILE" up -d --pull always); then
        info "Compose 项目已部署：$DEST_DIR/$FILE"
        audit_action "拉取并部署 Compose 文件：$URL -> $DEST_DIR/$FILE" SUCCESS
    else
        error "Compose 部署失败，请检查文件内容与镜像可用性"
        audit_action "拉取并部署 Compose 文件：$URL -> $DEST_DIR/$FILE" FAILED
        return 1
    fi
}

docker_inspect_label() {
    local VALUE
    VALUE=$(docker inspect --format "{{index .Config.Labels \"$2\"}}" "$1" 2>/dev/null || true)
    [ "$VALUE" = "<no value>" ] && VALUE=""
    printf '%s\n' "$VALUE"
}

docker_upgrade_container() {
    local ID="$1" NAME="$2" PROJECT SERVICE WORKDIR CONFIG_FILES IMAGE OLD_IMAGE NEW_IMAGE FILE
    PROJECT=$(docker_inspect_label "$ID" com.docker.compose.project)
    SERVICE=$(docker_inspect_label "$ID" com.docker.compose.service)
    WORKDIR=$(docker_inspect_label "$ID" com.docker.compose.project.working_dir)
    CONFIG_FILES=$(docker_inspect_label "$ID" com.docker.compose.project.config_files)
    if [ -n "$PROJECT" ] && [ -n "$SERVICE" ]; then
        docker_compose_available || { error "缺少 Docker Compose 插件"; return 1; }
        [ -d "$WORKDIR" ] || { error "Compose 工作目录不存在：${WORKDIR:-未记录}"; return 1; }
        confirm_change_preview "升级 Compose 容器 $NAME" "项目：$PROJECT" "服务：$SERVICE" "将拉取镜像并按 Compose 配置重建该服务" || return
        local ARGS=(-p "$PROJECT") FILES=()
        IFS=',' read -r -a FILES <<< "$CONFIG_FILES"
        for FILE in "${FILES[@]}"; do
            [ -f "$FILE" ] || FILE="$WORKDIR/$FILE"
            [ -f "$FILE" ] && ARGS+=(-f "$FILE")
        done
        if (cd "$WORKDIR" && docker compose "${ARGS[@]}" up -d --pull always "$SERVICE"); then
            info "Compose 服务 $SERVICE 已升级"
            audit_action "升级 Docker Compose：$PROJECT/$SERVICE" SUCCESS
        else
            error "Compose 升级失败，原容器不会被脚本主动删除"
            audit_action "升级 Docker Compose：$PROJECT/$SERVICE" FAILED
            return 1
        fi
        return
    fi

    IMAGE=$(docker inspect --format '{{.Config.Image}}' "$ID" 2>/dev/null)
    [ -n "$IMAGE" ] || { error "无法读取容器镜像"; return 1; }
    OLD_IMAGE=$(docker inspect --format '{{.Image}}' "$ID" 2>/dev/null)
    if ! confirm_change_preview "检查普通容器 $NAME 的镜像更新" "镜像：$IMAGE" "仅拉取镜像，不删除或重建现有容器"; then
        return
    fi
    if ! docker pull "$IMAGE"; then
        error "镜像拉取失败"
        return 1
    fi
    NEW_IMAGE=$(docker image inspect --format '{{.Id}}' "$IMAGE" 2>/dev/null)
    if [ "$OLD_IMAGE" = "$NEW_IMAGE" ]; then
        info "容器已使用当前最新镜像"
    else
        warn "新镜像已下载，但现有容器仍在运行旧镜像"
        warn "该容器不是 Compose 项目，需按原 docker run 参数重建；脚本不会冒险自动删除"
    fi
}

docker_container_action() {
    local ACTION="$1"
    docker_require_ready || return
    print_header "选择 Docker 容器"
    docker_select_container || return
    case "$ACTION" in
        inspect) docker_container_details "$DOCKER_SELECTED_ID" ;;
        start|stop|restart)
            docker "$ACTION" "$DOCKER_SELECTED_ID" && info "容器 $DOCKER_SELECTED_NAME 已执行 $ACTION"
            ;;
        logs) docker logs --tail 200 --timestamps "$DOCKER_SELECTED_ID" ;;
        shell)
            docker exec -it "$DOCKER_SELECTED_ID" sh 2>/dev/null || docker exec -it "$DOCKER_SELECTED_ID" bash
            ;;
        upgrade) docker_upgrade_container "$DOCKER_SELECTED_ID" "$DOCKER_SELECTED_NAME" ;;
        remove)
            if confirm_change_preview "删除容器 $DOCKER_SELECTED_NAME" "容器数据卷不会自动删除"; then
                docker rm -f "$DOCKER_SELECTED_ID" && info "容器已删除"
            fi
            ;;
    esac
    ui_pause
}

docker_menu() {
    while true; do
        local STATE LABEL COUNT="0"
        STATE=$(docker_status)
        case "$STATE" in
            running) LABEL="运行中"; COUNT=$(docker ps -a -q 2>/dev/null | wc -l | tr -d ' ') ;;
            stopped) LABEL="已安装 · 服务停止" ;;
            *) LABEL="未安装" ;;
        esac
        print_header "Docker 管理"
        echo -e "  状态：${BOLD}$LABEL${NC}    容器：${BOLD}$COUNT${NC}"
        echo ""; menu_div
        menu_pair "1" "一键安装 / 修复" "2" "查看全部容器"
        menu_pair "3" "查看容器详情" "4" "启动容器"
        menu_pair "5" "停止容器" "6" "重启容器"
        menu_pair "7" "查看最近日志" "8" "进入容器 Shell"
        menu_pair "9" "升级容器镜像" "d" "删除容器" "$CYAN" "$YELLOW"
        menu_item "10" "拉取 Compose 文件并部署" "$BLUE"
        menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
        menu_div; echo ""
        read -rp "$(ui_prompt '选择功能 [0-10 / d]: ')" CH
        case "$CH" in
            1) docker_install; ui_pause ;;
            2) docker_require_ready && docker_list_containers; ui_pause ;;
            3) docker_container_action inspect ;;
            4) docker_container_action start ;;
            5) docker_container_action stop ;;
            6) docker_container_action restart ;;
            7) docker_container_action logs ;;
            8) docker_container_action shell ;;
            9) docker_container_action upgrade ;;
            10) docker_compose_fetch_and_deploy; ui_pause ;;
            d|D) docker_container_action remove ;;
            0) return ;;
            00) exit 0 ;;
            *) warn "无效选项"; sleep 1 ;;
        esac
    done
}
# ══════════════════════════════════════════════════════════
#  脚本自我管理模块
# ══════════════════════════════════════════════════════════

SCRIPT_URL="https://raw.githubusercontent.com/chnnic/SSH-Hardening/refs/heads/main/SSH-Hardening.sh"
CHECKSUM_URL="https://raw.githubusercontent.com/chnnic/SSH-Hardening/refs/heads/main/SSH-Hardening.sh.sha256"
MANIFEST_URL="https://raw.githubusercontent.com/chnnic/SSH-Hardening/refs/heads/main/SSH-Hardening.manifest.json"
GITHUB_REF_URL="https://api.github.com/repos/chnnic/SSH-Hardening/git/ref/heads/main"
LOCAL_BIN_DIR="${LOCAL_BIN_DIR:-/usr/local/bin}"
LOCAL_SCRIPT="${LOCAL_SCRIPT:-${LOCAL_BIN_DIR}/vps-tools}"

file_sha256() {
    if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | awk '{print $1}'
    elif command -v shasum >/dev/null 2>&1; then shasum -a 256 "$1" | awk '{print $1}'
    elif command -v openssl >/dev/null 2>&1; then openssl dgst -sha256 "$1" | awk '{print $NF}'
    else return 1
    fi
}

self_atomic_replace() {
    local SOURCE="$1" DEST="$2" INSTALL_TMP
    mkdir -p "$(dirname "$DEST")" || return 1
    INSTALL_TMP="$(dirname "$DEST")/.vps-tools.update.$$"
    if ! install -m 755 "$SOURCE" "$INSTALL_TMP" || ! mv -f "$INSTALL_TMP" "$DEST"; then
        rm -f "$INSTALL_TMP"
        return 1
    fi
}

self_script_valid() {
    local FILE="$1"
    [ -f "$FILE" ] && [ -r "$FILE" ] || return 1
    bash -n "$FILE" >/dev/null 2>&1 || return 1
    grep -qE '^APP_VERSION="V[0-9]+\.[0-9]+(\.[0-9]+)?"' "$FILE" 2>/dev/null
}

self_resolve_script_source() {
    local CANDIDATE="${1:-$0}" RESOLVED
    case "$CANDIDATE" in
        -|/dev/fd/*|/dev/stdin|/proc/*/fd/*) return 1 ;;
    esac
    RESOLVED=$(readlink -f "$CANDIDATE" 2>/dev/null) || return 1
    case "$RESOLVED" in
        /dev/fd/*|/dev/stdin|/proc/*/fd/*) return 1 ;;
    esac
    self_script_valid "$RESOLVED" || return 1
    printf '%s\n' "$RESOLVED"
}

self_reconcile_tc_after_update() {
    local STATE_FILE="${TC_STATE_FILE:-/var/lib/vps-tools/tc-fq.state}"
    [ -s "$STATE_FILE" ] || return 0
    [ -f "$LOCAL_SCRIPT" ] || return 1
    VPS_TOOLS_TEST_MODE=0 BBR_TUNE_TEST_MODE=0 \
        bash "$LOCAL_SCRIPT" --bbr-reconcile-tc
}

self_fetch_script() {
    local DEST="$1" REMOTE_SHA FETCH_URL
    REMOTE_SHA=$(self_remote_main_sha || true)
    if [ -n "$REMOTE_SHA" ]; then
        FETCH_URL="https://raw.githubusercontent.com/chnnic/SSH-Hardening/${REMOTE_SHA}/SSH-Hardening.sh"
    else
        FETCH_URL="${SCRIPT_URL}?ts=$(date +%s)"
    fi
    curl -fsSL --retry 2 --retry-delay 1 \
        -H 'Cache-Control: no-cache' -H 'Pragma: no-cache' \
        "$FETCH_URL" -o "$DEST" 2>/dev/null || return 1
    self_script_valid "$DEST"
}

self_shortcut_path() {
    printf '%s/%s\n' "$LOCAL_BIN_DIR" "$1"
}

self_shortcut_owned() {
    local TARGET LINK
    TARGET=$(self_shortcut_path "$1")
    [ -L "$TARGET" ] || return 1
    LINK=$(readlink "$TARGET" 2>/dev/null || true)
    [ "$LINK" = "$LOCAL_SCRIPT" ]
}

self_managed_script_file() {
    [ -f "$1" ] || return 1
    grep -qE 'VPS 开荒脚本|APP_UI_TITLE="VPS TOOLS"' "$1" 2>/dev/null
}

self_install_shortcut() {
    local CMD="$1" TARGET LINK
    TARGET=$(self_shortcut_path "$CMD")
    mkdir -p "$LOCAL_BIN_DIR" 2>/dev/null || return 1

    if self_shortcut_owned "$CMD"; then
        ln -sfn "$LOCAL_SCRIPT" "$TARGET" 2>/dev/null || return 1
        info "系统命令 ${CMD} 已创建 ✓"
        return 0
    fi

    if [ -L "$TARGET" ]; then
        LINK=$(readlink "$TARGET" 2>/dev/null || true)
        if [ ! -e "$TARGET" ]; then
            warn "快捷键 ${CMD} 指向失效路径（${LINK:-未知}），正在修复"
        elif self_managed_script_file "$TARGET"; then
            warn "快捷键 ${CMD} 指向旧版 VPS Tools，正在修复"
        else
            warn "快捷键 ${CMD} 已被其他脚本占用（${LINK:-未知}），跳过"
            return 0
        fi
    elif [ -e "$TARGET" ]; then
        if self_managed_script_file "$TARGET"; then
            warn "快捷键 ${CMD} 是旧版 VPS Tools 文件，正在替换为软链接"
        else
            warn "快捷键 ${CMD} 是独立文件（非软链接），跳过以避免覆盖"
            return 0
        fi
    fi

    ln -sfn "$LOCAL_SCRIPT" "$TARGET" 2>/dev/null || return 1
    info "系统命令 ${CMD} 已创建 ✓"
}

self_remove_shortcut() {
    local CMD="$1" TARGET
    TARGET=$(self_shortcut_path "$CMD")
    if self_shortcut_owned "$CMD" || self_managed_script_file "$TARGET"; then
        rm -f "$TARGET"
    fi
}

self_manifest_value() {
    local FILE="$1" KEY="$2"
    sed -n 's/.*"'$KEY'"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' "$FILE" | head -1
}

self_remote_main_sha() {
    curl -fsSL --retry 2 --retry-delay 1 \
        -H 'Accept: application/vnd.github+json' \
        -H 'Cache-Control: no-cache' \
        -H 'Pragma: no-cache' \
        "$GITHUB_REF_URL" 2>/dev/null \
        | sed -n 's/.*"sha"[[:space:]]*:[[:space:]]*"\([0-9a-f]\{40\}\)".*/\1/p' \
        | head -1
}

# ── 安装脚本到本地（设置快捷键 v）────────────────────────
self_install() {
    print_header "安装脚本到本地"
    echo -e "  将脚本安装到 ${BOLD}${LOCAL_SCRIPT}${NC}"
    echo -e "  安装后输入 ${GREEN}v${NC} 或 ${GREEN}V${NC} 即可快速呼出"
    echo ""

    local SELF="" SOURCE="" DOWNLOAD_TMP=""
    SELF=$(self_resolve_script_source "$0" 2>/dev/null || true)
    if [ -n "$SELF" ]; then
        SOURCE="$SELF"
    else
        info "当前通过管道运行，正在下载完整脚本..."
        DOWNLOAD_TMP=$(mktemp "${TMPDIR:-/tmp}/vps-tools-install.XXXXXX") || {
            error "无法创建安装临时文件"; return 1
        }
        if self_fetch_script "$DOWNLOAD_TMP"; then
            SOURCE="$DOWNLOAD_TMP"
        elif self_script_valid /tmp/ssh_hardening.sh; then
            warn "下载失败，改用已校验的本地缓存"
            SOURCE="/tmp/ssh_hardening.sh"
        else
            rm -f "$DOWNLOAD_TMP"
            error "无法获取完整脚本，请检查网络"
            return 1
        fi
    fi

    if [ "$SOURCE" != "$LOCAL_SCRIPT" ]; then
        if ! self_atomic_replace "$SOURCE" "$LOCAL_SCRIPT"; then
            rm -f "$DOWNLOAD_TMP"
            error "脚本安装失败，原文件未被替换"
            return 1
        fi
    fi
    rm -f "$DOWNLOAD_TMP"
    self_script_valid "$LOCAL_SCRIPT" || {
        error "安装后的脚本完整性校验失败"
        return 1
    }
    chmod 755 "$LOCAL_SCRIPT" || { error "无法设置脚本执行权限"; return 1; }
    info "脚本已安装到 ${LOCAL_SCRIPT} ✓"

    # 创建系统级命令 v / V（最可靠，无需 source）。
    for _CMD in v V; do
        self_install_shortcut "$_CMD" || warn "快捷键 ${_CMD} 创建失败"
    done

    echo ""
    menu_div
    info "安装完成！新终端直接输入 ${BOLD}v${NC} 即可启动"
    echo -e "  ${DIM}软链接已创建，无需 source，新终端直接可用${NC}"
    menu_div
}

# ── 强制从 GitHub 更新脚本 ────────────────────────────────
self_update() {
    print_header "强制更新脚本"
    echo -e "  ${DIM}${SCRIPT_URL}${NC}"
    echo ""

    local TMP_FILE CHECKSUM_FILE MANIFEST_FILE; TMP_FILE="/tmp/vps_update_$$.sh"; CHECKSUM_FILE="/tmp/vps_update_$$.sha256"; MANIFEST_FILE="/tmp/vps_update_$$.manifest.json"

    info "正在下载最新版本..."
    local TRY EXPECTED_HASH ACTUAL_HASH DOWNLOAD_OK SCRIPT_FETCH_URL CHECKSUM_FETCH_URL MANIFEST_FETCH_URL TS REMOTE_SHA
    DOWNLOAD_OK=0
    REMOTE_SHA=$(self_remote_main_sha || true)
    if [ -n "$REMOTE_SHA" ]; then
        info "已锁定 GitHub main commit：${REMOTE_SHA:0:12}"
    fi
    for TRY in 1 2 3 4 5; do
        TS=$(date +%s)
        case "$TRY" in
            1)
                if [ -n "$REMOTE_SHA" ]; then
                    SCRIPT_FETCH_URL="https://raw.githubusercontent.com/chnnic/SSH-Hardening/${REMOTE_SHA}/SSH-Hardening.sh"
                    CHECKSUM_FETCH_URL="https://raw.githubusercontent.com/chnnic/SSH-Hardening/${REMOTE_SHA}/SSH-Hardening.sh.sha256"
                    MANIFEST_FETCH_URL="https://raw.githubusercontent.com/chnnic/SSH-Hardening/${REMOTE_SHA}/SSH-Hardening.manifest.json"
                else
                    SCRIPT_FETCH_URL="$SCRIPT_URL"
                    CHECKSUM_FETCH_URL="$CHECKSUM_URL"
                    MANIFEST_FETCH_URL="$MANIFEST_URL"
                fi
                ;;
            2)
                SCRIPT_FETCH_URL="$SCRIPT_URL"
                CHECKSUM_FETCH_URL="$CHECKSUM_URL"
                MANIFEST_FETCH_URL="$MANIFEST_URL"
                ;;
            3)
                SCRIPT_FETCH_URL="$SCRIPT_URL?ts=$TS"
                CHECKSUM_FETCH_URL="$CHECKSUM_URL?ts=$TS"
                MANIFEST_FETCH_URL="$MANIFEST_URL?ts=$TS"
                ;;
            4)
                SCRIPT_FETCH_URL="https://github.com/chnnic/SSH-Hardening/raw/refs/heads/main/SSH-Hardening.sh"
                CHECKSUM_FETCH_URL="https://github.com/chnnic/SSH-Hardening/raw/refs/heads/main/SSH-Hardening.sh.sha256"
                MANIFEST_FETCH_URL="https://github.com/chnnic/SSH-Hardening/raw/refs/heads/main/SSH-Hardening.manifest.json"
                ;;
            *)
                SCRIPT_FETCH_URL="https://cdn.jsdelivr.net/gh/chnnic/SSH-Hardening@main/SSH-Hardening.sh"
                CHECKSUM_FETCH_URL="https://cdn.jsdelivr.net/gh/chnnic/SSH-Hardening@main/SSH-Hardening.sh.sha256"
                MANIFEST_FETCH_URL="https://cdn.jsdelivr.net/gh/chnnic/SSH-Hardening@main/SSH-Hardening.manifest.json"
                ;;
        esac
        rm -f "$TMP_FILE" "$CHECKSUM_FILE" "$MANIFEST_FILE"
        if curl -fsSL --retry 2 --retry-delay 1 -H 'Cache-Control: no-cache' -H 'Pragma: no-cache' \
            "$SCRIPT_FETCH_URL" -o "$TMP_FILE" 2>/dev/null \
            && curl -fsSL --retry 2 --retry-delay 1 -H 'Cache-Control: no-cache' -H 'Pragma: no-cache' \
            "$CHECKSUM_FETCH_URL" -o "$CHECKSUM_FILE" 2>/dev/null; then
            EXPECTED_HASH=$(awk 'NR==1 {print $1}' "$CHECKSUM_FILE")
            if curl -fsSL --retry 1 --retry-delay 1 -H 'Cache-Control: no-cache' -H 'Pragma: no-cache' \
                "$MANIFEST_FETCH_URL" -o "$MANIFEST_FILE" 2>/dev/null; then
                local MANIFEST_HASH
                MANIFEST_HASH=$(self_manifest_value "$MANIFEST_FILE" sha256)
                [ -n "$MANIFEST_HASH" ] && EXPECTED_HASH="$MANIFEST_HASH"
            fi
            ACTUAL_HASH=$(file_sha256 "$TMP_FILE" 2>/dev/null || true)
            if [ -n "$ACTUAL_HASH" ] && [ "$ACTUAL_HASH" = "$EXPECTED_HASH" ]; then
                DOWNLOAD_OK=1
                break
            fi
        fi
        warn "下载或校验未通过，正在重试（${TRY}/5）"
        if [ -n "${ACTUAL_HASH:-}" ] || [ -n "${EXPECTED_HASH:-}" ]; then
            echo -e "  ${DIM}期望：${EXPECTED_HASH:-未知}  实际：${ACTUAL_HASH:-未知}${NC}"
        fi
        sleep 1
    done
    rm -f "$CHECKSUM_FILE" "$MANIFEST_FILE"
    if [ "$DOWNLOAD_OK" -ne 1 ]; then
        rm -f "$TMP_FILE"
        error "SHA256 校验失败，已拒绝更新"
        echo -e "  ${DIM}可先手动验证：curl -fsSL '${SCRIPT_URL}' -o /tmp/SSH-Hardening.sh && sha256sum /tmp/SSH-Hardening.sh${NC}"
        echo -e "  ${DIM}若 VPS 网络缓存异常，可临时手动覆盖：curl -fsSL '${SCRIPT_URL}' -o ${LOCAL_SCRIPT} && chmod +x ${LOCAL_SCRIPT}${NC}"
        audit_action "脚本更新SHA256校验失败" FAILED
        return
    fi
    info "SHA256 校验通过：${ACTUAL_HASH:0:16}..."

    # 验证语法
    if ! bash -n "$TMP_FILE" 2>/dev/null; then
        rm -f "$TMP_FILE"
        error "下载的文件语法有误，已取消更新"
        return
    fi

    # 版本对比
    local NEW_VER; NEW_VER=$(grep -oE 'V[0-9]+\.[0-9]+\.[0-9]+|V[0-9]+\.[0-9]+' "$TMP_FILE" | head -1)
    local CUR_VER; CUR_VER=$(grep -oE 'V[0-9]+\.[0-9]+\.[0-9]+|V[0-9]+\.[0-9]+' "${LOCAL_SCRIPT}" 2>/dev/null | head -1)
    echo -e "  当前版本：${BOLD}${CUR_VER:-未知}${NC}  →  最新版本：${GREEN}${BOLD}${NEW_VER:-未知}${NC}"
    echo ""

    # 覆盖前保留当前可执行版本
    if [ -f "$LOCAL_SCRIPT" ]; then
        mkdir -p "$VPS_VERSION_DIR" || { rm -f "$TMP_FILE"; error "无法创建版本备份目录"; return 1; }
        chmod 700 "$VPS_DATA_DIR" "$VPS_VERSION_DIR" 2>/dev/null || true
        local SAVED_VER
        SAVED_VER="${CUR_VER:-unknown}_$(date +%Y%m%d_%H%M%S).sh"
        cp "$LOCAL_SCRIPT" "$VPS_VERSION_DIR/$SAVED_VER" \
            && chmod 700 "$VPS_VERSION_DIR/$SAVED_VER" \
            || { rm -f "$TMP_FILE"; error "当前版本备份失败，已取消更新"; return 1; }
    fi
    # 同目录写入后原子替换，避免磁盘满或中断破坏当前脚本。
    if ! self_atomic_replace "$TMP_FILE" "$LOCAL_SCRIPT"; then
        rm -f "$TMP_FILE"
        error "更新文件安装失败，当前版本未被替换"
        audit_action "脚本更新安装失败" FAILED
        return 1
    fi
    cp "$TMP_FILE" /tmp/ssh_hardening.sh 2>/dev/null
    rm -f "$TMP_FILE"

    # 确保 v 命令还在
    self_install_shortcut v || warn "快捷键 v 修复失败"
    self_install_shortcut V || warn "快捷键 V 修复失败"

    # 由刚安装的新脚本执行，首次升级到带恢复功能的版本也能立即生效。
    self_reconcile_tc_after_update || warn "已保存的 tc 限速状态未能自动恢复，请进入 BBR 菜单检查"

    info "更新完成 ✓"
    audit_action "脚本更新 ${CUR_VER:-未知} 到 ${NEW_VER:-未知}" SUCCESS
    # 清理 DDNS 日志，保留最后 500 行（避免文件过大）
    if [ -f /var/log/ddns.log ]; then
        local _LL; _LL=$(wc -l < /var/log/ddns.log 2>/dev/null || echo 0)
        if [ "$_LL" -gt 500 ]; then
            tail -n 500 /var/log/ddns.log > /var/log/ddns.log.tmp \
                && mv /var/log/ddns.log.tmp /var/log/ddns.log
            info "DDNS 日志已清理（保留最近 500 条）✓"
        fi
    fi
    # 清理旧版写入的 alias（旧版本会写 alias v=，会拦截其他命令如 volss）
    for RC in /root/.bashrc /root/.bash_profile ~/.bashrc ~/.bash_profile ~/.zshrc; do
        [ -f "$RC" ] || continue
        if grep -q "VPS 开荒脚本快捷键" "$RC" 2>/dev/null; then
            grep -v "alias v=\|alias V=\|VPS 开荒脚本快捷键" "$RC" > "${RC}.tmp" \
                && mv "${RC}.tmp" "$RC"
            info "已清理旧版 alias（${RC}）✓"
        fi
    done
    # 清除更新提示，避免新版本启动后还显示旧提示
    rm -f /tmp/.vps_new_version 2>/dev/null
    warn "即将用新版本重启脚本..."
    sleep 1
    exec "$LOCAL_SCRIPT"
}

# ── 回滚到更新前版本 ──────────────────────────────────────
self_rollback() {
    print_header "回滚脚本版本"
    mkdir -p "$VPS_VERSION_DIR"
    local FILES=() f i=1
    while IFS= read -r f; do FILES+=("$f"); done < <(find "$VPS_VERSION_DIR" -maxdepth 1 -type f -name '*.sh' 2>/dev/null | sort -r)
    [ "${#FILES[@]}" -gt 0 ] || { warn "暂无可回滚版本"; return; }
    for f in "${FILES[@]}"; do echo -e "  ${GREEN}[$i]${NC} $(basename "$f")"; i=$((i+1)); done
    read -rp "  选择版本编号（回车取消）: " N
    [ -n "$N" ] || return
    echo "$N" | grep -qE '^[0-9]+$' || { warn "编号无效"; return; }
    [ "$N" -ge 1 ] && [ "$N" -le "${#FILES[@]}" ] || { warn "编号无效"; return; }
    local SELECTED="${FILES[$((N-1))]}"
    bash -n "$SELECTED" 2>/dev/null || { error "该版本语法校验失败"; return 1; }
    read -rp "  确认回滚到 $(basename "$SELECTED")？(y/N): " OK
    echo "$OK" | grep -qiE '^y(es)?$' || { warn "已取消"; return; }
    [ -f "$LOCAL_SCRIPT" ] && cp "$LOCAL_SCRIPT" "$VPS_VERSION_DIR/before_rollback_$(date +%Y%m%d_%H%M%S).sh"
    if ! cp "$SELECTED" "$LOCAL_SCRIPT" || ! chmod 700 "$LOCAL_SCRIPT"; then error "回滚失败"; return 1; fi
    audit_action "脚本回滚到 $(basename "$SELECTED")" SUCCESS
    info "版本回滚完成"
    warn "即将用回滚版本重启脚本..."
    sleep 1
    exec "$LOCAL_SCRIPT"
}

self_offline_bundle_create() {
    print_header "离线安装包"
    local SRC TMPDIR BUNDLE ARCHIVE
    SRC="${LOCAL_SCRIPT:-}"
    [ -f "$SRC" ] || SRC=$(self_resolve_script_source "$0" 2>/dev/null || true)
    [ -f "$SRC" ] || { error "找不到可打包的脚本"; return 1; }
    TMPDIR=$(mktemp -d "${TMPDIR:-/tmp}/vps-offline.XXXXXX") || return 1
    ARCHIVE="$TMPDIR/SSH-Hardening.sh"
    cp "$SRC" "$ARCHIVE" || { rm -rf "$TMPDIR"; error "复制脚本失败"; return 1; }
    if command -v sha256sum >/dev/null 2>&1; then
        sha256sum "$ARCHIVE" > "$TMPDIR/SSH-Hardening.sh.sha256"
    elif command -v shasum >/dev/null 2>&1; then
        shasum -a 256 "$ARCHIVE" > "$TMPDIR/SSH-Hardening.sh.sha256"
    else
        rm -rf "$TMPDIR"; error "缺少 SHA256 工具"; return 1
    fi
    BUNDLE="$VPS_DATA_DIR/offline/SSH-Hardening_offline_$(date +%Y%m%d_%H%M%S).tar.gz"
    mkdir -p "$VPS_DATA_DIR/offline" 2>/dev/null || { rm -rf "$TMPDIR"; error "无法创建离线包目录"; return 1; }
    tar -czf "$BUNDLE" -C "$TMPDIR" SSH-Hardening.sh SSH-Hardening.sh.sha256 || { rm -rf "$TMPDIR"; error "打包失败"; return 1; }
    rm -rf "$TMPDIR"
    chmod 600 "$BUNDLE" 2>/dev/null || true
    audit_action "生成离线安装包 $(basename "$BUNDLE")" SUCCESS
    info "离线安装包已生成：$BUNDLE"
    printf '%s\n' "$BUNDLE"
}

self_offline_bundle_install() {
    local PACKAGE="$1" TMPDIR FILE SHA_FILE EXPECTED ACTUAL DEST SRC_FILE
    [ -f "$PACKAGE" ] || { error "离线包不存在"; return 1; }
    TMPDIR=$(mktemp -d "${TMPDIR:-/tmp}/vps-offline-install.XXXXXX") || return 1
    case "$PACKAGE" in
        *.tar.gz|*.tgz)
            tar -xzf "$PACKAGE" -C "$TMPDIR" || { rm -rf "$TMPDIR"; error "解包失败"; return 1; }
            FILE=$(find "$TMPDIR" -maxdepth 1 -type f \( -name 'SSH-Hardening.sh' -o -name 'vps-tools.sh' -o -name '*.sh' \) | head -1)
            [ -n "$FILE" ] || FILE=$(find "$TMPDIR" -maxdepth 1 -type f ! -name '*.sha256' | head -1)
            SHA_FILE=$(find "$TMPDIR" -maxdepth 1 -type f -name '*.sha256' | head -1)
            [ -n "$FILE" ] || { rm -rf "$TMPDIR"; error "离线包中没有脚本文件"; return 1; }
            if [ -n "$SHA_FILE" ]; then
                EXPECTED=$(awk 'NR==1{print $1}' "$SHA_FILE")
                ACTUAL=$(file_sha256 "$FILE" 2>/dev/null || true)
                [ -n "$ACTUAL" ] && [ "$ACTUAL" = "$EXPECTED" ] || { rm -rf "$TMPDIR"; error "离线包校验失败"; return 1; }
            fi
            SRC_FILE="$FILE"
            ;;
        *.sh)
            SRC_FILE="$PACKAGE"
            bash -n "$SRC_FILE" 2>/dev/null || { rm -rf "$TMPDIR"; error "脚本语法校验失败"; return 1; }
            ;;
        *)
            rm -rf "$TMPDIR"
            error "仅支持 .sh / .tar.gz / .tgz 离线包"
            return 1
            ;;
    esac
    DEST="${LOCAL_SCRIPT:-/usr/local/bin/vps-tools}"
    mkdir -p "$(dirname "$DEST")" 2>/dev/null || { rm -rf "$TMPDIR"; error "无法创建安装目录"; return 1; }
    cp "$SRC_FILE" "$DEST" || { rm -rf "$TMPDIR"; error "安装失败"; return 1; }
    chmod 700 "$DEST" 2>/dev/null || true
    self_install_shortcut v || warn "快捷键 v 创建失败"
    self_install_shortcut V || warn "快捷键 V 创建失败"
    audit_action "离线安装脚本 $(basename "$PACKAGE")" SUCCESS
    info "离线安装完成：$DEST"
    rm -rf "$TMPDIR"
}

# ── 脚本管理菜单 ──────────────────────────────────────────
# ── 删除本地脚本和快捷键 ─────────────────────────────────
self_uninstall() {
    print_header "删除本地脚本和快捷键"
    warn "将删除以下内容："
    echo -e "  ${DIM}${LOCAL_SCRIPT}${NC}"
    echo -e "  ${DIM}$(self_shortcut_path v)${NC}"
    echo -e "  ${DIM}$(self_shortcut_path V)${NC}"
    echo -e "  ${DIM}各 shell 配置文件中的 alias v=...${NC}"
    echo ""
    read -rp "  确认删除？(Y/n，默认Y): " CONFIRM
    [ -z "$CONFIRM" ] && CONFIRM="y"
    if ! echo "$CONFIRM" | grep -qiE '^y(es)?$'; then warn "已取消"; return; fi

    # 删除本地脚本
    rm -f "$LOCAL_SCRIPT" && info "已删除 ${LOCAL_SCRIPT} ✓"

    # 删除系统命令
    self_remove_shortcut v
    self_remove_shortcut V
    info "已删除 VPS Tools 管理的系统命令 v/V ✓"

    # 清理 shell 配置文件中可能残留的旧版 alias
    for RC in /root/.bashrc /root/.bash_profile ~/.bashrc ~/.bash_profile ~/.zshrc; do
        [ -f "$RC" ] || continue
        if grep -q "VPS 开荒脚本快捷键" "$RC" 2>/dev/null; then
            grep -v "alias v=\|alias V=\|VPS 开荒脚本快捷键" "$RC" > "${RC}.tmp" \
                && mv "${RC}.tmp" "$RC"
            info "已清理旧版 alias（${RC}）✓"
        fi
    done

    echo ""
    info "清理完成，快捷键 v 已移除"
    warn "当前会话仍可使用 alias，重新登录后完全生效"
    ui_pause
    return
}

# ── 首次运行检测是否已安装快捷键 ─────────────────────────
self_check_first_run() {
    # 已安装则跳过
    self_shortcut_owned v && return
    [ -f "$LOCAL_SCRIPT" ] && return

    print_header "首次运行设置"
    echo -e "  ${YELLOW}检测到脚本未安装到本地${NC}"
    echo -e "  安装后可随时输入 ${BOLD}v${NC} 快速启动"
    echo ""
    menu_div
    menu_item "1" "立即安装  ${DIM}推荐${NC}"
    menu_item "0" "跳过并进入主菜单" "$RED"
    menu_div
    echo ""
    read -rp "$(ui_prompt '选择操作 [0-1]: ')" CH
    case "$CH" in
        1)
            self_install
            ui_pause
            ;;
        *) ;;
    esac
}

self_manage_menu() {
    while true; do
        print_header "脚本管理"

        local IS_INSTALLED=false
        local CUR_VER=""
        if [ -f "$LOCAL_SCRIPT" ]; then
            IS_INSTALLED=true
            CUR_VER=$(grep -oE 'V[0-9]+\.[0-9]+\.[0-9]+|V[0-9]+\.[0-9]+' "$LOCAL_SCRIPT" | head -1)
        fi
        local HAS_CMD=false
        self_shortcut_owned v && HAS_CMD=true

        echo -e "  本地路径：${BOLD}${LOCAL_SCRIPT}${NC}"
        if [ "$IS_INSTALLED" = true ]; then
            echo -e "  状  态  ：${GREEN}${BOLD}已安装${NC}  版本：${BOLD}${CUR_VER:-未知}${NC}"
        else
            echo -e "  状  态  ：${YELLOW}${BOLD}未安装${NC}"
        fi
        echo -e "  快捷键 v：${BOLD}$([ "$HAS_CMD" = true ] && echo "${GREEN}已设置${NC}" || echo "${YELLOW}未设置${NC}")${NC}"
        echo ""
        menu_div
        menu_pair "1" "安装并设置快捷键" "2" "更新到最新版"
        menu_pair "3" "卸载本地脚本" "4" "回滚历史版本" "$YELLOW" "$YELLOW"
        menu_pair "5" "离线安装包" "0" "返回主菜单" "$CYAN" "$RED"
        menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
        menu_div
        echo ""
        read -rp "$(ui_prompt '选择操作 [0-5]: ')" CH

        case "$CH" in
            1) self_install ;;
            2) self_update ;;
            3) self_uninstall ;;
            4) self_rollback ;;
            5)
                while true; do
                    print_header "离线安装包"
                    menu_item "1" "生成离线安装包" "$GREEN"
                    menu_item "2" "安装本地离线包" "$YELLOW"
                    menu_item "0" "返回上级" "$RED"
                    menu_div; echo ""
                    read -rp "$(ui_prompt '选择操作 [0-2]: ')" OCH
                    case "$OCH" in
                        1) self_offline_bundle_create; ui_pause ;;
                        2)
                            local PKG
                            read -rp "$(ui_prompt '输入离线包路径 (.sh/.tar.gz): ')" PKG
                            [ -n "$PKG" ] && self_offline_bundle_install "$PKG"
                            ui_pause
                            ;;
                        0) break ;;
                        *) warn "无效选项"; sleep 1 ;;
                    esac
                done
                ;;
            0) return ;;
            00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
            *) warn "无效选项"; sleep 1; continue ;;
        esac

        [ "${CH}" != "0" ] && [ "${CH}" != "3" ] && ui_pause
    done
}
# ══════════════════════════════════════════════════════════
#  NFT 转发管理模块（端口转发 / DDNS / 访问控制）
# ══════════════════════════════════════════════════════════
NFT_CONFIG_FILE="${NFT_CONFIG_FILE:-/etc/nftables.conf}"
NFT_MANAGED_FILE="${NFT_MANAGED_FILE:-/etc/nftables.d/vps-tools-nftpf.nft}"
NFT_INCLUDE_MARKER="# VPS_TOOLS_NFTPF_INCLUDE"
NFT_STATE_DIR="${NFT_STATE_DIR:-/etc/nft-port-forward}"
NFT_RULES_FILE="${NFT_RULES_FILE:-$NFT_STATE_DIR/rules.db}"
NFT_ACCESS_FILE="${NFT_ACCESS_FILE:-$NFT_STATE_DIR/access.conf}"
NFT_RENDER_VERSION="1"
NFT_TRACK_TIMEOUT="${NFT_TRACK_TIMEOUT:-30m}"
NFT_DDNS_TIMER_FILE="/etc/systemd/system/nftpf-ddns.timer"
NFT_DDNS_SERVICE_FILE="/etc/systemd/system/nftpf-ddns.service"

# ── 基础工具 ──────────────────────────────────────────────
nft_ensure_state_dir() {
    mkdir -p "$NFT_STATE_DIR"
    touch "$NFT_RULES_FILE"
    [ -f "$NFT_ACCESS_FILE" ] || echo "mode=off" > "$NFT_ACCESS_FILE"
}

nft_main_config_prepare() {
    local tmp legacy=false
    mkdir -p "$(dirname "$NFT_CONFIG_FILE")" "$(dirname "$NFT_MANAGED_FILE")" || return 1
    tmp=$(mktemp "${NFT_CONFIG_FILE}.tmp.XXXXXX") || return 1
    if [ -f "$NFT_CONFIG_FILE" ] && grep -q '^# NFTPF_RENDER_VERSION=' "$NFT_CONFIG_FILE" 2>/dev/null; then
        legacy=true
        cp "$NFT_CONFIG_FILE" "${NFT_CONFIG_FILE}.bak.pre-vps-tools-include" 2>/dev/null || true
        printf '%s\n\n' '#!/usr/sbin/nft -f' > "$tmp"
    elif [ -f "$NFT_CONFIG_FILE" ]; then
        grep -Fv -- "$NFT_INCLUDE_MARKER" "$NFT_CONFIG_FILE" > "$tmp" || true
    else
        printf '%s\n\n' '#!/usr/sbin/nft -f' > "$tmp"
    fi
    if ! grep -Fq -- "$NFT_MANAGED_FILE" "$tmp" 2>/dev/null; then
        printf '\ninclude "%s" %s\n' "$NFT_MANAGED_FILE" "$NFT_INCLUDE_MARKER" >> "$tmp"
    fi
    chmod 755 "$tmp" 2>/dev/null || true
    mv "$tmp" "$NFT_CONFIG_FILE" || { rm -f "$tmp"; return 1; }
    [ "$legacy" = true ] && info "已将旧版独占配置迁移为独立 include，原文件已备份"
    return 0
}

nft_main_config_remove_include() {
    local tmp
    [ -f "$NFT_CONFIG_FILE" ] || return 0
    tmp=$(mktemp "${NFT_CONFIG_FILE}.tmp.XXXXXX") || return 1
    grep -Fv -- "$NFT_INCLUDE_MARKER" "$NFT_CONFIG_FILE" > "$tmp" || true
    mv "$tmp" "$NFT_CONFIG_FILE" || { rm -f "$tmp"; return 1; }
}

nft_main_has_external_rules() {
    [ -f "$NFT_CONFIG_FILE" ] || return 1
    sed -e '/^[[:space:]]*$/d' -e '/^[[:space:]]*#/d' "$NFT_CONFIG_FILE" | grep -q .
}

nft_install() {
    command -v nft &>/dev/null && return 0
    info "正在安装 nftables..."
    if command -v apt-get &>/dev/null; then
        apt-get update -qq 2>/dev/null
        apt-get install -y nftables 2>/dev/null
    elif command -v apk &>/dev/null; then
        apk add --no-cache nftables 2>/dev/null
    elif command -v yum &>/dev/null; then
        yum install -y nftables 2>/dev/null
    elif command -v dnf &>/dev/null; then
        dnf install -y nftables 2>/dev/null
    fi
    command -v nft &>/dev/null
}


nft_uninstall() {
    print_header "卸载 nftables"
    echo -e "  ${RED}${BOLD}⚠ 警告：卸载将执行以下操作：${NC}"
    echo -e "  ${DIM}1. 清空所有 NFT 转发规则${NC}"
    echo -e "  ${DIM}2. 删除访问控制配置${NC}"
    echo -e "  ${DIM}3. 关闭 DDNS 自动刷新 timer${NC}"
    echo -e "  ${DIM}4. 停止并删除 nftables 服务${NC}"
    echo -e "  ${DIM}5. 卸载 nftables 软件包${NC}"
    echo ""
    warn "如果你的防火墙依赖 nftables（如 firewalld 后端），卸载后会失去保护！"
    read -rp "  确认卸载？(y/N，默认N): " c
    [ -z "$c" ] && c="n"
    echo "$c" | grep -qiE '^y(es)?$' || { warn "已取消"; return; }

    # 1. 关闭 DDNS timer
    if command -v systemctl &>/dev/null; then
        systemctl disable --now nftpf-ddns.timer &>/dev/null || true
        systemctl disable --now nftpf-ddns.service &>/dev/null || true
    fi
    rm -f "$NFT_DDNS_TIMER_FILE" "$NFT_DDNS_SERVICE_FILE"

    # 2. 只清理本脚本托管的表，不触碰系统已有 nftables 防火墙规则
    if command -v nft &>/dev/null; then
        nft delete table ip nftpf_access 2>/dev/null || true
        nft delete table ip6 nftpf_access 2>/dev/null || true
        nft delete table ip nftpf_nat 2>/dev/null || true
        nft delete table ip6 nftpf_nat 2>/dev/null || true
    fi

    # 3. 只移除脚本自己的持久化 include，保留用户配置。
    rm -f "$NFT_MANAGED_FILE"
    nft_main_config_remove_include || warn "无法从主配置移除 VPS Tools include"

    # 4. 删除状态目录
    rm -rf "$NFT_STATE_DIR"

    # 主配置仍有其它规则时保留 nftables 服务和软件包。
    if nft_main_has_external_rules; then
        warn "检测到用户自有 nftables 配置，已保留 nftables 服务和软件包"
        info "VPS Tools NFT 转发模块已卸载 ✓"
        return 0
    fi

    # 5. 没有其它规则时停止服务并卸载软件包。
    if systemd_available; then
        systemctl stop nftables &>/dev/null || true
        systemctl disable nftables &>/dev/null || true
    elif command -v rc-service &>/dev/null; then
        rc-service nftables stop 2>/dev/null || true
        rc-update del nftables default 2>/dev/null || true
    fi

    info "正在卸载 nftables 软件包..."
    if command -v apt-get &>/dev/null; then
        apt-get remove -y nftables 2>/dev/null
    elif command -v apk &>/dev/null; then
        apk del nftables 2>/dev/null
    elif command -v yum &>/dev/null; then
        yum remove -y nftables 2>/dev/null
    elif command -v dnf &>/dev/null; then
        dnf remove -y nftables 2>/dev/null
    fi

    if ! command -v systemctl &>/dev/null || ! command -v nft &>/dev/null; then
        info "nftables 卸载完成 ✓"
    else
        warn "卸载命令已执行，但 nft 命令仍存在（可能是依赖保留）"
    fi
}

nft_enable_ip_forward() {
    sysctl -w net.ipv4.ip_forward=1 >/dev/null 2>&1
    sysctl -w net.ipv6.conf.all.forwarding=1 >/dev/null 2>&1
    if [ -f /etc/sysctl.conf ]; then
        grep -q '^net.ipv4.ip_forward=1' /etc/sysctl.conf \
            || echo 'net.ipv4.ip_forward=1' >> /etc/sysctl.conf
        grep -q '^net.ipv6.conf.all.forwarding=1' /etc/sysctl.conf \
            || echo 'net.ipv6.conf.all.forwarding=1' >> /etc/sysctl.conf
    fi
}

# ── IP / 端口 校验 ────────────────────────────────────────
nft_is_ipv4() {
    echo "$1" | grep -qE '^([0-9]{1,3}\.){3}[0-9]{1,3}$' || return 1
    local IFS='.'
    set -- $1
    for p in "$@"; do [ "$p" -ge 0 ] && [ "$p" -le 255 ] || return 1; done
}

nft_is_ipv6() {
    [ "${1#*:}" != "$1" ] || return 1
    echo "$1" | grep -qE '^[0-9A-Fa-f:.]+$'
}

nft_is_hostname() {
    [ ${#1} -le 253 ] || return 1
    echo "$1" | grep -qE '^[A-Za-z0-9][A-Za-z0-9.-]*[A-Za-z0-9]$'
}

nft_classify() {
    if nft_is_ipv4 "$1"; then echo "ipv4"
    elif nft_is_ipv6 "$1"; then echo "ipv6"
    elif nft_is_hostname "$1"; then echo "domain"
    else echo "invalid"
    fi
}

nft_check_port() {
    [[ "$1" =~ ^[0-9]+$ ]] && [ "$1" -ge 1 ] && [ "$1" -le 65535 ]
}

nft_resolve_domain() {
    local domain="$1" family="$2" result=""
    if [ "$family" = "ipv4" ]; then
        result=$(getent ahostsv4 "$domain" 2>/dev/null | awk '{print $1; exit}')
        nft_is_ipv4 "$result" && echo "$result" && return 0
    else
        result=$(getent ahostsv6 "$domain" 2>/dev/null | awk '{print $1; exit}')
        nft_is_ipv6 "$result" && echo "$result" && return 0
    fi
    return 1
}

# ── 规则数据库读写 ────────────────────────────────────────
# 格式: id|family|listen_ip|lstart|lend|target_type|target_host|resolved|tstart|tend|mode
nft_next_rule_id() {
    local max=0 id
    while IFS='|' read -r id _; do
        [[ -z "$id" || "$id" = \#* ]] && continue
        [[ "$id" =~ ^[0-9]+$ ]] && [ "$id" -gt "$max" ] && max=$id
    done < "$NFT_RULES_FILE"
    echo $((max + 1))
}

nft_get_access_mode() {
    local m
    m=$(grep -m1 '^mode=' "$NFT_ACCESS_FILE" 2>/dev/null | cut -d= -f2)
    case "$m" in whitelist|blacklist|off) echo "$m" ;; *) echo "off" ;; esac
}

nft_access_entries_for() {
    grep "^entry=$1|" "$NFT_ACCESS_FILE" 2>/dev/null | cut -d'|' -f2-
}

nft_format_access_for() {
    local family="$1" out="" sep="" entry
    while IFS= read -r entry; do
        [ -n "$entry" ] || continue
        out="${out}${sep}${entry}"; sep=", "
    done < <(nft_access_entries_for "$family")
    echo "$out"
}

nft_rules_has_family() {
    local family="$1" line
    while IFS= read -r line; do
        [[ -z "$line" || "$line" = \#* ]] && continue
        case "$line" in
            *"|$family|"*) return 0 ;;
        esac
    done < "$NFT_RULES_FILE"
    return 1
}

# ── 生成 nftables 配置 ────────────────────────────────────
nft_build_dnat() {
    local family="$1" ip="$2" port="$3"
    if [ "$family" = "ipv6" ] && [ -n "$port" ]; then
        echo "[$ip]:$port"
    elif [ -n "$port" ]; then
        echo "$ip:$port"
    else
        echo "$ip"
    fi
}

nft_build_port_map() {
    local lstart="$1" lend="$2" tstart="$3"
    local lp="$lstart" rp="$tstart" first=1 out="{ "
    while [ "$lp" -le "$lend" ]; do
        [ "$first" -eq 1 ] && first=0 || out="$out, "
        out="${out}${lp} : ${rp}"
        lp=$((lp+1)); rp=$((rp+1))
    done
    echo "$out }"
}

nft_render_rule_line() {
    local id="$1" family="$2" lip="$3" ls="$4" le="$5" \
          ttype="$6" thost="$7" tip="$8" ts="$9" te="${10}" mode="${11}"
    local listen_match="" port_expr dnat map_str

    if [ -n "$lip" ]; then
        if [ "$family" = "ipv6" ]; then listen_match="ip6 daddr $lip "
        else listen_match="ip daddr $lip "; fi
    fi

    if [ "$ls" = "$le" ]; then
        port_expr="$ls"
    else
        port_expr="{ $ls-$le }"
    fi

    case "$mode" in
        single)
            dnat=$(nft_build_dnat "$family" "$tip" "$ts")
            echo "        ${listen_match}meta l4proto {tcp, udp} th dport $port_expr dnat to $dnat"
            ;;
        range_1_to_1)
            dnat=$(nft_build_dnat "$family" "$tip" "")
            echo "        ${listen_match}meta l4proto {tcp, udp} th dport $port_expr dnat to $dnat"
            ;;
        range_offset)
            dnat=$(nft_build_dnat "$family" "$tip" "")
            map_str=$(nft_build_port_map "$ls" "$le" "$ts")
            echo "        ${listen_match}meta l4proto {tcp, udp} th dport $port_expr dnat to $dnat : th dport map $map_str"
            ;;
    esac
}

nft_render_rules_for() {
    local family="$1" line
    while IFS='|' read -r id f lip ls le ttype thost tip ts te mode; do
        [[ -z "$id" || "$id" = \#* ]] && continue
        [ "$f" = "$family" ] || continue
        nft_render_rule_line "$id" "$f" "$lip" "$ls" "$le" "$ttype" "$thost" "$tip" "$ts" "$te" "$mode"
    done < "$NFT_RULES_FILE"
}

nft_render_access_table_for() {
    local family="$1" mode entries tf addr addr_type
    mode=$(nft_get_access_mode)
    [ "$mode" != "off" ] || return 0
    nft_rules_has_family "$family" || return 0

    entries=$(nft_format_access_for "$family")
    [ "$mode" = "blacklist" ] && [ -z "$entries" ] && return 0

    if [ "$family" = "ipv6" ]; then
        tf="ip6"; addr="ip6"; addr_type="ipv6_addr"
    else
        tf="ip"; addr="ip"; addr_type="ipv4_addr"
    fi

    echo "table $tf nftpf_access {"
    if [ -n "$entries" ]; then
        cat <<EOF
    set sources {
        type $addr_type
        flags interval
        elements = { $entries }
    }
EOF
    fi
    echo "    chain prerouting {"
    echo "        type filter hook prerouting priority -101; policy accept;"
    echo "        # NFTPF_ACCESS_MODE=$mode"

    # 为每条规则生成访问控制匹配
    local id f lip ls le ttype thost tip ts te _md match
    while IFS='|' read -r id f lip ls le ttype thost tip ts te _md; do
        [[ -z "$id" || "$id" = \#* ]] && continue
        [ "$f" = "$family" ] || continue
        # 构造匹配（不带 dnat 的版本）
        if [ -n "$lip" ]; then
            if [ "$f" = "ipv6" ]; then match="ip6 daddr $lip "
            else match="ip daddr $lip "; fi
        else
            match=""
        fi
        if [ "$ls" = "$le" ]; then
            match="${match}meta l4proto {tcp, udp} th dport $ls"
        else
            match="${match}meta l4proto {tcp, udp} th dport { $ls-$le }"
        fi
        if [ "$mode" = "whitelist" ]; then
            if [ -n "$entries" ]; then
                echo "        $match $addr saddr != @sources drop"
            else
                echo "        $match drop"
            fi
        else
            echo "        $match $addr saddr @sources drop"
        fi
    done < "$NFT_RULES_FILE"
    echo "    }"
    echo "}"
    echo ""
}

nft_generate_config() {
    cat <<EOF
#!/usr/sbin/nft -f
# NFTPF_RENDER_VERSION=$NFT_RENDER_VERSION

EOF
    nft_render_access_table_for "ipv4"
    nft_render_access_table_for "ipv6"

    cat <<EOF
table ip nftpf_nat {
    chain prerouting {
        type nat hook prerouting priority dstnat; policy accept;
EOF
    nft_render_rules_for "ipv4"
    cat <<EOF
    }
    chain postrouting {
        type nat hook postrouting priority srcnat; policy accept;
        ct status dnat masquerade
    }
}

table ip6 nftpf_nat {
    chain prerouting {
        type nat hook prerouting priority dstnat; policy accept;
EOF
    nft_render_rules_for "ipv6"
    cat <<EOF
    }
    chain postrouting {
        type nat hook postrouting priority srcnat; policy accept;
        ct status dnat masquerade
    }
}
EOF
}

nft_write_and_apply() {
    local candidate batch main_backup managed_backup main_existed=no managed_existed=no table family
    mkdir -p "$(dirname "$NFT_MANAGED_FILE")" || return 1
    candidate=$(mktemp "${NFT_MANAGED_FILE}.tmp.XXXXXX") || return 1
    batch=$(mktemp) || { rm -f "$candidate"; return 1; }
    nft_generate_config > "$candidate" || { rm -f "$candidate" "$batch"; return 1; }

    for family in ip ip6; do
        for table in nftpf_access nftpf_nat; do
            nft list table "$family" "$table" &>/dev/null && printf 'delete table %s %s\n' "$family" "$table" >> "$batch"
        done
    done
    cat "$candidate" >> "$batch"
    if ! nft -c -f "$batch" 2>&1; then
        rm -f "$candidate" "$batch"
        error "nftables 配置语法校验失败"
        return 1
    fi

    main_backup=$(mktemp) || { rm -f "$candidate" "$batch"; return 1; }
    managed_backup=$(mktemp) || { rm -f "$candidate" "$batch" "$main_backup"; return 1; }
    if [ -f "$NFT_CONFIG_FILE" ]; then cp "$NFT_CONFIG_FILE" "$main_backup" || return 1; main_existed=yes; fi
    if [ -f "$NFT_MANAGED_FILE" ]; then cp "$NFT_MANAGED_FILE" "$managed_backup" || return 1; managed_existed=yes; fi

    mv "$candidate" "$NFT_MANAGED_FILE" || { rm -f "$candidate" "$batch" "$main_backup" "$managed_backup"; return 1; }
    chmod 755 "$NFT_MANAGED_FILE" 2>/dev/null || true
    if ! nft_main_config_prepare || ! nft -f "$batch" &>/dev/null; then
        [ "$managed_existed" = yes ] && cp "$managed_backup" "$NFT_MANAGED_FILE" || rm -f "$NFT_MANAGED_FILE"
        [ "$main_existed" = yes ] && cp "$main_backup" "$NFT_CONFIG_FILE" || rm -f "$NFT_CONFIG_FILE"
        rm -f "$batch" "$main_backup" "$managed_backup"
        error "nftables 配置应用失败，持久化文件已恢复"
        return 1
    fi
    rm -f "$batch" "$main_backup" "$managed_backup"
    if systemd_available; then
        systemctl enable nftables &>/dev/null || warn "nftables 开机自启设置失败"
    elif command -v rc-update &>/dev/null; then
        rc-update add nftables default 2>/dev/null || warn "nftables 开机自启设置失败"
    fi
    info "nftables 配置已应用 ✓"
}

# ── 规则展示 ──────────────────────────────────────────────
nft_display_host() {
    nft_is_ipv6 "$1" && echo "[$1]" || echo "$1"
}

nft_rule_summary() {
    local id="$1" family="$2" lip="$3" ls="$4" le="$5" \
          ttype="$6" thost="$7" tip="$8" ts="$9" te="${10}" mode="${11}"
    local listen_disp target_disp mode_text note=""

    [ -z "$lip" ] && lip="$([ "$family" = "ipv6" ] && echo "::" || echo "0.0.0.0")"
    if [ "$ls" = "$le" ]; then
        listen_disp="$(nft_display_host "$lip"):$ls"
    else
        listen_disp="$(nft_display_host "$lip"):${ls}-${le}"
    fi

    [ "$ttype" = "domain" ] && note=" (${tip})"
    if [ "$ts" = "$te" ]; then
        target_disp="$(nft_display_host "$thost"):${ts}${note}"
    else
        target_disp="$(nft_display_host "$thost"):${ts}-${te}${note}"
    fi

    case "$mode" in
        single) mode_text="单端口" ;;
        range_1_to_1) mode_text="端口段1:1" ;;
        range_offset) mode_text="端口段偏移" ;;
    esac

    echo "[${id}] [${family}] [${mode_text}] ${listen_disp} → ${target_disp}"
}

nft_list_rules() {
    local count=0 line
    while IFS='|' read -r id f lip ls le ttype thost tip ts te mode; do
        [[ -z "$id" || "$id" = \#* ]] && continue
        nft_rule_summary "$id" "$f" "$lip" "$ls" "$le" "$ttype" "$thost" "$tip" "$ts" "$te" "$mode"
        count=$((count + 1))
    done < "$NFT_RULES_FILE"
    [ "$count" -gt 0 ]
}

nft_find_rule() {
    local target_id="$1" line
    while IFS= read -r line; do
        [[ -z "$line" || "$line" = \#* ]] && continue
        local id="${line%%|*}"
        if [ "$id" = "$target_id" ]; then
            NFT_FOUND_RULE="$line"
            return 0
        fi
    done < "$NFT_RULES_FILE"
    return 1
}

# ── 添加规则 ──────────────────────────────────────────────
nft_choose_family() {
    local lip="$1" thost="$2" choice="$3"
    if [ -n "$lip" ]; then
        echo "$(nft_classify "$lip")"
        return
    fi
    case "$choice" in
        4|ipv4) echo "ipv4"; return ;;
        6|ipv6) echo "ipv6"; return ;;
    esac
    local k; k=$(nft_classify "$thost")
    case "$k" in
        ipv4|ipv6) echo "$k" ;;
        domain)
            if nft_resolve_domain "$thost" ipv4 >/dev/null 2>&1; then echo "ipv4"
            elif nft_resolve_domain "$thost" ipv6 >/dev/null 2>&1; then echo "ipv6"
            else echo "invalid"; fi
            ;;
        *) echo "invalid" ;;
    esac
}

nft_add_rule() {
    local mode="$1"
    local lip ls le thost ts te family resolved_ip
    print_header "添加端口转发规则（${mode}）"

    read -rp "  监听 IP（留空=所有，IPv6 输入 ::）: " lip
    [ "$lip" = "0.0.0.0" ] || [ "$lip" = "::" ] && lip=""

    if [ "$mode" = "single" ]; then
        read -rp "  监听端口: " ls
        nft_check_port "$ls" || { error "端口无效"; return; }
        le="$ls"
    else
        read -rp "  监听起始端口: " ls
        read -rp "  监听结束端口: " le
        nft_check_port "$ls" || { error "起始端口无效"; return; }
        nft_check_port "$le" || { error "结束端口无效"; return; }
        [ "$ls" -le "$le" ] || { error "起始端口不能大于结束端口"; return; }
    fi

    read -rp "  目标 IP / 域名: " thost
    [ -z "$thost" ] && { warn "已取消"; return; }
    [ "$(nft_classify "$thost")" != "invalid" ] || { error "目标地址格式无效"; return; }

    if [ "$mode" = "single" ]; then
        read -rp "  目标端口（留空=同监听端口）: " ts
        [ -z "$ts" ] && ts="$ls"
        nft_check_port "$ts" || { error "目标端口无效"; return; }
        te="$ts"
        local rule_mode="single"
    else
        echo ""
        menu_item "1" "1:1 映射  ${DIM}目标端口段等于监听端口段${NC}"
        menu_item "2" "端口段偏移  ${DIM}指定目标起始端口${NC}"
        read -rp "  选择映射模式 [1/2]，默认 1: " mc
        [ -z "$mc" ] && mc=1
        local count=$((le - ls + 1))
        if [ "$mc" = "2" ]; then
            read -rp "  目标起始端口: " ts
            nft_check_port "$ts" || { error "目标端口无效"; return; }
            te=$((ts + count - 1))
            [ "$te" -le 65535 ] || { error "目标结束端口超过 65535"; return; }
            local rule_mode="range_offset"
        else
            ts="$ls"; te="$le"
            local rule_mode="range_1_to_1"
        fi
    fi

    # 协议族判定
    family=$(nft_choose_family "$lip" "$thost" "auto")
    [ "$family" = "invalid" ] && { error "无法确定协议族"; return; }

    # 目标地址解析
    local ttype="ip"
    if [ "$(nft_classify "$thost")" = "domain" ]; then
        ttype="domain"
        resolved_ip=$(nft_resolve_domain "$thost" "$family") || { error "域名解析失败"; return; }
    else
        resolved_ip="$thost"
    fi

    local id; id=$(nft_next_rule_id)
    local record="${id}|${family}|${lip}|${ls}|${le}|${ttype}|${thost}|${resolved_ip}|${ts}|${te}|${rule_mode}"

    echo ""
    info "即将添加："
    nft_rule_summary "$id" "$family" "$lip" "$ls" "$le" "$ttype" "$thost" "$resolved_ip" "$ts" "$te" "$rule_mode"
    echo ""
    read -rp "  确认添加？(Y/n，默认Y): " c
    [ -z "$c" ] && c="y"
    echo "$c" | grep -qiE '^y(es)?$' || { warn "已取消"; return; }

    echo "$record" >> "$NFT_RULES_FILE"
    nft_write_and_apply || {
        # 回滚
        sed -i "/^${id}|/d" "$NFT_RULES_FILE"
        return 1
    }
}

# ── 删除规则 ──────────────────────────────────────────────
nft_edit_rule() {
    print_header "修改转发规则"
    if ! nft_list_rules; then
        warn "暂无规则"
        return
    fi
    echo ""
    read -rp "  请输入要修改的规则 ID（0 取消）: " id
    [ "$id" = "0" ] || [ -z "$id" ] && { warn "已取消"; return; }
    nft_find_rule "$id" || { error "未找到该规则"; return; }

    # 解析当前字段
    IFS='|' read -r OLD_ID OLD_F OLD_LIP OLD_LS OLD_LE OLD_TTYPE OLD_THOST OLD_TIP OLD_TS OLD_TE OLD_MODE <<< "$NFT_FOUND_RULE"

    echo ""
    info "当前规则："
    nft_rule_summary "$OLD_ID" "$OLD_F" "$OLD_LIP" "$OLD_LS" "$OLD_LE" "$OLD_TTYPE" "$OLD_THOST" "$OLD_TIP" "$OLD_TS" "$OLD_TE" "$OLD_MODE"
    echo ""
    echo -e "  ${DIM}直接回车 = 保留原值${NC}"
    echo ""

    # ── 监听 IP ──
    local lip_display="${OLD_LIP:-所有}"
    read -rp "  监听 IP [${lip_display}]: " new_lip
    [ -z "$new_lip" ] && new_lip="$OLD_LIP"
    [ "$new_lip" = "0.0.0.0" ] || [ "$new_lip" = "::" ] && new_lip=""

    # ── 监听端口 ──
    local new_ls new_le
    if [ "$OLD_MODE" = "single" ]; then
        read -rp "  监听端口 [${OLD_LS}]: " new_ls
        [ -z "$new_ls" ] && new_ls="$OLD_LS"
        nft_check_port "$new_ls" || { error "端口无效"; return; }
        new_le="$new_ls"
    else
        read -rp "  监听起始端口 [${OLD_LS}]: " new_ls
        [ -z "$new_ls" ] && new_ls="$OLD_LS"
        read -rp "  监听结束端口 [${OLD_LE}]: " new_le
        [ -z "$new_le" ] && new_le="$OLD_LE"
        nft_check_port "$new_ls" || { error "起始端口无效"; return; }
        nft_check_port "$new_le" || { error "结束端口无效"; return; }
        [ "$new_ls" -le "$new_le" ] || { error "起始端口不能大于结束端口"; return; }
    fi

    # ── 目标主机 ──
    read -rp "  目标 IP/域名 [${OLD_THOST}]: " new_thost
    [ -z "$new_thost" ] && new_thost="$OLD_THOST"
    [ "$(nft_classify "$new_thost")" != "invalid" ] || { error "目标地址格式无效"; return; }

    # ── 目标端口 ──
    local new_ts new_te new_mode
    if [ "$OLD_MODE" = "single" ]; then
        read -rp "  目标端口 [${OLD_TS}]: " new_ts
        [ -z "$new_ts" ] && new_ts="$OLD_TS"
        nft_check_port "$new_ts" || { error "目标端口无效"; return; }
        new_te="$new_ts"
        new_mode="single"
    else
        # 端口段：保留原模式或允许切换
        echo ""
        local cur_mode_label
        case "$OLD_MODE" in
            range_1_to_1) cur_mode_label="1:1 映射" ;;
            range_offset) cur_mode_label="端口段偏移" ;;
        esac
        echo -e "  当前映射模式：${BOLD}${cur_mode_label}${NC}"
        menu_item "1" "1:1 映射"
        menu_item "2" "端口段偏移"
        local default_mc=1
        [ "$OLD_MODE" = "range_offset" ] && default_mc=2
        read -rp "  选择映射模式 [1/2]，默认 ${default_mc}: " mc
        [ -z "$mc" ] && mc=$default_mc

        local count=$((new_le - new_ls + 1))
        if [ "$mc" = "2" ]; then
            read -rp "  目标起始端口 [${OLD_TS}]: " new_ts
            [ -z "$new_ts" ] && new_ts="$OLD_TS"
            nft_check_port "$new_ts" || { error "目标端口无效"; return; }
            new_te=$((new_ts + count - 1))
            [ "$new_te" -le 65535 ] || { error "目标结束端口超过 65535"; return; }
            new_mode="range_offset"
        else
            new_ts="$new_ls"; new_te="$new_le"
            new_mode="range_1_to_1"
        fi
    fi

    # ── 协议族判定（监听 IP 变化可能改变 family）──
    local new_family
    new_family=$(nft_choose_family "$new_lip" "$new_thost" "$OLD_F")
    [ "$new_family" = "invalid" ] && { error "无法确定协议族"; return; }

    # ── 目标解析 ──
    local new_ttype new_tip
    if [ "$(nft_classify "$new_thost")" = "domain" ]; then
        new_ttype="domain"
        new_tip=$(nft_resolve_domain "$new_thost" "$new_family") || { error "域名解析失败"; return; }
    else
        new_ttype="ip"
        new_tip="$new_thost"
    fi

    local new_record="${OLD_ID}|${new_family}|${new_lip}|${new_ls}|${new_le}|${new_ttype}|${new_thost}|${new_tip}|${new_ts}|${new_te}|${new_mode}"

    echo ""
    info "修改后："
    nft_rule_summary "$OLD_ID" "$new_family" "$new_lip" "$new_ls" "$new_le" "$new_ttype" "$new_thost" "$new_tip" "$new_ts" "$new_te" "$new_mode"
    echo ""
    read -rp "  确认应用？(Y/n，默认Y): " c
    [ -z "$c" ] && c="y"
    echo "$c" | grep -qiE '^y(es)?$' || { warn "已取消"; return; }

    # 备份原规则用于回滚
    local backup_line="$NFT_FOUND_RULE"
    # 删除旧规则
    sed -i "/^${OLD_ID}|/d" "$NFT_RULES_FILE"
    # 写入新规则
    echo "$new_record" >> "$NFT_RULES_FILE"

    if ! nft_write_and_apply; then
        # 回滚
        sed -i "/^${OLD_ID}|/d" "$NFT_RULES_FILE"
        echo "$backup_line" >> "$NFT_RULES_FILE"
        error "应用失败，已回滚到原规则"
        return 1
    fi
    info "规则已修改 ✓"
}

nft_delete_rule() {
    print_header "删除端口转发规则"
    if ! nft_list_rules; then
        warn "暂无规则"
        return
    fi
    echo ""
    read -rp "  请输入要删除的规则 ID（0 取消）: " id
    [ "$id" = "0" ] || [ -z "$id" ] && { warn "已取消"; return; }
    nft_find_rule "$id" || { error "未找到该规则"; return; }

    echo ""
    info "即将删除："
    local fields; IFS='|' read -ra fields <<< "$NFT_FOUND_RULE"
    nft_rule_summary "${fields[@]}"
    echo ""
    read -rp "  确认删除？(Y/n，默认Y): " c
    [ -z "$c" ] && c="y"
    echo "$c" | grep -qiE '^y(es)?$' || { warn "已取消"; return; }

    local backup; backup=$(mktemp) || return 1
    cp "$NFT_RULES_FILE" "$backup" || { rm -f "$backup"; return 1; }
    sed -i "/^${id}|/d" "$NFT_RULES_FILE" || { rm -f "$backup"; return 1; }
    nft_write_and_apply || { cp "$backup" "$NFT_RULES_FILE"; rm -f "$backup"; return 1; }
    rm -f "$backup"
}

# ── 清空所有规则 ──────────────────────────────────────────
nft_clear_all_rules() {
    warn "将清空所有 NFT 转发规则！"
    read -rp "  确认清空？(y/N，默认N): " c
    [ -z "$c" ] && c="n"
    echo "$c" | grep -qiE '^y(es)?$' || { warn "已取消"; return; }

    local backup; backup=$(mktemp) || return 1
    cp "$NFT_RULES_FILE" "$backup" || { rm -f "$backup"; return 1; }
    : > "$NFT_RULES_FILE"
    nft_write_and_apply || { cp "$backup" "$NFT_RULES_FILE"; rm -f "$backup"; return 1; }
    rm -f "$backup"
}

# ── DDNS 刷新 ─────────────────────────────────────────────
nft_refresh_ddns() {
    local tmp; tmp=$(mktemp) || return 1
    local changed=0 domain_count=0 line
    while IFS= read -r line; do
        if [[ -z "$line" || "$line" = \#* ]]; then
            echo "$line" >> "$tmp"
            continue
        fi
        IFS='|' read -r id f lip ls le ttype thost tip ts te mode <<< "$line"
        if [ "$ttype" = "domain" ]; then
            domain_count=$((domain_count + 1))
            local new_ip
            if new_ip=$(nft_resolve_domain "$thost" "$f"); then
                if [ "$new_ip" != "$tip" ]; then
                    info "[$id] ${thost}: ${tip} → ${new_ip}"
                    tip="$new_ip"
                    changed=$((changed + 1))
                fi
            else
                warn "[$id] ${thost} 解析失败，保留旧值 ${tip}"
            fi
        fi
        echo "${id}|${f}|${lip}|${ls}|${le}|${ttype}|${thost}|${tip}|${ts}|${te}|${mode}" >> "$tmp"
    done < "$NFT_RULES_FILE"

    if [ "$domain_count" -eq 0 ]; then
        warn "没有配置 DDNS 域名目标"
        rm -f "$tmp"
        return 0
    fi
    if [ "$changed" -eq 0 ]; then
        info "DDNS 检查完成，无变化"
        rm -f "$tmp"
        return 0
    fi
    local backup; backup=$(mktemp) || { rm -f "$tmp"; return 1; }
    cp "$NFT_RULES_FILE" "$backup" || { rm -f "$tmp" "$backup"; return 1; }
    mv "$tmp" "$NFT_RULES_FILE"
    nft_write_and_apply || { cp "$backup" "$NFT_RULES_FILE"; rm -f "$backup"; return 1; }
    rm -f "$backup"
}

# ── DDNS 自动刷新 timer ──────────────────────────────────
nft_ddns_timer_status() {
    if command -v systemctl &>/dev/null && systemctl is-active --quiet nftpf-ddns.timer 2>/dev/null; then
        echo "active"
    else
        echo "inactive"
    fi
}

nft_ddns_timer_enable() {
    print_header "启用 DDNS 自动刷新"
    if ! command -v systemctl &>/dev/null; then
        error "需要 systemd 才能启用自动刷新"
        return 1
    fi
    read -rp "  刷新间隔（10s-24h，默认 5m）: " interval
    [ -z "$interval" ] && interval="5m"

    cat > "$NFT_DDNS_SERVICE_FILE" <<EOF
[Unit]
Description=NFT Port Forward DDNS refresh
After=network-online.target

[Service]
Type=oneshot
ExecStart=$LOCAL_SCRIPT --nft-refresh-ddns
EOF

    cat > "$NFT_DDNS_TIMER_FILE" <<EOF
[Unit]
Description=NFT Port Forward DDNS auto refresh

[Timer]
OnBootSec=${interval}
OnUnitActiveSec=${interval}
AccuracySec=1s
Unit=nftpf-ddns.service

[Install]
WantedBy=timers.target
EOF

    systemctl daemon-reload
    systemctl enable --now nftpf-ddns.timer &>/dev/null && info "DDNS 自动刷新已启用（每 ${interval}）✓" \
        || error "启用失败"
}

nft_ddns_timer_disable() {
    if command -v systemctl &>/dev/null; then
        systemctl disable --now nftpf-ddns.timer &>/dev/null || true
    fi
    rm -f "$NFT_DDNS_TIMER_FILE" "$NFT_DDNS_SERVICE_FILE"
    command -v systemctl &>/dev/null && systemctl daemon-reload
    info "DDNS 自动刷新已关闭"
}

# ── 访问控制 ──────────────────────────────────────────────
nft_validate_access_entry() {
    local entry="$1" base prefix=""
    if [[ "$entry" = */* ]]; then
        base="${entry%%/*}"
        prefix="${entry##*/}"
        [[ "$prefix" =~ ^[0-9]+$ ]] || return 1
    else
        base="$entry"
    fi
    local family; family=$(nft_classify "$base")
    case "$family" in
        ipv4)
            [ -z "$prefix" ] || { [ "$prefix" -ge 0 ] && [ "$prefix" -le 32 ]; } || return 1
            NFT_AC_FAMILY="ipv4"
            ;;
        ipv6)
            [ -z "$prefix" ] || { [ "$prefix" -ge 0 ] && [ "$prefix" -le 128 ]; } || return 1
            NFT_AC_FAMILY="ipv6"
            ;;
        *) return 1 ;;
    esac
}

nft_set_access_mode() {
    local mode="$1" entries_raw="$2"
    local tmp; tmp=$(mktemp) || return 1
    echo "mode=$mode" > "$tmp"

    local entry count=0
    for entry in $(echo "$entries_raw" | tr ',' ' '); do
        [ -n "$entry" ] || continue
        if ! nft_validate_access_entry "$entry"; then
            error "无效的 IP/CIDR：$entry"
            rm -f "$tmp"
            return 1
        fi
        grep -qxF "entry=$NFT_AC_FAMILY|$entry" "$tmp" || {
            echo "entry=$NFT_AC_FAMILY|$entry" >> "$tmp"
            count=$((count + 1))
        }
    done

    if [ "$mode" != "off" ] && [ "$count" -eq 0 ]; then
        error "启用白/黑名单需要至少一个 IP/CIDR"
        rm -f "$tmp"
        return 1
    fi

    local backup existed=no; backup=$(mktemp) || { rm -f "$tmp"; return 1; }
    [ -f "$NFT_ACCESS_FILE" ] && { cp "$NFT_ACCESS_FILE" "$backup" || { rm -f "$tmp" "$backup"; return 1; }; existed=yes; }
    mv "$tmp" "$NFT_ACCESS_FILE"
    if ! nft_write_and_apply; then
        [ "$existed" = yes ] && cp "$backup" "$NFT_ACCESS_FILE" || rm -f "$NFT_ACCESS_FILE"
        rm -f "$backup"
        return 1
    fi
    rm -f "$backup"
}

nft_access_menu() {
    while true; do
        local mode count v4 v6
        mode=$(nft_get_access_mode)
        if [ -f "$NFT_ACCESS_FILE" ]; then
            count=$(grep -c '^entry=' "$NFT_ACCESS_FILE" 2>/dev/null)
            count=${count:-0}
        else
            count=0
        fi
        v4=$(nft_format_access_for "ipv4")
        v6=$(nft_format_access_for "ipv6")

        local mode_label mode_color
        case "$mode" in
            whitelist) mode_label="白名单"; mode_color="$GREEN" ;;
            blacklist) mode_label="黑名单"; mode_color="$YELLOW" ;;
            *) mode_label="关闭"; mode_color="$DIM" ;;
        esac

        print_header "访问控制（白名单 / 黑名单）"
        echo -e "  当前模式: ${mode_color}${BOLD}${mode_label}${NC}    名单数: ${BOLD}${count}${NC}"
        [ -n "$v4" ] && echo -e "  IPv4: ${BOLD}${v4}${NC}"
        [ -n "$v6" ] && echo -e "  IPv6: ${BOLD}${v6}${NC}"
        menu_div
        echo -e "  ${DIM}白名单：只允许名单内 IP 访问转发端口${NC}"
        echo -e "  ${DIM}黑名单：拒绝名单内 IP 访问转发端口${NC}"
        echo -e "  ${DIM}仅影响 NFT 转发端口，不影响 SSH 等其他服务${NC}"
        menu_div
        menu_pair "1" "启用白名单" "2" "启用黑名单"
        menu_item "3" "关闭访问控制" "$YELLOW"
        menu_pair "0" "返回上级" "00" "退出脚本" "$RED" "$RED"
        echo ""
        read -rp "$(ui_prompt '选择模式: ')" ch

        case "$ch" in
            1)
                # 白名单警告：自动检测当前 SSH 来源
                local ssh_from
                ssh_from=$(echo "${SSH_CONNECTION:-}" | awk '{print $1}')
                if [ -n "$ssh_from" ]; then
                    echo ""
                    echo -e "  ${YELLOW}当前 SSH 来源：${BOLD}${ssh_from}${NC}"
                    echo -e "  ${DIM}建议加入白名单避免自我封锁${NC}"
                fi
                echo ""
                echo -e "  ${DIM}多个用空格或逗号分隔，例如：1.2.3.4 5.6.7.0/24${NC}"
                read -rp "  白名单 IP/CIDR: " entries
                [ -z "$entries" ] && { warn "已取消"; sleep 1; continue; }
                if [ -n "$ssh_from" ] && ! echo "$entries" | grep -qF "$ssh_from"; then
                    read -rp "  自动添加 ${ssh_from}？(Y/n，默认Y): " a
                    [ -z "$a" ] && a="y"
                    echo "$a" | grep -qiE '^y(es)?$' && entries="$entries $ssh_from"
                fi
                nft_set_access_mode whitelist "$entries"
                ;;
            2)
                echo ""
                read -rp "  黑名单 IP/CIDR: " entries
                [ -z "$entries" ] && { warn "已取消"; sleep 1; continue; }
                nft_set_access_mode blacklist "$entries"
                ;;
            3)
                nft_set_access_mode off ""
                ;;
            0) return ;;
            00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
            *) warn "无效选项"; sleep 1; continue ;;
        esac
        echo ""
        ui_continue
    done
}


# ── iptables 本地端口转发（轻量，不依赖 nftables）─────────
IPTPF_RULES_FILE="${IPTPF_RULES_FILE:-/etc/iptables-local-fwd.conf}"

iptpf_ensure_file() {
    [ -f "$IPTPF_RULES_FILE" ] || touch "$IPTPF_RULES_FILE" || return 1
}

iptpf_check_iptables() {
    command -v iptables &>/dev/null && return 0
    info "正在安装 iptables..."
    if command -v apt-get &>/dev/null; then
        apt-get install -y iptables iptables-persistent 2>/dev/null
    elif command -v apk &>/dev/null; then
        apk add --no-cache iptables 2>/dev/null
    elif command -v yum &>/dev/null; then
        yum install -y iptables-services 2>/dev/null
    fi
    command -v iptables &>/dev/null
}

iptpf_persist() {
    # 持久化保存当前 iptables 规则
    if [ -d /etc/iptables ]; then
        iptables-save > /etc/iptables/rules.v4 2>/dev/null || return 1
        if command -v ip6tables-save &>/dev/null; then
            ip6tables-save > /etc/iptables/rules.v6 2>/dev/null || return 1
        fi
        return 0
    elif [ -f /etc/sysconfig/iptables ]; then
        iptables-save > /etc/sysconfig/iptables 2>/dev/null || return 1
        return 0
    fi
    return 1
}

iptpf_apply_rule() {
    local src_port="$1" dst_port="$2" proto="$3"
    # PREROUTING：来自外部的流量
    iptables -t nat -A PREROUTING -p "$proto" --dport "$src_port" -j REDIRECT --to-port "$dst_port" 2>/dev/null || return 1
    # OUTPUT：本机自己访问也走转发
    if ! iptables -t nat -A OUTPUT -p "$proto" -o lo --dport "$src_port" -j REDIRECT --to-port "$dst_port" 2>/dev/null; then
        iptables -t nat -D PREROUTING -p "$proto" --dport "$src_port" -j REDIRECT --to-port "$dst_port" 2>/dev/null || true
        return 1
    fi
}

iptpf_remove_rule() {
    local src_port="$1" dst_port="$2" proto="$3"
    local removed_pre=no
    if iptables -t nat -C PREROUTING -p "$proto" --dport "$src_port" -j REDIRECT --to-port "$dst_port" 2>/dev/null; then
        iptables -t nat -D PREROUTING -p "$proto" --dport "$src_port" -j REDIRECT --to-port "$dst_port" 2>/dev/null || return 1
        removed_pre=yes
    fi
    if iptables -t nat -C OUTPUT -p "$proto" -o lo --dport "$src_port" -j REDIRECT --to-port "$dst_port" 2>/dev/null; then
        if ! iptables -t nat -D OUTPUT -p "$proto" -o lo --dport "$src_port" -j REDIRECT --to-port "$dst_port" 2>/dev/null; then
            [ "$removed_pre" = yes ] && iptables -t nat -A PREROUTING -p "$proto" --dport "$src_port" -j REDIRECT --to-port "$dst_port" 2>/dev/null || true
            return 1
        fi
    fi
}

iptpf_list() {
    iptpf_ensure_file
    if [ ! -s "$IPTPF_RULES_FILE" ]; then
        warn "暂无本地端口转发规则"
        return 1
    fi
    echo -e "  ${DIM}格式: [编号] 源端口 → 目标端口 (协议)${NC}"
    local i=1
    while IFS='|' read -r src dst proto; do
        [ -z "$src" ] && continue
        echo -e "  ${GREEN}[$i]${NC} ${BOLD}${src}${NC} → ${BOLD}${dst}${NC}  (${proto})"
        i=$((i + 1))
    done < "$IPTPF_RULES_FILE"
}

iptpf_add() {
    print_header "添加本地端口转发"
    echo -e "  ${DIM}将访问本机 A 端口的流量转发到本机 B 端口${NC}"
    echo -e "  ${DIM}用途：端口跳转、绕过端口限制、本机端口聚合${NC}"
    echo ""

    iptpf_check_iptables || { error "iptables 不可用"; return; }

    read -rp "  源端口（外部访问的端口）: " src
    nft_check_port "$src" || { error "端口无效"; return; }

    read -rp "  目标端口（本机实际服务端口）: " dst
    nft_check_port "$dst" || { error "端口无效"; return; }

    [ "$src" = "$dst" ] && { error "源端口和目标端口不能相同"; return; }

    echo ""
    menu_pair "1" "TCP" "2" "UDP"
    menu_item "3" "TCP + UDP"
    read -rp "  协议 [1/2/3]，默认 3: " pc
    [ -z "$pc" ] && pc=3

    case "$pc" in
        1) protos="tcp" ;;
        2) protos="udp" ;;
        3) protos="tcp udp" ;;
        *) error "无效选项"; return ;;
    esac

    # 检查重复
    for p in $protos; do
        if grep -qE "^${src}\|${dst}\|${p}$" "$IPTPF_RULES_FILE" 2>/dev/null; then
            warn "规则已存在: ${src} → ${dst} (${p})"
            continue
        fi
        if ! iptpf_apply_rule "$src" "$dst" "$p"; then
            error "iptables 添加失败: ${src} → ${dst} (${p})"
            continue
        fi
        if ! echo "${src}|${dst}|${p}" >> "$IPTPF_RULES_FILE"; then
            iptpf_remove_rule "$src" "$dst" "$p" || true
            error "规则状态保存失败"
            continue
        fi
        info "已添加: ${src} → ${dst} (${p}) ✓"
    done

    iptpf_persist || warn "当前系统未提供 iptables 持久化后端，规则仅在本次启动有效"
}

iptpf_delete() {
    print_header "删除本地端口转发"
    if ! iptpf_list; then
        return
    fi
    echo ""
    read -rp "  请输入要删除的规则编号（0 取消）: " id
    [ "$id" = "0" ] || [ -z "$id" ] && { warn "已取消"; return; }
    if ! echo "$id" | grep -qE '^[0-9]+$'; then
        error "无效编号"
        return
    fi

    local target_line; target_line=$(sed -n "${id}p" "$IPTPF_RULES_FILE")
    [ -z "$target_line" ] && { error "未找到该规则"; return; }

    IFS='|' read -r src dst proto <<< "$target_line"

    echo ""
    info "即将删除: ${src} → ${dst} (${proto})"
    read -rp "  确认删除？(Y/n，默认Y): " c
    [ -z "$c" ] && c="y"
    echo "$c" | grep -qiE '^y(es)?$' || { warn "已取消"; return; }

    iptpf_remove_rule "$src" "$dst" "$proto" || { error "iptables 规则删除失败"; return 1; }
    if ! sed -i "${id}d" "$IPTPF_RULES_FILE"; then
        iptpf_apply_rule "$src" "$dst" "$proto" || true
        error "规则状态更新失败，已尝试恢复运行规则"
        return 1
    fi
    iptpf_persist || warn "当前系统未提供 iptables 持久化后端，重启后状态可能与当前规则不同"
    info "已删除 ✓"
}

iptpf_clear_all() {
    warn "将清空所有本地端口转发规则"
    read -rp "  确认？(y/N，默认N): " c
    [ -z "$c" ] && c="n"
    echo "$c" | grep -qiE '^y(es)?$' || { warn "已取消"; return; }

    iptpf_ensure_file || return 1
    local removed; removed=$(mktemp) || return 1
    while IFS='|' read -r src dst proto; do
        [ -z "$src" ] && continue
        if ! iptpf_remove_rule "$src" "$dst" "$proto"; then
            while IFS='|' read -r old_src old_dst old_proto; do
                [ -n "$old_src" ] && iptpf_apply_rule "$old_src" "$old_dst" "$old_proto" || true
            done < "$removed"
            rm -f "$removed"
            error "清空失败，已尝试恢复之前删除的规则"
            return 1
        fi
        echo "${src}|${dst}|${proto}" >> "$removed"
    done < "$IPTPF_RULES_FILE"
    : > "$IPTPF_RULES_FILE" || { rm -f "$removed"; return 1; }
    rm -f "$removed"
    iptpf_persist || warn "当前系统未提供 iptables 持久化后端"
    info "已清空所有本地端口转发规则 ✓"
}

iptpf_menu() {
    iptpf_ensure_file
    while true; do
        local count
        count=$(grep -c '^' "$IPTPF_RULES_FILE" 2>/dev/null)
        count=${count:-0}

        print_header "iptables 本地端口转发"
        echo -e "  ${DIM}本机 A 端口 → 本机 B 端口（不涉及外网目标）${NC}"
        echo -e "  ${DIM}用途：端口跳转、绕过端口限制、端口别名${NC}"
        echo ""
        echo -e "  当前规则数：${BOLD}${count}${NC}"

        if [ "$count" -gt 0 ]; then
            menu_div
            iptpf_list
        fi

        menu_div
        menu_item "1" "添加本地端口转发"
        menu_pair "2" "删除指定规则" "3" "清空所有规则" "$YELLOW" "$YELLOW"
        menu_pair "0" "返回上级" "00" "退出脚本" "$RED" "$RED"
        echo ""
        read -rp "$(ui_prompt '选择操作: ')" ch

        case "$ch" in
            1) iptpf_add ;;
            2) iptpf_delete ;;
            3) iptpf_clear_all ;;
            0) return ;;
            00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
            *) warn "无效选项"; sleep 1; continue ;;
        esac
        echo ""
        ui_continue
    done
}

# ── NFT 主菜单 ────────────────────────────────────────────
nft_menu() {
    nft_ensure_state_dir

    while true; do
        local rule_count
        if [ -f "$NFT_RULES_FILE" ]; then
            rule_count=$(grep -c '^[0-9]' "$NFT_RULES_FILE" 2>/dev/null)
            rule_count=${rule_count:-0}
        else
            rule_count=0
        fi
        local access_mode; access_mode=$(nft_get_access_mode)
        local timer_st; timer_st=$(nft_ddns_timer_status)

        print_header "NFT 转发管理（端口转发 / DDNS / 访问控制）"

        # 状态栏
        if command -v nft &>/dev/null; then
            echo -e "  nftables : ${GREEN}已安装${NC}    规则数: ${BOLD}${rule_count}${NC}"
        else
            echo -e "  nftables : ${RED}未安装${NC}"
        fi

        case "$access_mode" in
            whitelist) echo -e "  访问控制 : ${GREEN}${BOLD}白名单${NC}" ;;
            blacklist) echo -e "  访问控制 : ${YELLOW}${BOLD}黑名单${NC}" ;;
            *) echo -e "  访问控制 : ${DIM}关闭${NC}" ;;
        esac
        case "$timer_st" in
            active)  echo -e "  DDNS 定时刷新 : ${GREEN}${BOLD}运行中${NC}" ;;
            *)       echo -e "  DDNS 定时刷新 : ${DIM}未启用${NC}" ;;
        esac

        # 显示规则列表（不超过 10 条）
        if [ "$rule_count" -gt 0 ]; then
            menu_div
            echo -e "  ${DIM}当前规则：${NC}"
            local shown=0
            while IFS='|' read -r id f lip ls le ttype thost tip ts te mode; do
                [[ -z "$id" || "$id" = \#* ]] && continue
                [ "$shown" -ge 10 ] && { echo -e "  ${DIM}（更多规则请用「查看所有规则」）${NC}"; break; }
                echo "  $(nft_rule_summary "$id" "$f" "$lip" "$ls" "$le" "$ttype" "$thost" "$tip" "$ts" "$te" "$mode")"
                shown=$((shown + 1))
            done < "$NFT_RULES_FILE"
        fi

        menu_div
        if command -v nft &>/dev/null; then
            menu_pair "1" "添加单端口转发" "2" "添加端口段转发"
            menu_pair "3" "查看所有规则" "e" "修改规则"
            menu_pair "4" "删除规则" "5" "清空所有规则" "$YELLOW" "$YELLOW"
            echo ""
            menu_group "动态解析与访问"
            menu_item "6" "立即刷新 DDNS"
            if [ "$timer_st" = "active" ]; then
                menu_item "7" "关闭 DDNS 自动刷新" "$YELLOW"
            else
                menu_item "7" "启用 DDNS 自动刷新"
            fi
            menu_pair "8" "访问控制" "l" "iptables 本地转发"
            menu_item "9" "卸载 nftables" "$YELLOW"
        else
            echo -e "  ${YELLOW}未检测到 nftables，请先安装：${NC}"
            menu_item "i" "安装 nftables"
            menu_item "l" "iptables 本地端口转发"
            menu_div
        fi
        menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
        echo ""
        read -rp "$(ui_prompt '选择操作: ')" ch

        if ! command -v nft &>/dev/null; then
            case "$ch" in
                i|I)
                    nft_install && info "nftables 安装完成 ✓" || error "nftables 安装失败"
                    ;;
                l|L) iptpf_menu ;;
                0) return ;;
                00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
                *) warn "请先安装 nftables（按 i）"; sleep 1; continue ;;
            esac
        else
            case "$ch" in
                1|2)
                    nft_enable_ip_forward
                    if [ "$ch" = "1" ]; then nft_add_rule single
                    else nft_add_rule range; fi
                    ;;
                3)
                    print_header "所有 NFT 转发规则"
                    nft_list_rules || warn "暂无规则"
                    ;;
                e|E) nft_edit_rule ;;
                4) nft_delete_rule ;;
                5) nft_clear_all_rules ;;
                6) nft_refresh_ddns ;;
                7)
                    [ "$timer_st" = "active" ] && nft_ddns_timer_disable || nft_ddns_timer_enable
                    ;;
                8) nft_access_menu ;;
                9) nft_uninstall ;;
                l|L) iptpf_menu ;;
                0) return ;;
                00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
                *) warn "无效选项"; sleep 1; continue ;;
            esac
        fi
        echo ""
        ui_continue
    done
}
# ══════════════════════════════════════════════════════════
#  DDNS 模块
# ══════════════════════════════════════════════════════════

DDNS_SCRIPT="/root/ddns.sh"
DDNS_TOKEN_FILE="/root/.cf_token"
DDNS_HUAWEI_KEY_FILE="/root/.hw_dns_aksk"
DDNS_LOG="/var/log/ddns.log"
DDNS_ZONE_FILE="/root/.cf_zone"
DDNS_TG_FILE="/root/.cf_tg"    # Telegram 通知配置
DDNS_STATE_DIR="/root"
DDNS_CRON_MARKER="# VPS_TOOLS_DDNS"

ddns_cfg_get() {
    local key="$1"
    [ -f "$DDNS_ZONE_FILE" ] || return 1
    grep "^${key}=" "$DDNS_ZONE_FILE" 2>/dev/null | head -1 | cut -d= -f2-
}

ddns_provider() {
    local provider
    provider=$(ddns_cfg_get PROVIDER 2>/dev/null || true)
    [ -n "$provider" ] || provider="cloudflare"
    echo "$provider"
}

ddns_provider_label() {
    case "$(ddns_provider)" in
        huawei) echo "华为云 DNS" ;;
        *) echo "Cloudflare" ;;
    esac
}

ddns_sed_escape() {
    printf '%s' "$1" | sed 's/[&|\\]/\\&/g'
}

ddns_domain_normalize() {
    local value="$1"
    DDNS_DOMAIN_VALUE="$value" python3 <<'PY'
import os
import re

value = os.environ.get("DDNS_DOMAIN_VALUE", "").strip().rstrip(".")
try:
    value = value.encode("idna").decode("ascii").lower()
except (UnicodeError, UnicodeDecodeError):
    raise SystemExit(1)
if not value or len(value) > 253:
    raise SystemExit(1)
labels = value.split(".")
if any(
    not label
    or len(label) > 63
    or label.startswith("-")
    or label.endswith("-")
    or re.fullmatch(r"[a-z0-9-]+", label) is None
    for label in labels
):
    raise SystemExit(1)
print(value)
PY
}

ddns_domain_in_zone() {
    local domain="${1%.}" zone="${2%.}"
    [ "$domain" = "$zone" ] || [[ "$domain" = *."$zone" ]]
}

ddns_huawei_endpoint_normalize() {
    local value="${1:-https://dns.myhuaweicloud.com}"
    DDNS_ENDPOINT_VALUE="$value" python3 <<'PY'
import os
import re
import urllib.parse

value = os.environ.get("DDNS_ENDPOINT_VALUE", "").strip()
if "://" not in value:
    value = "https://" + value
parts = urllib.parse.urlsplit(value)
host = (parts.hostname or "").lower().rstrip(".")
if (
    parts.scheme != "https"
    or parts.username is not None
    or parts.password is not None
    or parts.port is not None
    or parts.path not in ("", "/")
    or parts.query
    or parts.fragment
    or re.fullmatch(r"dns(?:\.[a-z0-9-]+)?\.myhuaweicloud\.com", host) is None
):
    raise SystemExit(1)
print("https://" + host)
PY
}

ddns_cf_ttl_normalize() {
    local value="${1:-60}"
    [[ "$value" =~ ^[0-9]+$ ]] || return 1
    value=$(printf '%s' "$value" | sed 's/^0*//')
    [ -n "$value" ] || value=0
    [ "${#value}" -le 5 ] || return 1
    if [ "$value" -eq 1 ] || { [ "$value" -ge 60 ] && [ "$value" -le 86400 ]; }; then
        echo "$value"
        return 0
    fi
    return 1
}

ddns_huawei_ttl_normalize() {
    local value="${1:-300}"
    [[ "$value" =~ ^[0-9]+$ ]] || return 1
    value=$(printf '%s' "$value" | sed 's/^0*//')
    [ -n "$value" ] || value=0
    [ "${#value}" -le 10 ] || return 1
    [ "$value" -ge 300 ] && [ "$value" -le 2147483647 ] || return 1
    echo "$value"
}

ddns_install_tx_begin() {
    DDNS_INSTALL_TX_DIR=$(mktemp -d /tmp/vps-tools-ddns.XXXXXX) || return 1
    local index=0 path
    for path in "$DDNS_SCRIPT" "$DDNS_TOKEN_FILE" "$DDNS_HUAWEI_KEY_FILE" "$DDNS_ZONE_FILE"; do
        index=$((index + 1))
        if [ -e "$path" ]; then
            cp -a -- "$path" "$DDNS_INSTALL_TX_DIR/file.$index" || {
                rm -rf -- "$DDNS_INSTALL_TX_DIR"
                DDNS_INSTALL_TX_DIR=""
                return 1
            }
            : > "$DDNS_INSTALL_TX_DIR/present.$index"
        fi
    done
    if command -v crontab >/dev/null 2>&1; then
        crontab -l > "$DDNS_INSTALL_TX_DIR/crontab" 2>/dev/null || : > "$DDNS_INSTALL_TX_DIR/crontab"
        : > "$DDNS_INSTALL_TX_DIR/has-crontab"
    fi
}

ddns_install_tx_restore() {
    local dir="${DDNS_INSTALL_TX_DIR:-}" index=0 path failed=0
    [ -n "$dir" ] && [ -d "$dir" ] || return 0
    for path in "$DDNS_SCRIPT" "$DDNS_TOKEN_FILE" "$DDNS_HUAWEI_KEY_FILE" "$DDNS_ZONE_FILE"; do
        index=$((index + 1))
        if [ -f "$dir/present.$index" ]; then
            cp -a -- "$dir/file.$index" "$path" || failed=1
        else
            rm -f -- "$path" || failed=1
        fi
    done
    if [ -f "$dir/has-crontab" ]; then
        crontab "$dir/crontab" >/dev/null 2>&1 || failed=1
    fi
    if [ "$failed" -eq 0 ]; then
        rm -rf -- "$dir"
        DDNS_INSTALL_TX_DIR=""
        return 0
    fi
    warn "DDNS 回滚未完整完成，快照保留在 ${dir}"
    return 1
}

ddns_install_tx_commit() {
    [ -z "${DDNS_INSTALL_TX_DIR:-}" ] || rm -rf -- "$DDNS_INSTALL_TX_DIR"
    DDNS_INSTALL_TX_DIR=""
}

ddns_domain_dot() {
    local domain="$1"
    case "$domain" in
        *.) echo "$domain" ;;
        *) echo "${domain}." ;;
    esac
}

ddns_interval_normalize() {
    local value="${1:-5}"
    echo "$value" | grep -qE '^[0-9]+$' || { echo 5; return; }
    if [ "$value" -ge 1 ] && [ "$value" -le 59 ]; then
        echo "$value"
    else
        echo 5
    fi
}

ddns_interval_min() {
    local value
    value=$(ddns_cfg_get INTERVAL_MIN 2>/dev/null || true)
    ddns_interval_normalize "${value:-5}"
}

ddns_cron_expr() {
    local interval
    interval=$(ddns_interval_normalize "${1:-$(ddns_interval_min)}")
    if [ "$interval" -eq 1 ]; then
        echo "* * * * *"
    else
        printf '*/%s * * * *\n' "$interval"
    fi
}

ddns_cron_without_managed() {
    grep -Fv -- "$DDNS_CRON_MARKER" | grep -Fv -- "$DDNS_SCRIPT"
}

ddns_prompt_interval() {
    local default="${1:-5}" input
    default=$(ddns_interval_normalize "$default")
    read -rp "  检测间隔分钟（1-59，默认${default}，常用 1/2/5）: " input
    ddns_interval_normalize "${input:-$default}"
}

ddns_log_path() {
    local log_path
    log_path=$(ddns_cfg_get LOG 2>/dev/null)
    if [ -n "$log_path" ]; then
        echo "$log_path"
    elif [ -f "$DDNS_LOG" ]; then
        echo "$DDNS_LOG"
    else
        echo "$HOME/ddns.log"
    fi
}

ddns_truthy() {
    case "$1" in
        1|true|TRUE|yes|YES|on|ON) return 0 ;;
        *) return 1 ;;
    esac
}

ddns_cfg_enable_a() {
    local enabled mode
    enabled=$(ddns_cfg_get ENABLE_A 2>/dev/null || true)
    if [ -n "$enabled" ]; then
        ddns_truthy "$enabled"
        return
    fi
    mode=$(ddns_cfg_get MODE 2>/dev/null || true)
    [ "$mode" != "ipv6" ] && [ "$mode" != "aaaa" ]
}

ddns_cfg_enable_aaaa() {
    local enabled mode
    enabled=$(ddns_cfg_get ENABLE_AAAA 2>/dev/null || true)
    if [ -n "$enabled" ]; then
        ddns_truthy "$enabled"
        return
    fi
    mode=$(ddns_cfg_get MODE 2>/dev/null || true)
    [ "$mode" = "dual" ] || [ "$mode" = "ipv6" ] || [ "$mode" = "aaaa" ]
}

ddns_cfg_domain4() {
    local domain
    domain=$(ddns_cfg_get DOMAIN4 2>/dev/null || true)
    [ -n "$domain" ] || domain=$(ddns_cfg_get DOMAIN 2>/dev/null || true)
    echo "$domain"
}

ddns_cfg_domain6() {
    local domain mode
    domain=$(ddns_cfg_get DOMAIN6 2>/dev/null || true)
    if [ -z "$domain" ]; then
        mode=$(ddns_cfg_get MODE 2>/dev/null || true)
        if [ "$mode" = "dual" ] || [ "$mode" = "ipv6" ] || [ "$mode" = "aaaa" ]; then
            domain=$(ddns_cfg_get DOMAIN 2>/dev/null || true)
        fi
    fi
    echo "$domain"
}

ddns_primary_domain() {
    local domain
    if ddns_cfg_enable_a; then
        domain=$(ddns_cfg_domain4)
        [ -n "$domain" ] && { echo "$domain"; return; }
    fi
    if ddns_cfg_enable_aaaa; then
        domain=$(ddns_cfg_domain6)
        [ -n "$domain" ] && { echo "$domain"; return; }
    fi
    ddns_cfg_get DOMAIN 2>/dev/null || true
}

ddns_mode_label() {
    local domain4 domain6 has_a="false" has_aaaa="false"
    ddns_cfg_enable_a && has_a="true"
    ddns_cfg_enable_aaaa && has_aaaa="true"
    domain4=$(ddns_cfg_domain4)
    domain6=$(ddns_cfg_domain6)
    if [ "$has_a" = "true" ] && [ "$has_aaaa" = "true" ]; then
        if [ "$domain4" = "$domain6" ]; then
            echo "IPv4 + IPv6（同域名）"
        else
            echo "IPv4 + IPv6（分别设置）"
        fi
    elif [ "$has_aaaa" = "true" ]; then
        echo "仅 IPv6"
    else
        echo "仅 IPv4"
    fi
}

ddns_build_domain() {
    local sub="$1" zone="$2"
    case "$sub" in
        @) echo "$zone" ;;
        *."$zone") echo "$sub" ;;
        *) echo "${sub}.${zone}" ;;
    esac
}

ddns_ipv6_subdomain_default() {
    local sub4="${1:-}"
    case "$sub4" in
        ""|@)   echo "v6" ;;
        *ipv4)  echo "${sub4%ipv4}ipv6" ;;
        *IPv4)  echo "${sub4%IPv4}IPv6" ;;
        *v4)    echo "${sub4%v4}v6" ;;
        *V4)    echo "${sub4%V4}V6" ;;
        *-4)    echo "${sub4%-4}-6" ;;
        *)      echo "${sub4}-v6" ;;
    esac
}

ddns_replace_link_host() {
    local link="$1" domain="$2"
    python3 - "$domain" 3<<<"$link" <<'PY'
import base64
import json
import os
import re
import sys
import urllib.parse


def fail(message):
    print(message, file=sys.stderr)
    raise SystemExit(1)


def decode_base64(value):
    try:
        raw = value.encode("ascii")
        raw += b"=" * (-len(raw) % 4)
        return base64.b64decode(raw, altchars=b"-_", validate=True)
    except Exception:
        fail("链接中的 Base64 内容无效")


def encode_base64(value, original):
    encoder = base64.urlsafe_b64encode if "-" in original or "_" in original else base64.b64encode
    encoded = encoder(value).decode("ascii")
    return encoded if original.endswith("=") else encoded.rstrip("=")


def valid_domain(value):
    try:
        ascii_value = value.rstrip(".").encode("idna").decode("ascii")
    except UnicodeError:
        fail("DDNS 域名格式无效")
    labels = ascii_value.split(".")
    if len(ascii_value) > 253 or any(
        not label
        or len(label) > 63
        or label.startswith("-")
        or label.endswith("-")
        or re.fullmatch(r"[A-Za-z0-9-]+", label) is None
        for label in labels
    ):
        fail("DDNS 域名格式无效")
    return ascii_value


def replace_vmess(value, target):
    payload = value[len("vmess://"):]
    fragment = ""
    if "#" in payload:
        payload, fragment = payload.split("#", 1)
        fragment = "#" + fragment
    if not payload or "?" in payload:
        fail("无法识别 VMess 分享链接")
    try:
        data = json.loads(decode_base64(payload).decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        fail("VMess 分享链接中的 JSON 无效")
    if not isinstance(data, dict) or not str(data.get("add") or "").strip():
        fail("VMess 分享链接缺少服务器地址")
    data["add"] = target
    rendered = json.dumps(data, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return "vmess://" + encode_base64(rendered, payload) + fragment


def replace_legacy_ss(value, target):
    payload = value[len("ss://"):]
    fragment = ""
    if "#" in payload:
        payload, fragment = payload.split("#", 1)
        fragment = "#" + fragment
    try:
        decoded = decode_base64(payload).decode("utf-8")
    except UnicodeDecodeError:
        fail("Shadowsocks 分享链接内容无效")
    if "@" not in decoded:
        fail("Shadowsocks 分享链接缺少服务器地址")
    credentials, endpoint = decoded.rsplit("@", 1)
    if endpoint.startswith("["):
        match = re.fullmatch(r"\[[^]]+\]:(\d+)", endpoint)
        port = match.group(1) if match else ""
    else:
        host, separator, port = endpoint.rpartition(":")
        if not separator or not host:
            port = ""
    if not port or not port.isdigit() or not 1 <= int(port) <= 65535:
        fail("Shadowsocks 分享链接端口无效")
    rendered = f"{credentials}@{target}:{port}".encode("utf-8")
    return "ss://" + encode_base64(rendered, payload) + fragment


domain = valid_domain(sys.argv[1].strip())
with os.fdopen(3, "r", encoding="utf-8") as stream:
    link = stream.read().rstrip("\r\n")
if not link or "://" not in link:
    fail("请输入完整的分享链接")

scheme = link.split(":", 1)[0].lower()
if scheme == "vmess":
    print(replace_vmess(link, domain))
    raise SystemExit(0)

# Legacy Shadowsocks encodes credentials and endpoint together, so no @ is visible in the URI.
if scheme == "ss" and "@" not in link.split("#", 1)[0]:
    print(replace_legacy_ss(link, domain))
    raise SystemExit(0)

try:
    parts = urllib.parse.urlsplit(link)
    port = parts.port
except ValueError:
    fail("分享链接中的服务器端口无效")
if not parts.scheme or not parts.netloc or not parts.hostname:
    fail("无法识别分享链接中的服务器地址")

userinfo, separator, unused_endpoint = parts.netloc.rpartition("@")
del unused_endpoint
new_netloc = (userinfo + separator if separator else "") + domain
if port is not None:
    if not 1 <= port <= 65535:
        fail("分享链接中的服务器端口无效")
    new_netloc += f":{port}"
print(urllib.parse.urlunsplit((parts.scheme, new_netloc, parts.path, parts.query, parts.fragment)))
PY
}

ddns_share_link_tool() {
    print_header "替换分享链接地址"
    [ ! -f "$DDNS_ZONE_FILE" ] && { error "DDNS 未配置"; return 1; }
    command -v python3 >/dev/null 2>&1 || { error "缺少 python3，无法解析分享链接"; return 1; }

    local domain4="" domain6="" original_link="" link4="" link6=""
    ddns_cfg_enable_a && domain4=$(ddns_cfg_domain4)
    ddns_cfg_enable_aaaa && domain6=$(ddns_cfg_domain6)
    if [ -z "$domain4" ] && [ -z "$domain6" ]; then
        error "当前配置没有可用的 IPv4 或 IPv6 DDNS 域名"
        return 1
    fi

    echo -e "  ${DIM}保留协议、密钥、端口、参数和备注，仅将服务器地址换成 DDNS 域名。${NC}"
    echo -e "  ${DIM}支持 SS / VMess / VLESS / Trojan / Hysteria2 / TUIC 等分享 URI。${NC}"
    echo ""
    [ -n "$domain4" ] && echo -e "  IPv4 DDNS : ${BOLD}${domain4}${NC}"
    [ -n "$domain6" ] && echo -e "  IPv6 DDNS : ${BOLD}${domain6}${NC}"
    echo ""
    menu_div
    read -rp "  粘贴现有分享链接: " original_link
    [ -z "$original_link" ] && { warn "已取消"; return; }

    if [ -n "$domain4" ]; then
        link4=$(ddns_replace_link_host "$original_link" "$domain4") || {
            error "分享链接解析失败，未生成新链接"
            return 1
        }
    fi
    if [ -n "$domain6" ]; then
        if [ "$domain6" = "$domain4" ]; then
            link6="$link4"
        else
            link6=$(ddns_replace_link_host "$original_link" "$domain6") || {
                error "分享链接解析失败，未生成新链接"
                return 1
            }
        fi
    fi

    echo ""
    menu_div
    if [ -n "$link4" ] && [ "$domain4" = "$domain6" ]; then
        echo -e "  ${GREEN}${BOLD}双栈 DDNS 链接${NC}"
        printf '  %s\n' "$link4"
    else
        if [ -n "$link4" ]; then
            echo -e "  ${GREEN}${BOLD}IPv4 DDNS 链接${NC}"
            printf '  %s\n' "$link4"
        fi
        if [ -n "$link6" ]; then
            [ -n "$link4" ] && echo ""
            echo -e "  ${GREEN}${BOLD}IPv6 DDNS 链接${NC}"
            printf '  %s\n' "$link6"
        fi
    fi
    menu_div
    echo -e "  ${DIM}新链接包含原节点凭据，请按密码同等保护。原链接和服务端配置未被修改。${NC}"
}

ddns_fetch_public_ip() {
    local FAMILY="$1" VALUE
    case "$FAMILY" in
        4) VALUE=$(curl -4 -fsS --max-time 8 https://api.ipify.org 2>/dev/null || curl -4 -fsS --max-time 8 https://api.ip.sb/ip 2>/dev/null) ;;
        6) VALUE=$(curl -6 -fsS --max-time 8 https://api64.ipify.org 2>/dev/null || curl -6 -fsS --max-time 8 https://api.ip.sb/ip 2>/dev/null) ;;
        *) return 1 ;;
    esac
    VALUE=${VALUE//$'\r'/}
    VALUE=${VALUE//$'\n'/}
    DDNS_IP_VALUE="$VALUE" python3 - "$FAMILY" <<'PY'
import ipaddress
import os
import sys

value = os.environ.get("DDNS_IP_VALUE", "")
try:
    address = ipaddress.ip_address(value)
except ValueError:
    raise SystemExit(1)
if address.version != int(sys.argv[1]) or not address.is_global:
    raise SystemExit(1)
print(address.compressed)
PY
}

ddns_cf_exact_records() {
    local type="$1" domain="$2"
    DDNS_CF_JSON=$(cat) python3 - "$type" "$domain" <<'PY'
import json
import os
import sys

rtype = sys.argv[1].upper()
target = sys.argv[2].rstrip(".").lower()
try:
    data = json.loads(os.environ.get("DDNS_CF_JSON", "{}"))
except Exception:
    raise SystemExit(1)
if data.get("success") is not True or not isinstance(data.get("result"), list):
    raise SystemExit(1)
for record in data["result"]:
    name = str(record.get("name") or "").rstrip(".").lower()
    if name == target and str(record.get("type") or "").upper() == rtype:
        record_id = str(record.get("id") or "").replace("\t", " ").replace("\n", " ")
        content = str(record.get("content") or "").replace("\t", " ").replace("\n", " ")
        if record_id:
            print(f"{record_id}\t{content}")
PY
}

ddns_install_cron_job() {
    local CRON_JOB="$1"
    if ! (crontab -l 2>/dev/null | ddns_cron_without_managed; echo "$CRON_JOB") | crontab -; then
        error "写入 DDNS crontab 失败"
        return 1
    fi
    if ! ddns_start_cron_service >/dev/null 2>&1; then
        if ddns_remove_cron_job >/dev/null 2>&1; then
            error "cron 服务无法启动，已撤销 DDNS 定时任务"
        else
            error "cron 服务无法启动，且定时任务撤销失败，请手动检查 crontab -l"
        fi
        return 1
    fi
}

ddns_remove_cron_job() {
    command -v crontab >/dev/null 2>&1 || return 0
    if ! (crontab -l 2>/dev/null | ddns_cron_without_managed) | crontab -; then
        error "移除 DDNS crontab 失败"
        return 1
    fi
}

ddns_cf_record_ensure() {
    local zone_id="$1" token="$2" type="$3" domain="$4" placeholder="$5" ttl="$6" proxied="$7"
    local record_resp exact_records record_count create_body create_resp create_ok
    record_resp=$(curl -s --max-time 10 \
        "https://api.cloudflare.com/client/v4/zones/${zone_id}/dns_records?name=${domain}&type=${type}" \
        -H "Authorization: Bearer ${token}")
    if ! exact_records=$(printf '%s' "$record_resp" | ddns_cf_exact_records "$type" "$domain"); then
        error "查询 ${type} 记录失败，请检查网络和 Token 权限"
        return 1
    fi
    record_count=$(printf '%s\n' "$exact_records" | awk 'NF { count++ } END { print count + 0 }')
    if [ "$record_count" -gt 1 ]; then
        error "检测到 ${record_count} 条重复的 ${type} 记录 ${domain}，为避免更新错误已停止"
        echo -e "  ${DIM}请在 DNS 控制台仅保留一条同名同类型记录后重试${NC}"
        return 1
    fi
    if [ "$record_count" = "0" ]; then
        warn "未找到 ${type} 记录 ${domain}，正在自动创建..."
        create_body=$(printf '{"type":"%s","name":"%s","content":"%s","ttl":%s,"proxied":%s}' \
            "$type" "$domain" "$placeholder" "$ttl" "$proxied")
        create_resp=$(curl -s -X POST --max-time 10 \
            "https://api.cloudflare.com/client/v4/zones/${zone_id}/dns_records" \
            -H "Authorization: Bearer ${token}" \
            -H "Content-Type: application/json" \
            --data "$create_body")
        create_ok=$(echo "$create_resp" | python3 -c \
            "import sys,json; print(json.load(sys.stdin).get('success',''))" 2>/dev/null)
        if [ "$create_ok" = "True" ]; then
            info "${type} 记录已创建 ✓"
        else
            error "创建 ${type} 记录失败"
            return 1
        fi
    else
        info "${type} 记录 ${domain} 已存在 ✓"
    fi
}

ddns_cf_cleanup_cross_record() {
    local zone_id="$1" token="$2" type="$3" domain="$4" reason="$5"
    local record_resp exact_records record_count choice record_id content delete_resp delete_ok failed=0
    record_resp=$(curl -s --max-time 10 \
        "https://api.cloudflare.com/client/v4/zones/${zone_id}/dns_records?name=${domain}&type=${type}" \
        -H "Authorization: Bearer ${token}")
    if ! exact_records=$(printf '%s' "$record_resp" | ddns_cf_exact_records "$type" "$domain"); then
        warn "无法检查可能残留的 ${type} 记录 ${domain}"
        return 0
    fi
    record_count=$(printf '%s\n' "$exact_records" | awk 'NF { count++ } END { print count + 0 }')
    [ "$record_count" -gt 0 ] || return 0

    echo ""
    warn "检测到${reason}：${type} ${domain}（${record_count} 条）"
    while IFS=$'\t' read -r record_id content; do
        [ -n "$record_id" ] && echo -e "  ${DIM}${type} ${domain} → ${content:-空值}  ID: ${record_id}${NC}"
    done <<< "$exact_records"
    read -rp "  是否删除上述交叉记录？(y/N，默认N): " choice
    echo "$choice" | grep -qiE '^y(es)?$' || { warn "已保留上述记录"; return 0; }

    while IFS=$'\t' read -r record_id content; do
        [ -n "$record_id" ] || continue
        delete_resp=$(curl -s -X DELETE --max-time 10 \
            "https://api.cloudflare.com/client/v4/zones/${zone_id}/dns_records/${record_id}" \
            -H "Authorization: Bearer ${token}")
        delete_ok=$(printf '%s' "$delete_resp" | python3 -c \
            "import sys,json; print(json.load(sys.stdin).get('success',''))" 2>/dev/null)
        if [ "$delete_ok" = "True" ]; then
            info "已删除 ${type} ${domain}（${content:-空值}）✓"
        else
            error "删除 ${type} ${domain} 失败，记录 ID: ${record_id}"
            failed=1
        fi
    done <<< "$exact_records"
    return "$failed"
}

ddns_type_status_file() {
    case "$1" in
        A|AAAA) echo "${DDNS_STATE_DIR:-/root}/.cf_last_status_$1" ;;
        *) echo "${DDNS_STATE_DIR:-/root}/.cf_last_status" ;;
    esac
}

ddns_type_change_file() {
    case "$1" in
        A|AAAA) echo "${DDNS_STATE_DIR:-/root}/.cf_last_change_$1" ;;
        *) echo "${DDNS_STATE_DIR:-/root}/.cf_last_change" ;;
    esac
}

ddns_line_from_state_file() {
    local type="$1" domain_filter="${2:-}" file ts record_type domain state old_ip new_ip
    file=$(ddns_type_status_file "$type")
    [ -f "$file" ] || return 1
    IFS='|' read -r ts record_type domain state old_ip new_ip < "$file"
    [ -n "$ts" ] && [ -n "$record_type" ] && [ -n "$domain" ] || return 1
    [ -z "$domain_filter" ] || [ "$domain" = "$domain_filter" ] || return 1
    case "$state" in
        unchanged) printf '[%s] OK: %s %s 未变化 %s\n' "$ts" "$record_type" "$domain" "${new_ip:-$old_ip}" ;;
        updated) printf '[%s] OK: %s %s 更新成功 %s → %s\n' "$ts" "$record_type" "$domain" "${old_ip:-?}" "${new_ip:-?}" ;;
        fetch_failed) printf '[%s] ERROR: %s %s 无法获取公网 IP\n' "$ts" "$record_type" "$domain" ;;
        invalid_ip) printf '[%s] ERROR: %s %s 获取到的 IP 非法：%s\n' "$ts" "$record_type" "$domain" "${new_ip:-?}" ;;
        missing) printf '[%s] ERROR: %s 记录不存在 %s\n' "$ts" "$record_type" "$domain" ;;
        duplicate) printf '[%s] ERROR: %s %s 存在 %s 条重复记录\n' "$ts" "$record_type" "$domain" "${old_ip:-?}" ;;
        query_failed) printf '[%s] WARN: %s %s 无法获取当前记录值\n' "$ts" "$record_type" "$domain" ;;
        verify_skipped) printf '[%s] WARN: %s %s 二次校验异常，跳过更新\n' "$ts" "$record_type" "$domain" ;;
        update_failed) printf '[%s] ERROR: %s %s 更新失败 %s → %s\n' "$ts" "$record_type" "$domain" "${old_ip:-?}" "${new_ip:-?}" ;;
        *) printf '[%s] %s: %s %s %s → %s\n' "$ts" "$state" "$record_type" "$domain" "${old_ip:-?}" "${new_ip:-?}" ;;
    esac
}

ddns_line_from_change_file() {
    local type="$1" domain_filter="${2:-}" file ts record_type domain old_ip new_ip kind line
    file=$(ddns_type_change_file "$type")
    if [ ! -f "$file" ] && [ -f "${DDNS_STATE_DIR:-/root}/.cf_last_change" ]; then
        line=$(cat "${DDNS_STATE_DIR:-/root}/.cf_last_change" 2>/dev/null)
        record_type=$(echo "$line" | cut -d'|' -f2)
        domain=$(echo "$line" | cut -d'|' -f5)
        if [ "$record_type" = "$type" ] && { [ -z "$domain_filter" ] || [ "$domain" = "$domain_filter" ]; }; then
            file="${DDNS_STATE_DIR:-/root}/.cf_last_change"
        fi
    fi
    [ -f "$file" ] || return 1
    IFS='|' read -r ts record_type old_ip new_ip domain kind < "$file"
    [ -n "$ts" ] && [ "$record_type" = "$type" ] || return 1
    [ -z "$domain_filter" ] || [ "$domain" = "$domain_filter" ] || return 1
    if [ "$kind" = "synced" ]; then
        printf '[%s] OK: %s %s IP变化 %s → %s（DNS已同步）\n' "$ts" "$record_type" "${domain:-?}" "${old_ip:-?}" "${new_ip:-?}"
    else
        printf '[%s] OK: %s %s 更新成功 %s → %s\n' "$ts" "$record_type" "${domain:-?}" "${old_ip:-?}" "${new_ip:-?}"
    fi
}

ddns_latest_log_line() {
    local type="$1" domain="$2" log="$3"
    [ -n "$domain" ] && [ -f "$log" ] || return 1
    grep -F "OK: ${type} ${domain} " "$log" 2>/dev/null | tail -1
}

ddns_latest_change_log_line() {
    local type="$1" domain="$2" log="$3"
    [ -n "$domain" ] && [ -f "$log" ] || return 1
    grep -F "OK: ${type} ${domain} " "$log" 2>/dev/null | grep -E "更新成功|IP变化" | tail -1
}

ddns_line_time() {
    local line="$1"
    case "$line" in
        \[*\]*)
            line=${line#\[}
            echo "${line%%\]*}"
            ;;
    esac
}

ddns_line_ip_tail() {
    local ip="$1"
    ip=${ip%% *}
    ip=${ip%%（*}
    echo "$ip"
}

ddns_line_result_ip() {
    local line="$1" ip
    case "$line" in
        *" → "*)
            ip=${line##* → }
            ddns_line_ip_tail "$ip"
            ;;
        *"未变化 "*)
            ip=${line##*未变化 }
            ddns_line_ip_tail "$ip"
            ;;
        *"创建成功 "*)
            ip=${line##*创建成功 }
            ddns_line_ip_tail "$ip"
            ;;
    esac
}

ddns_newer_line() {
    local first="$1" second="$2" first_time second_time
    [ -n "$first" ] || [ -n "$second" ] || return 1
    [ -n "$first" ] || { echo "$second"; return 0; }
    [ -n "$second" ] || { echo "$first"; return 0; }
    first_time=$(ddns_line_time "$first")
    second_time=$(ddns_line_time "$second")
    if [ -z "$first_time" ] && [ -n "$second_time" ]; then
        echo "$second"
    elif [ -n "$first_time" ] && [ -n "$second_time" ] && [[ "$second_time" > "$first_time" ]]; then
        echo "$second"
    else
        echo "$first"
    fi
}

ddns_change_matches_status() {
    local change_line="$1" status_ip="$2" change_ip
    [ -n "$change_line" ] || return 1
    [ -n "$status_ip" ] || return 0
    change_ip=$(ddns_line_result_ip "$change_line")
    [ -z "$change_ip" ] || [ "$change_ip" = "$status_ip" ]
}

ddns_record_status_line() {
    local type="$1" domain="$2" log="$3" state_line log_line
    state_line=$(ddns_line_from_state_file "$type" "$domain" 2>/dev/null || true)
    log_line=$(ddns_latest_log_line "$type" "$domain" "$log" 2>/dev/null || true)
    ddns_newer_line "$state_line" "$log_line"
}

ddns_record_change_line() {
    local type="$1" domain="$2" log="$3" status_line status_ip state_line log_line state_match log_match line
    state_match=""
    log_match=""
    status_line=$(ddns_record_status_line "$type" "$domain" "$log" 2>/dev/null || true)
    status_ip=$(ddns_line_result_ip "$status_line")
    state_line=$(ddns_line_from_change_file "$type" "$domain" 2>/dev/null || true)
    log_line=$(ddns_latest_change_log_line "$type" "$domain" "$log" 2>/dev/null || true)
    if ddns_change_matches_status "$state_line" "$status_ip"; then
        state_match="$state_line"
    fi
    if ddns_change_matches_status "$log_line" "$status_ip"; then
        log_match="$log_line"
    fi
    line=$(ddns_newer_line "$state_match" "$log_match" 2>/dev/null || true)
    [ -n "$line" ] || return 1
    echo "$line"
}

ddns_print_record_summary() {
    local label="$1" type="$2" domain="$3" log="$4" status_line change_line
    [ -n "$domain" ] || return 0
    status_line=$(ddns_record_status_line "$type" "$domain" "$log" 2>/dev/null || true)
    if [ -n "$status_line" ]; then
        echo -e "  最新 ${label}: ${DIM}${status_line}${NC}"
    else
        echo -e "  最新 ${label}: ${DIM}等待下一次更新${NC}"
    fi
    change_line=$(ddns_record_change_line "$type" "$domain" "$log" 2>/dev/null || true)
    if [ -n "$change_line" ]; then
        echo -e "  变更 ${label}: ${DIM}${change_line}${NC}"
    else
        echo -e "  变更 ${label}: ${DIM}暂无当前 IP 变更记录${NC}"
    fi
}

ddns_ensure_cron() {
    if command -v crontab &>/dev/null; then
        ddns_start_cron_service
        return $?
    fi
    info "未检测到 crontab，正在安装 cron..."
    if command -v apt-get &>/dev/null; then
        apt-get update -qq 2>/dev/null
        apt-get install -y cron 2>/dev/null || apt-get install -y cronie 2>/dev/null || return 1
    elif command -v apk &>/dev/null; then
        apk add --no-cache dcron 2>/dev/null || apk add --no-cache cronie 2>/dev/null || return 1
    elif command -v yum &>/dev/null; then
        yum install -y cronie 2>/dev/null || return 1
    elif command -v dnf &>/dev/null; then
        dnf install -y cronie 2>/dev/null || return 1
    else
        error "找不到包管理器，请手动安装 cron：apt-get install -y cron"
        return 1
    fi
    # 安装后立即启动服务
    ddns_start_cron_service >/dev/null 2>&1 || true
    sleep 1
    if command -v crontab &>/dev/null && ddns_cron_service_running; then
        info "cron 安装并启动成功 ✓"
        return 0
    else
        error "cron 安装后仍无法使用或服务未运行"
        return 1
    fi
}

ddns_start_cron_service() {
    for svc in cron crond dcron; do
        if systemd_available; then
            systemctl enable "$svc" --quiet 2>/dev/null || true
            systemctl start "$svc" 2>/dev/null || true
        fi
        if command -v rc-service &>/dev/null; then
            rc-service "$svc" start 2>/dev/null || true
        fi
        if command -v service &>/dev/null; then
            service "$svc" start >/dev/null 2>&1 || true
        fi
    done
    ddns_cron_service_running
}

ddns_cron_service_running() {
    local svc
    for svc in cron crond dcron; do
        if systemd_available && systemctl is-active --quiet "$svc" 2>/dev/null; then
            return 0
        fi
        if command -v rc-service &>/dev/null && rc-service "$svc" status >/dev/null 2>&1; then
            return 0
        fi
        if command -v service &>/dev/null && service "$svc" status >/dev/null 2>&1; then
            return 0
        fi
    done
    pgrep -x cron >/dev/null 2>&1 || pgrep -x crond >/dev/null 2>&1 || pgrep -x dcron >/dev/null 2>&1
}

# ── 检测 DDNS 安装状态 ────────────────────────────────────
ddns_status() {
    if [ ! -f "$DDNS_SCRIPT" ]; then
        echo "not_installed"
    elif ! command -v crontab &>/dev/null; then
        echo "no_cron"
    elif ! crontab -l 2>/dev/null | grep -Fq -e "$DDNS_CRON_MARKER" -e "$DDNS_SCRIPT"; then
        echo "stopped"
    elif ! ddns_cron_service_running; then
        echo "cron_stopped"
    else
        echo "running"
    fi
}

# ── 安装/配置 DDNS ────────────────────────────────────────
ddns_install_cloudflare() {
    print_header "Cloudflare DDNS 配置"
    echo -e "  ${DIM}动态 DNS：可分别将 A / AAAA 记录更新为本机公网 IP${NC}"
    echo ""

    for cmd in curl python3; do
        if ! command -v "$cmd" &>/dev/null; then
            info "安装依赖 $cmd..."
            pkg_install "$cmd" &>/dev/null || true
            if ! command -v "$cmd" &>/dev/null; then
                error "依赖 ${cmd} 安装失败，请手动安装后重试"
                return 1
            fi
        fi
    done
    if ! ddns_ensure_cron; then
        error "无法安装或启用 crontab/cron，请先手动安装 cron 后重试"
        return
    fi
    if ! ddns_start_cron_service >/dev/null 2>&1; then
        error "cron 服务无法启动，请修复后重试"
        return 1
    fi

    menu_div
    read -rp "  根域名（如 example.com）: " DDNS_ZONE_NAME
    [ -z "$DDNS_ZONE_NAME" ] && { warn "已取消"; return; }
    if ! DDNS_ZONE_NAME=$(ddns_domain_normalize "$DDNS_ZONE_NAME"); then
        error "根域名格式无效"
        return 1
    fi

    local DDNS_ENABLE_A="true" DDNS_ENABLE_AAAA="false"
    local DDNS_SUB4="" DDNS_SUB6="" DDNS_DOMAIN4="" DDNS_DOMAIN6=""

    read -rp "  启用 IPv4 A 记录？(Y/n，默认Y): " DDNS_A_CH
    if echo "$DDNS_A_CH" | grep -qiE '^n(o)?$'; then
        DDNS_ENABLE_A="false"
    else
        read -rp "  IPv4 子域名（A，如 home；@ 表示根域）: " DDNS_SUB4
        [ -z "$DDNS_SUB4" ] && { warn "已取消"; return; }
        DDNS_DOMAIN4=$(ddns_build_domain "$DDNS_SUB4" "$DDNS_ZONE_NAME")
    fi

    local V6_DEFAULT="N"
    [ "$DDNS_ENABLE_A" = "false" ] && V6_DEFAULT="Y"
    read -rp "  启用 IPv6 AAAA 记录？($([ "$V6_DEFAULT" = "Y" ] && echo 'Y/n' || echo 'y/N')，默认${V6_DEFAULT}): " DDNS_AAAA_CH
    case "$DDNS_AAAA_CH" in
        "")
            [ "$V6_DEFAULT" = "Y" ] && DDNS_ENABLE_AAAA="true" || DDNS_ENABLE_AAAA="false"
            ;;
        y|Y|yes|YES) DDNS_ENABLE_AAAA="true" ;;
        *) DDNS_ENABLE_AAAA="false" ;;
    esac

    if [ "$DDNS_ENABLE_AAAA" = "true" ]; then
        local DDNS_SUB6_DEFAULT DDNS_SHARE_DOMAIN=""
        if [ "$DDNS_ENABLE_A" = "true" ]; then
            read -rp "  A 与 AAAA 共用同一个域名 ${DDNS_DOMAIN4}？(y/N，默认N): " DDNS_SHARE_DOMAIN
        fi
        if echo "$DDNS_SHARE_DOMAIN" | grep -qiE '^y(es)?$'; then
            DDNS_SUB6="$DDNS_SUB4"
        else
            if [ "$DDNS_ENABLE_A" = "true" ]; then
                DDNS_SUB6_DEFAULT=$(ddns_ipv6_subdomain_default "$DDNS_SUB4")
            else
                DDNS_SUB6_DEFAULT="home"
            fi
            read -rp "  IPv6 子域名（AAAA，默认 ${DDNS_SUB6_DEFAULT}；@ 表示根域）: " DDNS_SUB6
            [ -z "$DDNS_SUB6" ] && DDNS_SUB6="$DDNS_SUB6_DEFAULT"
            if [ "$DDNS_ENABLE_A" = "true" ] && [ "$DDNS_SUB6" = "$DDNS_SUB4" ]; then
                error "已选择独立域名，但 A 与 AAAA 子域名相同；如需共用请在上一项选择 y"
                return 1
            fi
        fi
        DDNS_DOMAIN6=$(ddns_build_domain "$DDNS_SUB6" "$DDNS_ZONE_NAME")
    fi

    if [ "$DDNS_ENABLE_A" != "true" ] && [ "$DDNS_ENABLE_AAAA" != "true" ]; then
        error "至少需要启用 IPv4 A 或 IPv6 AAAA 其中一种记录"
        return
    fi
    if [ "$DDNS_ENABLE_A" = "true" ]; then
        if ! DDNS_DOMAIN4=$(ddns_domain_normalize "$DDNS_DOMAIN4") || ! ddns_domain_in_zone "$DDNS_DOMAIN4" "$DDNS_ZONE_NAME"; then
            error "IPv4 域名格式无效或不属于根域名 ${DDNS_ZONE_NAME}"
            return 1
        fi
    fi
    if [ "$DDNS_ENABLE_AAAA" = "true" ]; then
        if ! DDNS_DOMAIN6=$(ddns_domain_normalize "$DDNS_DOMAIN6") || ! ddns_domain_in_zone "$DDNS_DOMAIN6" "$DDNS_ZONE_NAME"; then
            error "IPv6 域名格式无效或不属于根域名 ${DDNS_ZONE_NAME}"
            return 1
        fi
    fi

    read -rp "  Cloudflare API Token（输入可见）: " DDNS_TOKEN
    [ -z "$DDNS_TOKEN" ] && { warn "已取消"; return; }

    local DDNS_MODE="ipv4"
    if [ "$DDNS_ENABLE_A" = "true" ] && [ "$DDNS_ENABLE_AAAA" = "true" ]; then
        DDNS_MODE="dual"
    elif [ "$DDNS_ENABLE_AAAA" = "true" ]; then
        DDNS_MODE="ipv6"
    fi

    local DDNS_PROXIED="false"
    read -rp "  是否开启 Cloudflare 代理（橙云）？(y/N，默认N): " DDNS_PROXY_CH
    echo "$DDNS_PROXY_CH" | grep -qiE '^y(es)?$' && DDNS_PROXIED="true"

    local DDNS_TTL="60"
    read -rp "  TTL 秒数（默认60）: " DDNS_TTL_IN
    if ! DDNS_TTL=$(ddns_cf_ttl_normalize "${DDNS_TTL_IN:-60}"); then
        error "Cloudflare TTL 必须为 1（自动）或 60-86400 秒"
        return 1
    fi
    if [ "$DDNS_PROXIED" = "true" ] && [ "$DDNS_TTL" != "1" ]; then
        warn "Cloudflare 代理记录使用自动 TTL，已调整为 1"
        DDNS_TTL=1
    fi
    local DDNS_INTERVAL_MIN
    DDNS_INTERVAL_MIN=$(ddns_prompt_interval 5)

    echo ""
    menu_div
    [ "$DDNS_ENABLE_A" = "true" ] && echo -e "  IPv4 A : ${BOLD}${DDNS_DOMAIN4}${NC}" || echo -e "  IPv4 A : ${DIM}未启用${NC}"
    [ "$DDNS_ENABLE_AAAA" = "true" ] && echo -e "  IPv6 AAAA : ${BOLD}${DDNS_DOMAIN6}${NC}" || echo -e "  IPv6 AAAA : ${DIM}未启用${NC}"
    if [ "$DDNS_ENABLE_A" = "true" ] && [ "$DDNS_ENABLE_AAAA" = "true" ]; then
        [ "$DDNS_DOMAIN4" = "$DDNS_DOMAIN6" ] \
            && echo -e "  记录方式 : ${BOLD}共用域名（同一域名各 1 条 A / AAAA）${NC}" \
            || echo -e "  记录方式 : ${BOLD}独立域名（IPv4 / IPv6 各 1 条）${NC}"
    fi
    echo -e "  代理   : ${BOLD}$([ "$DDNS_PROXIED" = "true" ] && echo '开启' || echo '关闭')${NC}"
    echo -e "  TTL    : ${BOLD}${DDNS_TTL}${NC}"
    echo -e "  间隔   : ${BOLD}${DDNS_INTERVAL_MIN} 分钟${NC}"
    echo -e "  Token  : ${BOLD}${DDNS_TOKEN:0:8}…${NC}"
    menu_div
    echo ""
    read -rp "  确认安装？(Y/n，默认Y): " CONFIRM
    [ -z "$CONFIRM" ] && CONFIRM="y"
    if ! echo "$CONFIRM" | grep -qiE '^y(es)?$'; then warn "已取消"; return; fi

    echo ""
    info "验证 Token 和域名..."
    local ZONE_RESP ZONE_OK ZONE_COUNT ZONE_ID
    ZONE_RESP=$(curl -s --max-time 10         "https://api.cloudflare.com/client/v4/zones?name=${DDNS_ZONE_NAME}"         -H "Authorization: Bearer ${DDNS_TOKEN}")
    ZONE_OK=$(echo "$ZONE_RESP" | python3 -c         "import sys,json; print(json.load(sys.stdin).get('success',''))" 2>/dev/null)
    if [ "$ZONE_OK" != "True" ]; then
        error "Token 验证失败，请检查 Token 权限（需要 Zone:DNS:Edit）"
        return
    fi
    ZONE_COUNT=$(echo "$ZONE_RESP" | python3 -c         "import sys,json; print(len(json.load(sys.stdin)['result']))" 2>/dev/null)
    if [ "$ZONE_COUNT" = "0" ]; then
        error "找不到域名 ${DDNS_ZONE_NAME}，请确认已托管到此 Cloudflare 账号"
        return
    fi
    ZONE_ID=$(echo "$ZONE_RESP" | python3 -c         "import sys,json; print(json.load(sys.stdin)['result'][0]['id'])")
    info "Token 有效，Zone ID: ${ZONE_ID} ✓"

    local DDNS_INITIAL_IP4="" DDNS_INITIAL_IP6=""
    if [ "$DDNS_ENABLE_A" = "true" ]; then
        DDNS_INITIAL_IP4=$(ddns_fetch_public_ip 4) || { error "无法获取有效公网 IPv4，未创建或修改 A 记录"; return 1; }
        ddns_cf_record_ensure "$ZONE_ID" "$DDNS_TOKEN" A "$DDNS_DOMAIN4" "$DDNS_INITIAL_IP4" "$DDNS_TTL" "$DDNS_PROXIED" || return
    fi
    if [ "$DDNS_ENABLE_AAAA" = "true" ]; then
        DDNS_INITIAL_IP6=$(ddns_fetch_public_ip 6) || { error "无法获取有效公网 IPv6，未创建或修改 AAAA 记录"; return 1; }
        ddns_cf_record_ensure "$ZONE_ID" "$DDNS_TOKEN" AAAA "$DDNS_DOMAIN6" "$DDNS_INITIAL_IP6" "$DDNS_TTL" "$DDNS_PROXIED" || return
    fi
    if [ "$DDNS_ENABLE_A" = "true" ] && [ "$DDNS_ENABLE_AAAA" = "true" ] && [ "$DDNS_DOMAIN4" != "$DDNS_DOMAIN6" ]; then
        ddns_cf_cleanup_cross_record "$ZONE_ID" "$DDNS_TOKEN" AAAA "$DDNS_DOMAIN4" "IPv4 域名上的额外 AAAA 记录" || true
        ddns_cf_cleanup_cross_record "$ZONE_ID" "$DDNS_TOKEN" A "$DDNS_DOMAIN6" "IPv6 域名上的额外 A 记录" || true
    fi

    if ! ddns_install_tx_begin; then
        error "无法创建 DDNS 配置回滚快照"
        return 1
    fi

    # 保存配置
    if ! printf '%s\n' "$DDNS_TOKEN" > "$DDNS_TOKEN_FILE" || ! chmod 600 "$DDNS_TOKEN_FILE"; then
        error "无法保存 Cloudflare Token"
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    fi
    if ! touch "$DDNS_LOG" 2>/dev/null; then
        DDNS_LOG="$HOME/ddns.log"
        if ! touch "$DDNS_LOG" 2>/dev/null; then
            error "无法创建 DDNS 日志文件"
            ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
            return 1
        fi
    fi
    chmod 644 "$DDNS_LOG" 2>/dev/null || true
    local DDNS_PRIMARY_DOMAIN="${DDNS_DOMAIN4:-$DDNS_DOMAIN6}"
    {
        echo "PROVIDER=cloudflare"
        echo "DOMAIN=${DDNS_PRIMARY_DOMAIN}"
        echo "DOMAIN4=${DDNS_DOMAIN4}"
        echo "DOMAIN6=${DDNS_DOMAIN6}"
        echo "ZONE=${DDNS_ZONE_NAME}"
        echo "MODE=${DDNS_MODE}"
        echo "ENABLE_A=${DDNS_ENABLE_A}"
        echo "ENABLE_AAAA=${DDNS_ENABLE_AAAA}"
        echo "PROXIED=${DDNS_PROXIED}"
        echo "TTL=${DDNS_TTL}"
        echo "INTERVAL_MIN=${DDNS_INTERVAL_MIN}"
        echo "LOG=${DDNS_LOG}"
    } > "$DDNS_ZONE_FILE" || {
        error "无法保存 DDNS 配置"
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    }

    # 生成 DDNS 执行脚本
    if ! cat > "$DDNS_SCRIPT" << 'DDNS_INNER'
#!/bin/bash
# 注入 PATH，确保 crontab 环境下能找到 curl / python3
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin

DOMAIN4="__DOMAIN4__"
DOMAIN6="__DOMAIN6__"
ZONE="__ZONE__"
ENABLE_A="__ENABLE_A__"
ENABLE_AAAA="__ENABLE_AAAA__"
PROXIED="__PROXIED__"
TTL="__TTL__"
TOKEN_FILE="/root/.cf_token"
LOG_FILE="__LOG__"
STATE_DIR="${DDNS_STATE_DIR:-/root}"
LOCK_FILE="/run/vps-tools-ddns.lockfile"
LOCK_DIR="/run/vps-tools-ddns.lock"

acquire_lock() {
    if command -v flock >/dev/null 2>&1; then
        exec 9>"$LOCK_FILE" || return 1
        flock -n 9 || return 75
        return 0
    fi
    if mkdir "$LOCK_DIR" 2>/dev/null; then
        printf '%s\n' "$$" > "$LOCK_DIR/pid"
        trap 'rm -rf -- "$LOCK_DIR"' EXIT
        return 0
    fi
    local LOCK_PID=""
    [ -f "$LOCK_DIR/pid" ] && read -r LOCK_PID < "$LOCK_DIR/pid"
    if [ -n "$LOCK_PID" ] && kill -0 "$LOCK_PID" 2>/dev/null; then
        return 75
    fi
    rm -rf -- "$LOCK_DIR" 2>/dev/null || return 1
    mkdir "$LOCK_DIR" 2>/dev/null || return 75
    printf '%s\n' "$$" > "$LOCK_DIR/pid"
    trap 'rm -rf -- "$LOCK_DIR"' EXIT
}

acquire_lock || exit $?

API_TOKEN=$(cat "$TOKEN_FILE" 2>/dev/null)
[ -z "$API_TOKEN" ] && exit 1

# 日志轮转：最多保留 500 条记录（每次运行检查）
if [ -f "$LOG_FILE" ]; then
    LOG_LINES=$(wc -l < "$LOG_FILE" 2>/dev/null || echo 0)
    if [ "$LOG_LINES" -gt 500 ]; then
        tail -n 500 "$LOG_FILE" > "${LOG_FILE}.tmp" && mv "${LOG_FILE}.tmp" "$LOG_FILE"
    fi
fi

is_true() {
    case "$1" in
        1|true|TRUE|yes|YES|on|ON) return 0 ;;
        *) return 1 ;;
    esac
}

log_line() {
    printf '[%s] %s: %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$1" "$2" >> "$LOG_FILE"
}

record_status_file() {
    case "$1" in
        A|AAAA) echo "${STATE_DIR}/.cf_last_status_$1" ;;
        *) echo "${STATE_DIR}/.cf_last_status" ;;
    esac
}

record_change_file() {
    case "$1" in
        A|AAAA) echo "${STATE_DIR}/.cf_last_change_$1" ;;
        *) echo "${STATE_DIR}/.cf_last_change" ;;
    esac
}

record_ip_file() {
    case "$1" in
        A|AAAA) echo "${STATE_DIR}/.cf_last_ip_$1" ;;
        *) echo "${STATE_DIR}/.cf_last_ip" ;;
    esac
}

write_record_status() {
    local TYPE="$1" DOMAIN_NAME="$2" STATE="$3" OLD_IP="${4:-}" NEW_IP="${5:-}" FILE
    FILE=$(record_status_file "$TYPE")
    printf '%s|%s|%s|%s|%s|%s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$TYPE" "$DOMAIN_NAME" "$STATE" "$OLD_IP" "$NEW_IP" > "$FILE" 2>/dev/null || return 0
    chmod 600 "$FILE" 2>/dev/null || true
}

previous_record_ip() {
    local TYPE="$1" DOMAIN_NAME="$2" FILE _TS RECORD_TYPE RECORD_DOMAIN STATE OLD_IP NEW_IP IP
    FILE=$(record_ip_file "$TYPE")
    if [ -f "$FILE" ]; then
        IFS='|' read -r _TS RECORD_TYPE RECORD_DOMAIN IP < "$FILE"
        if [ "$RECORD_TYPE" = "$TYPE" ] && [ "$RECORD_DOMAIN" = "$DOMAIN_NAME" ] && [ -n "$IP" ]; then
            printf '%s\n' "$IP"
            return 0
        fi
    fi

    # 升级兼容：首次运行时从旧状态文件迁移最后一次成功 IP。
    FILE=$(record_status_file "$TYPE")
    [ -f "$FILE" ] || return 0
    IFS='|' read -r _TS RECORD_TYPE RECORD_DOMAIN STATE OLD_IP NEW_IP < "$FILE"
    [ "$RECORD_TYPE" = "$TYPE" ] && [ "$RECORD_DOMAIN" = "$DOMAIN_NAME" ] || return 0
    case "$STATE" in
        unchanged|updated) printf '%s\n' "${NEW_IP:-$OLD_IP}" ;;
    esac
}

write_record_ip() {
    local TYPE="$1" DOMAIN_NAME="$2" IP="$3" FILE
    [ -n "$IP" ] || return 0
    FILE=$(record_ip_file "$TYPE")
    printf '%s|%s|%s|%s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$TYPE" "$DOMAIN_NAME" "$IP" > "$FILE" 2>/dev/null || return 0
    chmod 600 "$FILE" 2>/dev/null || true
}

write_record_change() {
    local TYPE="$1" DOMAIN_NAME="$2" OLD_IP="$3" NEW_IP="$4" KIND="${5:-updated}" LINE FILE
    LINE="$(date '+%Y-%m-%d %H:%M:%S')|${TYPE}|${OLD_IP}|${NEW_IP}|${DOMAIN_NAME}|${KIND}"
    FILE=$(record_change_file "$TYPE")
    printf '%s\n' "$LINE" > "$FILE" 2>/dev/null || true
    chmod 600 "$FILE" 2>/dev/null || true
    printf '%s\n' "$LINE" > "${STATE_DIR}/.cf_last_change" 2>/dev/null || true
    chmod 600 "${STATE_DIR}/.cf_last_change" 2>/dev/null || true
}

# 发送 Telegram 通知（每次调用时实时读取配置文件，避免 crontab 变量丢失）
tg_notify() {
    local MSG="$1"
    local TG_FILE="/root/.cf_tg"
    [ -f "$TG_FILE" ] || return 0
    local B_TOKEN C_ID RESP DESCRIPTION
    B_TOKEN=$(grep "^BOT_TOKEN=" "$TG_FILE" | cut -d= -f2-)
    C_ID=$(grep "^CHAT_ID=" "$TG_FILE" | cut -d= -f2-)
    [ -z "$B_TOKEN" ] || [ -z "$C_ID" ] && return 0
    if ! RESP=$(curl -fsS --max-time 15 \
        "https://api.telegram.org/bot${B_TOKEN}/sendMessage" \
        --data-urlencode "chat_id=${C_ID}" \
        --data-urlencode "text=${MSG}" \
        --data-urlencode "parse_mode=HTML" 2>/dev/null); then
        log_line WARN "Telegram 通知发送失败：网络或 HTTP 错误"
        return 0
    fi
    if ! printf '%s' "$RESP" | python3 -c 'import json,sys; raise SystemExit(0 if json.load(sys.stdin).get("ok") is True else 1)' 2>/dev/null; then
        DESCRIPTION=$(printf '%s' "$RESP" | python3 -c 'import json,sys; print(str(json.load(sys.stdin).get("description") or "API 返回异常").replace("\n", " "))' 2>/dev/null || echo "API 返回异常")
        log_line WARN "Telegram 通知发送失败：${DESCRIPTION}"
    fi
}

fetch_ip4() {
    (
        curl -4 -fsS --max-time 5 https://api.ipify.org ||
        curl -4 -fsS --max-time 5 https://ifconfig.me/ip ||
        curl -4 -fsS --max-time 5 https://ip.sb
    ) 2>/dev/null | tr -d ' \r\n'
}

fetch_ip6() {
    local IP
    IP=$( (
        curl -6 -fsS --max-time 5 https://api64.ipify.org ||
        curl -6 -fsS --max-time 5 https://ipv6.icanhazip.com ||
        curl -6 -fsS --max-time 5 https://ip.sb
    ) 2>/dev/null | tr -d ' \r\n')
    [ -n "$IP" ] && { echo "$IP"; return 0; }
    fetch_ip6_local
}

fetch_ip6_local() {
    command -v ip >/dev/null 2>&1 || return 0
    command -v python3 >/dev/null 2>&1 || return 0
    local ROUTE
    ROUTE=$(ip -6 route get 2606:4700:4700::1111 2>/dev/null) || return 0
    printf '%s\n' "$ROUTE" | python3 -c '
import ipaddress
import sys
for line in sys.stdin:
    parts = line.split()
    if "src" not in parts:
        continue
    try:
        addr = parts[parts.index("src") + 1].split("/")[0]
        ip = ipaddress.ip_address(addr)
    except Exception:
        continue
    if ip.version == 6 and ip.is_global:
        print(ip.compressed)
        break
'
}

valid_ipv4() {
    echo "$1" | grep -qE '^([0-9]{1,3}\.){3}[0-9]{1,3}$' && \
    echo "$1" | awk -F. '{for(i=1;i<=4;i++) if($i<0||$i>255) exit 1}'
}

valid_ipv6() {
    python3 -c "import ipaddress,sys; ip=ipaddress.ip_address(sys.argv[1]); sys.exit(0 if ip.version == 6 and ip.is_global else 1)" "$1" 2>/dev/null
}

cf_record_info() {
    local TYPE="$1" DOMAIN_NAME="$2"
    JSON_INPUT=$(cat) python3 - "$TYPE" "$DOMAIN_NAME" <<'PY'
import json
import os
import sys

rtype = sys.argv[1].upper()
target = sys.argv[2].rstrip(".").lower()
try:
    data = json.loads(os.environ.get("JSON_INPUT", "{}"))
except Exception:
    raise SystemExit(0)
if data.get("success") is not True or not isinstance(data.get("result"), list):
    raise SystemExit(0)
matches = []
for record in data["result"]:
    name = str(record.get("name") or "").rstrip(".").lower()
    if name == target and str(record.get("type") or "").upper() == rtype and record.get("id"):
        matches.append(record)
if len(matches) > 1:
    print(f"DUPLICATE|{len(matches)}")
elif matches:
    content = str(matches[0].get("content") or "").replace("\n", " ").replace("|", " ")
    print(f"{matches[0]['id']}|{content}")
PY
}

if { is_true "$ENABLE_A" && [ -z "$DOMAIN4" ]; } || { is_true "$ENABLE_AAAA" && [ -z "$DOMAIN6" ]; }; then
    log_line ERROR "启用的 A / AAAA 记录缺少域名，请重新生成 DDNS 配置"
    exit 1
fi

ZONE_ID=$(curl -s --max-time 8 "https://api.cloudflare.com/client/v4/zones?name=${ZONE}"     -H "Authorization: Bearer ${API_TOKEN}" |     python3 -c "import sys,json; print(json.load(sys.stdin)['result'][0]['id'])" 2>/dev/null)
[ -z "$ZONE_ID" ] && {
    echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: 获取 Zone ID 失败" >> "$LOG_FILE"
    exit 1
}

update_record() {
    local TYPE="$1" DOMAIN_NAME="$2" NEW_IP="$3"
    [ -z "$NEW_IP" ] && return 0
    [ -z "$DOMAIN_NAME" ] && return 0
    local RECORD_INFO RECORD_ID RECORD_COUNT OLD_IP RESULT SUCCESS
    RECORD_INFO=$(curl -s --max-time 8 \
        "https://api.cloudflare.com/client/v4/zones/${ZONE_ID}/dns_records?name=${DOMAIN_NAME}&type=${TYPE}" \
        -H "Authorization: Bearer ${API_TOKEN}" | cf_record_info "$TYPE" "$DOMAIN_NAME")
    case "$RECORD_INFO" in
        DUPLICATE\|*)
            RECORD_COUNT=${RECORD_INFO#*|}
            echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: ${TYPE} ${DOMAIN_NAME} 存在 ${RECORD_COUNT} 条重复记录，已停止更新" >> "$LOG_FILE"
            write_record_status "$TYPE" "$DOMAIN_NAME" duplicate "$RECORD_COUNT" "$NEW_IP"
            return 1
            ;;
    esac
    RECORD_ID=${RECORD_INFO%%|*}
    [ -z "$RECORD_ID" ] && {
        echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: ${TYPE} 记录不存在 ${DOMAIN_NAME}" >> "$LOG_FILE"
        write_record_status "$TYPE" "$DOMAIN_NAME" missing "" "$NEW_IP"
        return 1
    }
    OLD_IP=$(curl -s --max-time 8         "https://api.cloudflare.com/client/v4/zones/${ZONE_ID}/dns_records/${RECORD_ID}"         -H "Authorization: Bearer ${API_TOKEN}" |         python3 -c "import sys,json; print(json.load(sys.stdin)['result']['content'])" 2>/dev/null)
    # OLD_IP 为空说明查询失败，跳过本次更新避免误推 Telegram
    if [ -z "$OLD_IP" ]; then
        echo "[$(date '+%Y-%m-%d %H:%M:%S')] WARN: ${TYPE} 无法获取当前记录值，跳过更新" >> "$LOG_FILE"
        write_record_status "$TYPE" "$DOMAIN_NAME" query_failed "" "$NEW_IP"
        return 0
    fi
    if [ "$NEW_IP" = "$OLD_IP" ]; then
        local PREV_IP
        PREV_IP=$(previous_record_ip "$TYPE" "$DOMAIN_NAME")
        write_record_ip "$TYPE" "$DOMAIN_NAME" "$NEW_IP"
        if [ -n "$PREV_IP" ] && [ "$PREV_IP" != "$NEW_IP" ]; then
            echo "[$(date '+%Y-%m-%d %H:%M:%S')] OK: ${TYPE} ${DOMAIN_NAME} IP变化 ${PREV_IP} → ${NEW_IP}（DNS已同步）" >> "$LOG_FILE"
            write_record_change "$TYPE" "$DOMAIN_NAME" "$PREV_IP" "$NEW_IP" synced
            tg_notify "🌐 <b>DDNS IP 已变化</b>
域名：<code>${DOMAIN_NAME}</code>
类型：${TYPE}
旧IP：<code>${PREV_IP}</code>
新IP：<code>${NEW_IP}</code>
状态：DNS 已同步
时间：$(date '+%Y-%m-%d %H:%M:%S')"
        else
            echo "[$(date '+%Y-%m-%d %H:%M:%S')] OK: ${TYPE} ${DOMAIN_NAME} 未变化 ${NEW_IP}" >> "$LOG_FILE"
        fi
        write_record_status "$TYPE" "$DOMAIN_NAME" unchanged "$OLD_IP" "$NEW_IP"
        return 0
    fi
    # 二次校验：再次查询确认 OLD_IP 是否真的不一样（防止偶发查询返回错误数据）
    local VERIFY_IP
    VERIFY_IP=$(curl -s --max-time 8 \
        "https://api.cloudflare.com/client/v4/zones/${ZONE_ID}/dns_records/${RECORD_ID}" \
        -H "Authorization: Bearer ${API_TOKEN}" | \
        python3 -c "import sys,json; print(json.load(sys.stdin)['result']['content'])" 2>/dev/null)
    if [ "$NEW_IP" = "$VERIFY_IP" ]; then
        local PREV_IP
        PREV_IP=$(previous_record_ip "$TYPE" "$DOMAIN_NAME")
        write_record_ip "$TYPE" "$DOMAIN_NAME" "$NEW_IP"
        if [ -n "$PREV_IP" ] && [ "$PREV_IP" != "$NEW_IP" ]; then
            echo "[$(date '+%Y-%m-%d %H:%M:%S')] OK: ${TYPE} ${DOMAIN_NAME} IP变化 ${PREV_IP} → ${NEW_IP}（DNS已同步，二次确认）" >> "$LOG_FILE"
            write_record_change "$TYPE" "$DOMAIN_NAME" "$PREV_IP" "$NEW_IP" synced
            tg_notify "🌐 <b>DDNS IP 已变化</b>
域名：<code>${DOMAIN_NAME}</code>
类型：${TYPE}
旧IP：<code>${PREV_IP}</code>
新IP：<code>${NEW_IP}</code>
状态：DNS 已同步（二次确认）
时间：$(date '+%Y-%m-%d %H:%M:%S')"
        else
            echo "[$(date '+%Y-%m-%d %H:%M:%S')] OK: ${TYPE} ${DOMAIN_NAME} 未变化 ${NEW_IP}（二次确认）" >> "$LOG_FILE"
        fi
        write_record_status "$TYPE" "$DOMAIN_NAME" unchanged "$VERIFY_IP" "$NEW_IP"
        return 0
    fi
    if [ -z "$VERIFY_IP" ] || [ "$VERIFY_IP" != "$OLD_IP" ]; then
        echo "[$(date '+%Y-%m-%d %H:%M:%S')] WARN: ${TYPE} 二次校验异常 (1st:${OLD_IP} 2nd:${VERIFY_IP})，跳过更新" >> "$LOG_FILE"
        write_record_status "$TYPE" "$DOMAIN_NAME" verify_skipped "$OLD_IP" "$NEW_IP"
        return 0
    fi
    local JSON_BODY
    JSON_BODY=$(printf '{"type":"%s","name":"%s","content":"%s","ttl":%s,"proxied":%s}' \
        "$TYPE" "$DOMAIN_NAME" "$NEW_IP" "$TTL" "$PROXIED")
    RESULT=$(curl -s -X PUT --max-time 10 \
        "https://api.cloudflare.com/client/v4/zones/${ZONE_ID}/dns_records/${RECORD_ID}" \
        -H "Authorization: Bearer ${API_TOKEN}" \
        -H "Content-Type: application/json" \
        --data "$JSON_BODY")
    SUCCESS=$(echo "$RESULT" | python3 -c         "import sys,json; print(json.load(sys.stdin).get('success'))" 2>/dev/null)
    if [ "$SUCCESS" = "True" ]; then
        echo "[$(date '+%Y-%m-%d %H:%M:%S')] OK: ${TYPE} ${DOMAIN_NAME} 更新成功 ${OLD_IP} → ${NEW_IP}" >> "$LOG_FILE"
        write_record_status "$TYPE" "$DOMAIN_NAME" updated "$OLD_IP" "$NEW_IP"
        write_record_change "$TYPE" "$DOMAIN_NAME" "$OLD_IP" "$NEW_IP"
        write_record_ip "$TYPE" "$DOMAIN_NAME" "$NEW_IP"
        tg_notify "🌐 <b>DDNS IP 已更新</b>
域名：<code>${DOMAIN_NAME}</code>
类型：${TYPE}
旧IP：<code>${OLD_IP}</code>
新IP：<code>${NEW_IP}</code>
时间：$(date '+%Y-%m-%d %H:%M:%S')"
    else
        echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: ${TYPE} 更新失败 $RESULT" >> "$LOG_FILE"
        write_record_status "$TYPE" "$DOMAIN_NAME" update_failed "$OLD_IP" "$NEW_IP"
        return 1
    fi
}

EXIT_CODE=0

if is_true "$ENABLE_A"; then
    CURRENT_IP4=$(fetch_ip4)
    if [ -z "$CURRENT_IP4" ]; then
        echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: 无法获取公网 IPv4" >> "$LOG_FILE"
        write_record_status A "$DOMAIN4" fetch_failed "" ""
        EXIT_CODE=1
    elif ! valid_ipv4 "$CURRENT_IP4"; then
        echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: 获取到的 IPv4 非法：${CURRENT_IP4}" >> "$LOG_FILE"
        write_record_status A "$DOMAIN4" invalid_ip "" "$CURRENT_IP4"
        EXIT_CODE=1
    else
        update_record A "$DOMAIN4" "$CURRENT_IP4" || EXIT_CODE=1
    fi
fi

if is_true "$ENABLE_AAAA"; then
    CURRENT_IP6=$(fetch_ip6)
    if [ -z "$CURRENT_IP6" ]; then
        echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: 无法获取公网 IPv6" >> "$LOG_FILE"
        write_record_status AAAA "$DOMAIN6" fetch_failed "" ""
        EXIT_CODE=1
    elif ! valid_ipv6 "$CURRENT_IP6"; then
        echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: 获取到的 IPv6 非法：${CURRENT_IP6}" >> "$LOG_FILE"
        write_record_status AAAA "$DOMAIN6" invalid_ip "" "$CURRENT_IP6"
        EXIT_CODE=1
    else
        update_record AAAA "$DOMAIN6" "$CURRENT_IP6" || EXIT_CODE=1
    fi
fi

exit "$EXIT_CODE"
DDNS_INNER
    then
        error "无法生成 DDNS 执行脚本"
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    fi

    local DDNS_DOMAIN4_ESC DDNS_DOMAIN6_ESC DDNS_ZONE_ESC DDNS_LOG_ESC
    DDNS_DOMAIN4_ESC=$(ddns_sed_escape "$DDNS_DOMAIN4")
    DDNS_DOMAIN6_ESC=$(ddns_sed_escape "$DDNS_DOMAIN6")
    DDNS_ZONE_ESC=$(ddns_sed_escape "$DDNS_ZONE_NAME")
    DDNS_LOG_ESC=$(ddns_sed_escape "$DDNS_LOG")
    if ! sed -i \
        -e "s|__DOMAIN4__|${DDNS_DOMAIN4_ESC}|g" \
        -e "s|__DOMAIN6__|${DDNS_DOMAIN6_ESC}|g" \
        -e "s|__ZONE__|${DDNS_ZONE_ESC}|g" \
        -e "s|__ENABLE_A__|${DDNS_ENABLE_A}|g" \
        -e "s|__ENABLE_AAAA__|${DDNS_ENABLE_AAAA}|g" \
        -e "s|__PROXIED__|${DDNS_PROXIED}|g" \
        -e "s|__TTL__|${DDNS_TTL}|g" \
        -e "s|__LOG__|${DDNS_LOG_ESC}|g" "$DDNS_SCRIPT" \
        || ! chmod 700 "$DDNS_SCRIPT" \
        || ! bash -n "$DDNS_SCRIPT"; then
        error "生成的 DDNS 脚本校验失败"
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    fi

    echo ""
    info "立即执行一次测试..."
    if bash "$DDNS_SCRIPT"; then
        tail -1 "$DDNS_LOG" 2>/dev/null | while IFS= read -r l; do echo -e "  ${GREEN}$l${NC}"; done
    else
        error "执行失败，请查看日志"
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    fi
    local CRON_JOB; CRON_JOB="$(ddns_cron_expr "$DDNS_INTERVAL_MIN") ${DDNS_SCRIPT} >> ${DDNS_LOG} 2>&1 ${DDNS_CRON_MARKER}"
    if ! ddns_install_cron_job "$CRON_JOB"; then
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    fi
    ddns_install_tx_commit
    rm -f "$DDNS_HUAWEI_KEY_FILE" || warn "旧华为云凭据文件无法删除，请手动检查 ${DDNS_HUAWEI_KEY_FILE}"
    info "crontab 已设置（每 ${DDNS_INTERVAL_MIN} 分钟自动更新）✓"
    echo ""
    info "DDNS 配置完成 ✓"
    [ "$DDNS_ENABLE_A" = "true" ] && echo -e "  IPv4 : ${BOLD}${DDNS_DOMAIN4}${NC}"
    [ "$DDNS_ENABLE_AAAA" = "true" ] && echo -e "  IPv6 : ${BOLD}${DDNS_DOMAIN6}${NC}"
    echo -e "  日志 : ${DIM}${DDNS_LOG}${NC}"
}

ddns_install_huawei() {
    print_header "华为云 DDNS 配置"
    echo -e "  ${DIM}动态 DNS：通过华为云 DNS API 更新 A / AAAA 记录${NC}"
    echo ""

    for cmd in curl python3; do
        if ! command -v "$cmd" &>/dev/null; then
            info "安装依赖 $cmd..."
            pkg_install "$cmd" &>/dev/null || true
            if ! command -v "$cmd" &>/dev/null; then
                error "依赖 ${cmd} 安装失败，请手动安装后重试"
                return 1
            fi
        fi
    done
    if ! ddns_ensure_cron; then
        error "无法安装或启用 crontab/cron，请先手动安装 cron 后重试"
        return
    fi
    if ! ddns_start_cron_service >/dev/null 2>&1; then
        error "cron 服务无法启动，请修复后重试"
        return 1
    fi

    menu_div
    read -rp "  根域名（如 example.com，需已托管到华为云 DNS）: " DDNS_ZONE_NAME
    [ -z "$DDNS_ZONE_NAME" ] && { warn "已取消"; return; }
    if ! DDNS_ZONE_NAME=$(ddns_domain_normalize "$DDNS_ZONE_NAME"); then
        error "根域名格式无效"
        return 1
    fi

    local DDNS_ENDPOINT="https://dns.myhuaweicloud.com"
    read -rp "  API Endpoint（默认 ${DDNS_ENDPOINT}）: " DDNS_ENDPOINT_IN
    if ! DDNS_ENDPOINT=$(ddns_huawei_endpoint_normalize "${DDNS_ENDPOINT_IN:-$DDNS_ENDPOINT}"); then
        error "Endpoint 必须是华为云官方 HTTPS 地址，例如 dns.cn-north-4.myhuaweicloud.com"
        return 1
    fi

    local DDNS_ENABLE_A="true" DDNS_ENABLE_AAAA="false"
    local DDNS_SUB4="" DDNS_SUB6="" DDNS_DOMAIN4="" DDNS_DOMAIN6=""

    read -rp "  启用 IPv4 A 记录？(Y/n，默认Y): " DDNS_A_CH
    if echo "$DDNS_A_CH" | grep -qiE '^n(o)?$'; then
        DDNS_ENABLE_A="false"
    else
        read -rp "  IPv4 子域名（A，如 home；@ 表示根域）: " DDNS_SUB4
        [ -z "$DDNS_SUB4" ] && { warn "已取消"; return; }
        DDNS_DOMAIN4=$(ddns_build_domain "$DDNS_SUB4" "$DDNS_ZONE_NAME")
    fi

    local V6_DEFAULT="N"
    [ "$DDNS_ENABLE_A" = "false" ] && V6_DEFAULT="Y"
    read -rp "  启用 IPv6 AAAA 记录？($([ "$V6_DEFAULT" = "Y" ] && echo 'Y/n' || echo 'y/N')，默认${V6_DEFAULT}): " DDNS_AAAA_CH
    case "$DDNS_AAAA_CH" in
        "")
            [ "$V6_DEFAULT" = "Y" ] && DDNS_ENABLE_AAAA="true" || DDNS_ENABLE_AAAA="false"
            ;;
        y|Y|yes|YES) DDNS_ENABLE_AAAA="true" ;;
        *) DDNS_ENABLE_AAAA="false" ;;
    esac

    if [ "$DDNS_ENABLE_AAAA" = "true" ]; then
        local DDNS_SUB6_DEFAULT DDNS_SHARE_DOMAIN=""
        if [ "$DDNS_ENABLE_A" = "true" ]; then
            read -rp "  A 与 AAAA 共用同一个域名 ${DDNS_DOMAIN4}？(y/N，默认N): " DDNS_SHARE_DOMAIN
        fi
        if echo "$DDNS_SHARE_DOMAIN" | grep -qiE '^y(es)?$'; then
            DDNS_SUB6="$DDNS_SUB4"
        else
            if [ "$DDNS_ENABLE_A" = "true" ]; then
                DDNS_SUB6_DEFAULT=$(ddns_ipv6_subdomain_default "$DDNS_SUB4")
            else
                DDNS_SUB6_DEFAULT="home"
            fi
            read -rp "  IPv6 子域名（AAAA，默认 ${DDNS_SUB6_DEFAULT}；@ 表示根域）: " DDNS_SUB6
            [ -z "$DDNS_SUB6" ] && DDNS_SUB6="$DDNS_SUB6_DEFAULT"
            if [ "$DDNS_ENABLE_A" = "true" ] && [ "$DDNS_SUB6" = "$DDNS_SUB4" ]; then
                error "已选择独立域名，但 A 与 AAAA 子域名相同；如需共用请在上一项选择 y"
                return 1
            fi
        fi
        DDNS_DOMAIN6=$(ddns_build_domain "$DDNS_SUB6" "$DDNS_ZONE_NAME")
    fi

    if [ "$DDNS_ENABLE_A" != "true" ] && [ "$DDNS_ENABLE_AAAA" != "true" ]; then
        error "至少需要启用 IPv4 A 或 IPv6 AAAA 其中一种记录"
        return
    fi
    if [ "$DDNS_ENABLE_A" = "true" ]; then
        if ! DDNS_DOMAIN4=$(ddns_domain_normalize "$DDNS_DOMAIN4") || ! ddns_domain_in_zone "$DDNS_DOMAIN4" "$DDNS_ZONE_NAME"; then
            error "IPv4 域名格式无效或不属于根域名 ${DDNS_ZONE_NAME}"
            return 1
        fi
    fi
    if [ "$DDNS_ENABLE_AAAA" = "true" ]; then
        if ! DDNS_DOMAIN6=$(ddns_domain_normalize "$DDNS_DOMAIN6") || ! ddns_domain_in_zone "$DDNS_DOMAIN6" "$DDNS_ZONE_NAME"; then
            error "IPv6 域名格式无效或不属于根域名 ${DDNS_ZONE_NAME}"
            return 1
        fi
    fi

    read -rp "  华为云 Access Key ID（AK）: " DDNS_HW_AK
    [ -z "$DDNS_HW_AK" ] && { warn "已取消"; return; }
    read -rp "  华为云 Secret Access Key（SK，输入可见）: " DDNS_HW_SK
    [ -z "$DDNS_HW_SK" ] && { warn "已取消"; return; }

    local DDNS_TTL="300"
    read -rp "  TTL 秒数（默认300）: " DDNS_TTL_IN
    if ! DDNS_TTL=$(ddns_huawei_ttl_normalize "${DDNS_TTL_IN:-300}"); then
        error "华为云 TTL 必须为 300-2147483647 秒"
        return 1
    fi
    local DDNS_INTERVAL_MIN
    DDNS_INTERVAL_MIN=$(ddns_prompt_interval 5)

    echo ""
    menu_div
    [ "$DDNS_ENABLE_A" = "true" ] && echo -e "  IPv4 A    : ${BOLD}${DDNS_DOMAIN4}${NC}" || echo -e "  IPv4 A    : ${DIM}未启用${NC}"
    [ "$DDNS_ENABLE_AAAA" = "true" ] && echo -e "  IPv6 AAAA : ${BOLD}${DDNS_DOMAIN6}${NC}" || echo -e "  IPv6 AAAA : ${DIM}未启用${NC}"
    if [ "$DDNS_ENABLE_A" = "true" ] && [ "$DDNS_ENABLE_AAAA" = "true" ]; then
        [ "$DDNS_DOMAIN4" = "$DDNS_DOMAIN6" ] \
            && echo -e "  记录方式  : ${BOLD}共用域名（同一域名各 1 条 A / AAAA）${NC}" \
            || echo -e "  记录方式  : ${BOLD}独立域名（IPv4 / IPv6 各 1 条）${NC}"
    fi
    echo -e "  Endpoint  : ${BOLD}${DDNS_ENDPOINT}${NC}"
    echo -e "  TTL       : ${BOLD}${DDNS_TTL}${NC}"
    echo -e "  间隔      : ${BOLD}${DDNS_INTERVAL_MIN} 分钟${NC}"
    echo -e "  AK        : ${BOLD}${DDNS_HW_AK:0:8}…${NC}"
    menu_div
    echo ""
    read -rp "  确认安装？(Y/n，默认Y): " CONFIRM
    [ -z "$CONFIRM" ] && CONFIRM="y"
    if ! echo "$CONFIRM" | grep -qiE '^y(es)?$'; then warn "已取消"; return; fi

    if ! ddns_install_tx_begin; then
        error "无法创建 DDNS 配置回滚快照"
        return 1
    fi

    {
        echo "AK=${DDNS_HW_AK}"
        echo "SK=${DDNS_HW_SK}"
    } > "$DDNS_HUAWEI_KEY_FILE" || {
        error "无法保存华为云 AK/SK"
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    }
    if ! chmod 600 "$DDNS_HUAWEI_KEY_FILE"; then
        error "无法保护华为云 AK/SK 文件权限"
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    fi

    if ! touch "$DDNS_LOG" 2>/dev/null; then
        DDNS_LOG="$HOME/ddns.log"
        if ! touch "$DDNS_LOG" 2>/dev/null; then
            error "无法创建 DDNS 日志文件"
            ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
            return 1
        fi
    fi
    chmod 644 "$DDNS_LOG" 2>/dev/null || true
    local DDNS_PRIMARY_DOMAIN="${DDNS_DOMAIN4:-$DDNS_DOMAIN6}"
    {
        echo "PROVIDER=huawei"
        echo "DOMAIN=${DDNS_PRIMARY_DOMAIN}"
        echo "DOMAIN4=${DDNS_DOMAIN4}"
        echo "DOMAIN6=${DDNS_DOMAIN6}"
        echo "ZONE=${DDNS_ZONE_NAME}"
        echo "MODE=$([ "$DDNS_ENABLE_A" = "true" ] && [ "$DDNS_ENABLE_AAAA" = "true" ] && echo dual || { [ "$DDNS_ENABLE_AAAA" = "true" ] && echo ipv6 || echo ipv4; })"
        echo "ENABLE_A=${DDNS_ENABLE_A}"
        echo "ENABLE_AAAA=${DDNS_ENABLE_AAAA}"
        echo "ENDPOINT=${DDNS_ENDPOINT}"
        echo "TTL=${DDNS_TTL}"
        echo "INTERVAL_MIN=${DDNS_INTERVAL_MIN}"
        echo "LOG=${DDNS_LOG}"
    } > "$DDNS_ZONE_FILE" || {
        error "无法保存 DDNS 配置"
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    }

    if ! cat > "$DDNS_SCRIPT" << 'DDNS_HUAWEI_INNER'
#!/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin

DOMAIN4="__DOMAIN4__"
DOMAIN6="__DOMAIN6__"
ZONE="__ZONE__"
ENDPOINT="__ENDPOINT__"
ENABLE_A="__ENABLE_A__"
ENABLE_AAAA="__ENABLE_AAAA__"
TTL="__TTL__"
KEY_FILE="/root/.hw_dns_aksk"
LOG_FILE="__LOG__"
STATE_DIR="${DDNS_STATE_DIR:-/root}"
LOCK_FILE="/run/vps-tools-ddns.lockfile"
LOCK_DIR="/run/vps-tools-ddns.lock"

acquire_lock() {
    if command -v flock >/dev/null 2>&1; then
        exec 9>"$LOCK_FILE" || return 1
        flock -n 9 || return 75
        return 0
    fi
    if mkdir "$LOCK_DIR" 2>/dev/null; then
        printf '%s\n' "$$" > "$LOCK_DIR/pid"
        trap 'rm -rf -- "$LOCK_DIR"' EXIT
        return 0
    fi
    local LOCK_PID=""
    [ -f "$LOCK_DIR/pid" ] && read -r LOCK_PID < "$LOCK_DIR/pid"
    if [ -n "$LOCK_PID" ] && kill -0 "$LOCK_PID" 2>/dev/null; then
        return 75
    fi
    rm -rf -- "$LOCK_DIR" 2>/dev/null || return 1
    mkdir "$LOCK_DIR" 2>/dev/null || return 75
    printf '%s\n' "$$" > "$LOCK_DIR/pid"
    trap 'rm -rf -- "$LOCK_DIR"' EXIT
}

acquire_lock || exit $?

ENDPOINT=${ENDPOINT%/}
ZONE_DOT="${ZONE%.}."
AK=$(grep "^AK=" "$KEY_FILE" 2>/dev/null | head -1 | cut -d= -f2-)
SK=$(grep "^SK=" "$KEY_FILE" 2>/dev/null | head -1 | cut -d= -f2-)
if [ -z "$AK" ] || [ -z "$SK" ]; then
    exit 1
fi

if [ -f "$LOG_FILE" ]; then
    LOG_LINES=$(wc -l < "$LOG_FILE" 2>/dev/null || echo 0)
    if [ "$LOG_LINES" -gt 500 ]; then
        tail -n 500 "$LOG_FILE" > "${LOG_FILE}.tmp" && mv "${LOG_FILE}.tmp" "$LOG_FILE"
    fi
fi

is_true() {
    case "$1" in
        1|true|TRUE|yes|YES|on|ON) return 0 ;;
        *) return 1 ;;
    esac
}

fqdn_dot() {
    local NAME="$1"
    case "$NAME" in
        *.) echo "$NAME" ;;
        *) echo "${NAME}." ;;
    esac
}

log_line() {
    printf '[%s] %s: %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$1" "$2" >> "$LOG_FILE"
}

record_status_file() {
    case "$1" in
        A|AAAA) echo "${STATE_DIR}/.cf_last_status_$1" ;;
        *) echo "${STATE_DIR}/.cf_last_status" ;;
    esac
}

record_change_file() {
    case "$1" in
        A|AAAA) echo "${STATE_DIR}/.cf_last_change_$1" ;;
        *) echo "${STATE_DIR}/.cf_last_change" ;;
    esac
}

record_ip_file() {
    case "$1" in
        A|AAAA) echo "${STATE_DIR}/.cf_last_ip_$1" ;;
        *) echo "${STATE_DIR}/.cf_last_ip" ;;
    esac
}

write_record_status() {
    local TYPE="$1" DOMAIN_NAME="$2" STATE="$3" OLD_IP="${4:-}" NEW_IP="${5:-}" FILE
    FILE=$(record_status_file "$TYPE")
    printf '%s|%s|%s|%s|%s|%s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$TYPE" "$DOMAIN_NAME" "$STATE" "$OLD_IP" "$NEW_IP" > "$FILE" 2>/dev/null || return 0
    chmod 600 "$FILE" 2>/dev/null || true
}

previous_record_ip() {
    local TYPE="$1" DOMAIN_NAME="$2" FILE _TS RECORD_TYPE RECORD_DOMAIN STATE OLD_IP NEW_IP IP
    FILE=$(record_ip_file "$TYPE")
    if [ -f "$FILE" ]; then
        IFS='|' read -r _TS RECORD_TYPE RECORD_DOMAIN IP < "$FILE"
        if [ "$RECORD_TYPE" = "$TYPE" ] && [ "$RECORD_DOMAIN" = "$DOMAIN_NAME" ] && [ -n "$IP" ]; then
            printf '%s\n' "$IP"
            return 0
        fi
    fi

    # 升级兼容：首次运行时从旧状态文件迁移最后一次成功 IP。
    FILE=$(record_status_file "$TYPE")
    [ -f "$FILE" ] || return 0
    IFS='|' read -r _TS RECORD_TYPE RECORD_DOMAIN STATE OLD_IP NEW_IP < "$FILE"
    [ "$RECORD_TYPE" = "$TYPE" ] && [ "$RECORD_DOMAIN" = "$DOMAIN_NAME" ] || return 0
    case "$STATE" in
        unchanged|updated) printf '%s\n' "${NEW_IP:-$OLD_IP}" ;;
    esac
}

write_record_ip() {
    local TYPE="$1" DOMAIN_NAME="$2" IP="$3" FILE
    [ -n "$IP" ] || return 0
    FILE=$(record_ip_file "$TYPE")
    printf '%s|%s|%s|%s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$TYPE" "$DOMAIN_NAME" "$IP" > "$FILE" 2>/dev/null || return 0
    chmod 600 "$FILE" 2>/dev/null || true
}

write_record_change() {
    local TYPE="$1" DOMAIN_NAME="$2" OLD_IP="$3" NEW_IP="$4" KIND="${5:-updated}" LINE FILE
    LINE="$(date '+%Y-%m-%d %H:%M:%S')|${TYPE}|${OLD_IP}|${NEW_IP}|${DOMAIN_NAME}|${KIND}"
    FILE=$(record_change_file "$TYPE")
    printf '%s\n' "$LINE" > "$FILE" 2>/dev/null || true
    chmod 600 "$FILE" 2>/dev/null || true
    printf '%s\n' "$LINE" > "${STATE_DIR}/.cf_last_change" 2>/dev/null || true
    chmod 600 "${STATE_DIR}/.cf_last_change" 2>/dev/null || true
}

tg_notify() {
    local MSG="$1"
    local TG_FILE="/root/.cf_tg"
    [ -f "$TG_FILE" ] || return 0
    local B_TOKEN C_ID RESP DESCRIPTION
    B_TOKEN=$(grep "^BOT_TOKEN=" "$TG_FILE" | cut -d= -f2-)
    C_ID=$(grep "^CHAT_ID=" "$TG_FILE" | cut -d= -f2-)
    [ -z "$B_TOKEN" ] || [ -z "$C_ID" ] && return 0
    if ! RESP=$(curl -fsS --max-time 15 \
        "https://api.telegram.org/bot${B_TOKEN}/sendMessage" \
        --data-urlencode "chat_id=${C_ID}" \
        --data-urlencode "text=${MSG}" \
        --data-urlencode "parse_mode=HTML" 2>/dev/null); then
        log_line WARN "Telegram 通知发送失败：网络或 HTTP 错误"
        return 0
    fi
    if ! printf '%s' "$RESP" | python3 -c 'import json,sys; raise SystemExit(0 if json.load(sys.stdin).get("ok") is True else 1)' 2>/dev/null; then
        DESCRIPTION=$(printf '%s' "$RESP" | python3 -c 'import json,sys; print(str(json.load(sys.stdin).get("description") or "API 返回异常").replace("\n", " "))' 2>/dev/null || echo "API 返回异常")
        log_line WARN "Telegram 通知发送失败：${DESCRIPTION}"
    fi
}

fetch_ip4() {
    (
        curl -4 -fsS --max-time 5 https://api.ipify.org ||
        curl -4 -fsS --max-time 5 https://ifconfig.me/ip ||
        curl -4 -fsS --max-time 5 https://ip.sb
    ) 2>/dev/null | tr -d ' \r\n'
}

fetch_ip6() {
    local IP
    IP=$( (
        curl -6 -fsS --max-time 5 https://api64.ipify.org ||
        curl -6 -fsS --max-time 5 https://ipv6.icanhazip.com ||
        curl -6 -fsS --max-time 5 https://ip.sb
    ) 2>/dev/null | tr -d ' \r\n')
    [ -n "$IP" ] && { echo "$IP"; return 0; }
    fetch_ip6_local
}

fetch_ip6_local() {
    command -v ip >/dev/null 2>&1 || return 0
    command -v python3 >/dev/null 2>&1 || return 0
    local ROUTE
    ROUTE=$(ip -6 route get 2606:4700:4700::1111 2>/dev/null) || return 0
    printf '%s\n' "$ROUTE" | python3 -c '
import ipaddress
import sys
for line in sys.stdin:
    parts = line.split()
    if "src" not in parts:
        continue
    try:
        addr = parts[parts.index("src") + 1].split("/")[0]
        ip = ipaddress.ip_address(addr)
    except Exception:
        continue
    if ip.version == 6 and ip.is_global:
        print(ip.compressed)
        break
'
}

valid_ipv4() {
    echo "$1" | grep -qE '^([0-9]{1,3}\.){3}[0-9]{1,3}$' && \
    echo "$1" | awk -F. '{for(i=1;i<=4;i++) if($i<0||$i>255) exit 1}'
}

valid_ipv6() {
    python3 -c "import ipaddress,sys; ip=ipaddress.ip_address(sys.argv[1]); sys.exit(0 if ip.version == 6 and ip.is_global else 1)" "$1" 2>/dev/null
}

huawei_api() {
    local METHOD="$1" API_PATH="$2" QUERY="${3:-}" BODY="${4:-}"
    HUAWEI_AK="$AK" HUAWEI_SK="$SK" HUAWEI_ENDPOINT="$ENDPOINT" \
    HUAWEI_METHOD="$METHOD" HUAWEI_PATH="$API_PATH" HUAWEI_QUERY="$QUERY" HUAWEI_BODY="$BODY" \
    python3 <<'PY'
import datetime
import hashlib
import hmac
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

ak = os.environ["HUAWEI_AK"]
sk = os.environ["HUAWEI_SK"].encode()
endpoint = os.environ["HUAWEI_ENDPOINT"].rstrip("/")
if "://" not in endpoint:
    endpoint = "https://" + endpoint
method = os.environ["HUAWEI_METHOD"].upper()
api_path = os.environ["HUAWEI_PATH"]
query = os.environ.get("HUAWEI_QUERY", "")
body = os.environ.get("HUAWEI_BODY", "")

parts = urllib.parse.urlsplit(endpoint)
base_path = parts.path.rstrip("/")
path = base_path + (api_path if api_path.startswith("/") else "/" + api_path)
host = parts.netloc
sdk_date = datetime.datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")

params = urllib.parse.parse_qsl(query, keep_blank_values=True)
canonical_query = urllib.parse.urlencode(sorted(params), doseq=True, safe="-_.~")
canonical_uri = urllib.parse.quote(path, safe="/-_.~")
if not canonical_uri.endswith("/"):
    canonical_uri += "/"
payload_hash = hashlib.sha256(body.encode()).hexdigest()
signed_headers = "content-type;host;x-sdk-date"
canonical_headers = (
    "content-type:application/json\n"
    f"host:{host}\n"
    f"x-sdk-date:{sdk_date}\n"
)
canonical_request = "\n".join([
    method,
    canonical_uri,
    canonical_query,
    canonical_headers,
    signed_headers,
    payload_hash,
])
algorithm = "SDK-HMAC-SHA256"
hashed_request = hashlib.sha256(canonical_request.encode()).hexdigest()
string_to_sign = "\n".join([algorithm, sdk_date, hashed_request])
signature = hmac.new(sk, string_to_sign.encode(), hashlib.sha256).hexdigest()
authorization = f"{algorithm} Access={ak}, SignedHeaders={signed_headers}, Signature={signature}"

url = f"{parts.scheme}://{host}{path}"
if canonical_query:
    url += "?" + canonical_query
data = body.encode() if method not in ("GET", "HEAD") else None
headers = {
    "Content-Type": "application/json",
    "Host": host,
    "X-Sdk-Date": sdk_date,
    "Authorization": authorization,
}
req = urllib.request.Request(url, data=data, headers=headers, method=method)
try:
    with urllib.request.urlopen(req, timeout=15) as resp:
        sys.stdout.write(resp.read().decode())
except urllib.error.HTTPError as exc:
    sys.stdout.write(exc.read().decode())
    sys.exit(1)
except Exception:
    sys.exit(1)
PY
}

json_zone_id() {
    JSON_INPUT=$(cat) python3 - "$ZONE_DOT" <<'PY'
import json
import os
import sys
target = sys.argv[1].rstrip(".") + "."
try:
    data = json.loads(os.environ.get("JSON_INPUT", "{}"))
except Exception:
    sys.exit(0)
for zone in data.get("zones", []):
    name = (zone.get("name") or "").rstrip(".") + "."
    if name == target and zone.get("zone_type", "public") == "public":
        print(zone.get("id", ""))
        break
PY
}

json_record_info() {
    local TYPE="$1" DOMAIN_NAME="$2"
    JSON_INPUT=$(cat) python3 - "$TYPE" "$DOMAIN_NAME" <<'PY'
import json
import os
import sys
rtype = sys.argv[1]
target = sys.argv[2].rstrip(".") + "."
try:
    data = json.loads(os.environ.get("JSON_INPUT", "{}"))
except Exception:
    sys.exit(0)
for record in data.get("recordsets", []):
    name = (record.get("name") or "").rstrip(".") + "."
    if name == target and record.get("type") == rtype:
        records = record.get("records") or []
        print(f"{record.get('id', '')}|{records[0] if records else ''}")
        break
PY
}

json_top_record() {
    JSON_INPUT=$(cat) python3 <<'PY'
import json
import os
try:
    data = json.loads(os.environ.get("JSON_INPUT", "{}"))
except Exception:
    raise SystemExit(0)
records = data.get("records") or []
print(records[0] if records else "")
PY
}

json_top_id() {
    JSON_INPUT=$(cat) python3 <<'PY'
import json
import os
try:
    data = json.loads(os.environ.get("JSON_INPUT", "{}"))
except Exception:
    raise SystemExit(0)
print(data.get("id", ""))
PY
}

record_body() {
    local TYPE="$1" DOMAIN_NAME="$2" NEW_IP="$3"
    python3 - "$TYPE" "$DOMAIN_NAME" "$TTL" "$NEW_IP" <<'PY'
import json
import sys
rtype, name, ttl, value = sys.argv[1:]
body = {
    "name": name.rstrip(".") + ".",
    "type": rtype,
    "ttl": int(ttl),
    "records": [value],
    "description": "VPS TOOLS DDNS",
}
print(json.dumps(body, separators=(",", ":")))
PY
}

if { is_true "$ENABLE_A" && [ -z "$DOMAIN4" ]; } || { is_true "$ENABLE_AAAA" && [ -z "$DOMAIN6" ]; }; then
    log_line ERROR "启用的 A / AAAA 记录缺少域名，请重新生成 DDNS 配置"
    exit 1
fi

if ! ZONE_RESP=$(huawei_api GET "/v2/zones" "type=public&limit=500" ""); then
    log_line ERROR "查询华为云 Zone 失败，请检查网络、AK/SK 和 Endpoint"
    exit 1
fi
ZONE_ID=$(printf '%s' "$ZONE_RESP" | json_zone_id)
[ -z "$ZONE_ID" ] && {
    log_line ERROR "获取华为云 Zone ID 失败，请检查 AK/SK、Endpoint 和域名 ${ZONE}"
    exit 1
}

update_record() {
    local TYPE="$1" DOMAIN_NAME="$2" NEW_IP="$3"
    [ -z "$NEW_IP" ] && return 0
    [ -z "$DOMAIN_NAME" ] && return 0
    local DOMAIN_DOT RECORD_RESP RECORD_INFO RECORD_ID OLD_IP BODY RESULT UPDATED_IP CREATED_ID
    DOMAIN_DOT=$(fqdn_dot "$DOMAIN_NAME")
    if ! RECORD_RESP=$(huawei_api GET "/v2/zones/${ZONE_ID}/recordsets" "search_mode=equal&type=${TYPE}&name=${DOMAIN_DOT}&limit=100" ""); then
        log_line ERROR "${TYPE} ${DOMAIN_NAME} 查询记录失败"
        write_record_status "$TYPE" "$DOMAIN_NAME" query_failed "" "$NEW_IP"
        return 1
    fi
    RECORD_INFO=$(printf '%s' "$RECORD_RESP" | json_record_info "$TYPE" "$DOMAIN_DOT")
    RECORD_ID=${RECORD_INFO%%|*}
    OLD_IP=${RECORD_INFO#*|}
    if [ -z "$RECORD_ID" ]; then
        BODY=$(record_body "$TYPE" "$DOMAIN_DOT" "$NEW_IP")
        if ! RESULT=$(huawei_api POST "/v2/zones/${ZONE_ID}/recordsets" "" "$BODY"); then
            log_line ERROR "${TYPE} ${DOMAIN_NAME} 创建失败 ${RESULT}"
            write_record_status "$TYPE" "$DOMAIN_NAME" update_failed "" "$NEW_IP"
            return 1
        fi
        CREATED_ID=$(printf '%s' "$RESULT" | json_top_id)
        if [ -n "$CREATED_ID" ]; then
            log_line OK "${TYPE} ${DOMAIN_NAME} 创建成功 ${NEW_IP}"
            write_record_status "$TYPE" "$DOMAIN_NAME" updated "" "$NEW_IP"
            write_record_change "$TYPE" "$DOMAIN_NAME" "" "$NEW_IP"
            write_record_ip "$TYPE" "$DOMAIN_NAME" "$NEW_IP"
            return 0
        fi
        log_line ERROR "${TYPE} ${DOMAIN_NAME} 创建失败 ${RESULT}"
        write_record_status "$TYPE" "$DOMAIN_NAME" update_failed "" "$NEW_IP"
        return 1
    fi
    if [ -z "$OLD_IP" ]; then
        log_line WARN "${TYPE} ${DOMAIN_NAME} 无法获取当前记录值，跳过更新"
        write_record_status "$TYPE" "$DOMAIN_NAME" query_failed "" "$NEW_IP"
        return 0
    fi
    if [ "$NEW_IP" = "$OLD_IP" ]; then
        local PREV_IP
        PREV_IP=$(previous_record_ip "$TYPE" "$DOMAIN_NAME")
        write_record_ip "$TYPE" "$DOMAIN_NAME" "$NEW_IP"
        if [ -n "$PREV_IP" ] && [ "$PREV_IP" != "$NEW_IP" ]; then
            log_line OK "${TYPE} ${DOMAIN_NAME} IP变化 ${PREV_IP} → ${NEW_IP}（DNS已同步）"
            write_record_change "$TYPE" "$DOMAIN_NAME" "$PREV_IP" "$NEW_IP" synced
            tg_notify "🌐 <b>DDNS IP 已变化</b>
服务商：华为云 DNS
域名：<code>${DOMAIN_NAME}</code>
类型：${TYPE}
旧IP：<code>${PREV_IP}</code>
新IP：<code>${NEW_IP}</code>
状态：DNS 已同步
时间：$(date '+%Y-%m-%d %H:%M:%S')"
        else
            log_line OK "${TYPE} ${DOMAIN_NAME} 未变化 ${NEW_IP}"
        fi
        write_record_status "$TYPE" "$DOMAIN_NAME" unchanged "$OLD_IP" "$NEW_IP"
        return 0
    fi
    BODY=$(record_body "$TYPE" "$DOMAIN_DOT" "$NEW_IP")
    if ! RESULT=$(huawei_api PUT "/v2.1/zones/${ZONE_ID}/recordsets/${RECORD_ID}" "" "$BODY"); then
        log_line ERROR "${TYPE} ${DOMAIN_NAME} 更新失败 ${RESULT}"
        write_record_status "$TYPE" "$DOMAIN_NAME" update_failed "$OLD_IP" "$NEW_IP"
        return 1
    fi
    UPDATED_IP=$(printf '%s' "$RESULT" | json_top_record)
    if [ "$UPDATED_IP" = "$NEW_IP" ]; then
        log_line OK "${TYPE} ${DOMAIN_NAME} 更新成功 ${OLD_IP} → ${NEW_IP}"
        write_record_status "$TYPE" "$DOMAIN_NAME" updated "$OLD_IP" "$NEW_IP"
        write_record_change "$TYPE" "$DOMAIN_NAME" "$OLD_IP" "$NEW_IP"
        write_record_ip "$TYPE" "$DOMAIN_NAME" "$NEW_IP"
        tg_notify "🌐 <b>DDNS IP 已更新</b>
服务商：华为云 DNS
域名：<code>${DOMAIN_NAME}</code>
类型：${TYPE}
旧IP：<code>${OLD_IP}</code>
新IP：<code>${NEW_IP}</code>
时间：$(date '+%Y-%m-%d %H:%M:%S')"
        return 0
    fi
    log_line ERROR "${TYPE} ${DOMAIN_NAME} 更新失败 ${RESULT}"
    write_record_status "$TYPE" "$DOMAIN_NAME" update_failed "$OLD_IP" "$NEW_IP"
    return 1
}

EXIT_CODE=0

if is_true "$ENABLE_A"; then
    CURRENT_IP4=$(fetch_ip4)
    if [ -z "$CURRENT_IP4" ]; then
        log_line ERROR "A ${DOMAIN4} 无法获取公网 IPv4"
        write_record_status A "$DOMAIN4" fetch_failed "" ""
        EXIT_CODE=1
    elif ! valid_ipv4 "$CURRENT_IP4"; then
        log_line ERROR "A ${DOMAIN4} 获取到的 IPv4 非法：${CURRENT_IP4}"
        write_record_status A "$DOMAIN4" invalid_ip "" "$CURRENT_IP4"
        EXIT_CODE=1
    else
        update_record A "$DOMAIN4" "$CURRENT_IP4" || EXIT_CODE=1
    fi
fi

if is_true "$ENABLE_AAAA"; then
    CURRENT_IP6=$(fetch_ip6)
    if [ -z "$CURRENT_IP6" ]; then
        log_line ERROR "AAAA ${DOMAIN6} 无法获取公网 IPv6"
        write_record_status AAAA "$DOMAIN6" fetch_failed "" ""
        EXIT_CODE=1
    elif ! valid_ipv6 "$CURRENT_IP6"; then
        log_line ERROR "AAAA ${DOMAIN6} 获取到的 IPv6 非法：${CURRENT_IP6}"
        write_record_status AAAA "$DOMAIN6" invalid_ip "" "$CURRENT_IP6"
        EXIT_CODE=1
    else
        update_record AAAA "$DOMAIN6" "$CURRENT_IP6" || EXIT_CODE=1
    fi
fi

exit "$EXIT_CODE"
DDNS_HUAWEI_INNER
    then
        error "无法生成 DDNS 执行脚本"
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    fi

    local DDNS_DOMAIN4_ESC DDNS_DOMAIN6_ESC DDNS_ZONE_ESC DDNS_ENDPOINT_ESC DDNS_LOG_ESC
    DDNS_DOMAIN4_ESC=$(ddns_sed_escape "$DDNS_DOMAIN4")
    DDNS_DOMAIN6_ESC=$(ddns_sed_escape "$DDNS_DOMAIN6")
    DDNS_ZONE_ESC=$(ddns_sed_escape "$DDNS_ZONE_NAME")
    DDNS_ENDPOINT_ESC=$(ddns_sed_escape "$DDNS_ENDPOINT")
    DDNS_LOG_ESC=$(ddns_sed_escape "$DDNS_LOG")
    if ! sed -i \
        -e "s|__DOMAIN4__|${DDNS_DOMAIN4_ESC}|g" \
        -e "s|__DOMAIN6__|${DDNS_DOMAIN6_ESC}|g" \
        -e "s|__ZONE__|${DDNS_ZONE_ESC}|g" \
        -e "s|__ENDPOINT__|${DDNS_ENDPOINT_ESC}|g" \
        -e "s|__ENABLE_A__|${DDNS_ENABLE_A}|g" \
        -e "s|__ENABLE_AAAA__|${DDNS_ENABLE_AAAA}|g" \
        -e "s|__TTL__|${DDNS_TTL}|g" \
        -e "s|__LOG__|${DDNS_LOG_ESC}|g" "$DDNS_SCRIPT" \
        || ! chmod 700 "$DDNS_SCRIPT" \
        || ! bash -n "$DDNS_SCRIPT"; then
        error "生成的 DDNS 脚本校验失败"
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    fi

    echo ""
    info "立即执行一次测试..."
    if bash "$DDNS_SCRIPT"; then
        tail -1 "$DDNS_LOG" 2>/dev/null | while IFS= read -r l; do echo -e "  ${GREEN}$l${NC}"; done
    else
        error "执行失败，请查看日志"
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    fi
    local CRON_JOB; CRON_JOB="$(ddns_cron_expr "$DDNS_INTERVAL_MIN") ${DDNS_SCRIPT} >> ${DDNS_LOG} 2>&1 ${DDNS_CRON_MARKER}"
    if ! ddns_install_cron_job "$CRON_JOB"; then
        ddns_install_tx_restore || error "恢复原 DDNS 配置失败，请立即检查"
        return 1
    fi
    ddns_install_tx_commit
    rm -f "$DDNS_TOKEN_FILE" || warn "旧 Cloudflare Token 文件无法删除，请手动检查 ${DDNS_TOKEN_FILE}"
    info "crontab 已设置（每 ${DDNS_INTERVAL_MIN} 分钟自动更新）✓"
    echo ""
    info "华为云 DDNS 配置完成 ✓"
    [ "$DDNS_ENABLE_A" = "true" ] && echo -e "  IPv4 : ${BOLD}${DDNS_DOMAIN4}${NC}"
    [ "$DDNS_ENABLE_AAAA" = "true" ] && echo -e "  IPv6 : ${BOLD}${DDNS_DOMAIN6}${NC}"
    echo -e "  日志 : ${DIM}${DDNS_LOG}${NC}"
}

ddns_install() {
    print_header "DDNS 服务商"
    echo -e "  ${DIM}选择要使用的 DNS 服务商。已有 Cloudflare 配置不会自动迁移。${NC}"
    echo ""
    menu_div
    menu_item "1" "Cloudflare"
    menu_item "2" "华为云 DNS"
    menu_item "0" "返回上级" "$RED"
    menu_div
    echo ""
    read -rp "$(ui_prompt '选择服务商 [1-2]: ')" PROVIDER_CH
    case "$PROVIDER_CH" in
        1|"") ddns_install_cloudflare ;;
        2) ddns_install_huawei ;;
        0) return ;;
        *) warn "无效选项" ;;
    esac
}

# ── 暂停/恢复 DDNS ────────────────────────────────────────
ddns_pause() {
    [ ! -f "$DDNS_SCRIPT" ] && { error "DDNS 未安装"; return; }
    if ! ddns_remove_cron_job; then
        error "暂停失败，原定时任务未可靠移除"
        return 1
    fi
    info "DDNS 自动更新已暂停 ✓"
}

ddns_resume() {
    [ ! -f "$DDNS_SCRIPT" ] && { error "DDNS 未安装"; return; }
    if ! command -v crontab &>/dev/null; then
        info "检测到 cron 未安装，正在自动安装..."
        if ! ddns_ensure_cron; then
            error "cron 安装失败，请手动执行：apt-get install -y cron"
            return
        fi
    fi
    local LOG INTERVAL_MIN CRON_JOB
    LOG=$(ddns_log_path)
    INTERVAL_MIN=$(ddns_interval_min)
    CRON_JOB="$(ddns_cron_expr "$INTERVAL_MIN") ${DDNS_SCRIPT} >> ${LOG} 2>&1 ${DDNS_CRON_MARKER}"
    ddns_install_cron_job "$CRON_JOB" || return 1
    info "DDNS 自动更新已恢复（每 ${INTERVAL_MIN} 分钟）✓"
}

# ── 卸载 DDNS ─────────────────────────────────────────────
# ── Telegram 通知配置 ─────────────────────────────────────
ddns_tg_config() {
    print_header "Telegram 通知配置"
    echo -e "  ${DIM}IP 变化时自动发送 Telegram 通知${NC}"
    echo ""

    if [ -f "$DDNS_TG_FILE" ]; then
        local CUR_BOT CUR_CHAT
        CUR_BOT=$(grep "^BOT_TOKEN=" "$DDNS_TG_FILE" | cut -d= -f2-)
        CUR_CHAT=$(grep "^CHAT_ID=" "$DDNS_TG_FILE" | cut -d= -f2-)
        echo -e "  当前状态：${GREEN}${BOLD}已配置${NC}"
        echo -e "  Bot Token：${DIM}${CUR_BOT:0:10}…${NC}"
        echo -e "  Chat ID  ：${BOLD}${CUR_CHAT}${NC}"
    else
        echo -e "  当前状态：${YELLOW}未配置${NC}"
    fi

    echo ""
    menu_div
    echo -e "  ${DIM}如何获取：${NC}"
    echo -e "  ${DIM}① Telegram 搜索 @BotFather → /newbot 创建机器人${NC}"
    echo -e "  ${DIM}② 获取 Bot Token（格式：123456:ABC-xxx）${NC}"
    echo -e "  ${DIM}③ 与机器人发一条消息，再访问：${NC}"
    echo -e "  ${DIM}   https://api.telegram.org/bot<TOKEN>/getUpdates${NC}"
    echo -e "  ${DIM}④ 从返回的 chat.id 字段获取 Chat ID${NC}"
    menu_div
    echo ""
    menu_pair "1" "配置 Telegram 通知" "2" "发送测试消息"
    [ -f "$DDNS_TG_FILE" ] && menu_item "3" "关闭 Telegram 通知" "$YELLOW"
    menu_item "0" "返回上级" "$RED"
    echo ""
    read -rp "$(ui_prompt '选择操作: ')" CH

    case "$CH" in
        1)
            echo ""
            read -rp "  Bot Token（输入可见）: " TG_BOT
            [ -z "$TG_BOT" ] && { warn "已取消"; return; }
            read -rp "  Chat ID: " TG_CHAT
            [ -z "$TG_CHAT" ] && { warn "已取消"; return; }
            {
                echo "BOT_TOKEN=${TG_BOT}"
                echo "CHAT_ID=${TG_CHAT}"
            } > "$DDNS_TG_FILE"
            chmod 600 "$DDNS_TG_FILE"
            info "Telegram 通知已配置 ✓"
            ;;
        2)
            if [ ! -f "$DDNS_TG_FILE" ]; then
                error "请先配置 Telegram 通知"; return
            fi
            local BOT CHAT
            BOT=$(grep "^BOT_TOKEN=" "$DDNS_TG_FILE" | cut -d= -f2-)
            CHAT=$(grep "^CHAT_ID=" "$DDNS_TG_FILE" | cut -d= -f2-)
            info "发送测试消息..."
            local RESP
            local TG_DOMAIN_TEXT
            TG_DOMAIN_TEXT="服务商：$(ddns_provider_label)
模式：$(ddns_mode_label)"
            if ddns_cfg_enable_a; then
                TG_DOMAIN_TEXT="${TG_DOMAIN_TEXT}
IPv4：$(ddns_cfg_domain4)"
            fi
            if ddns_cfg_enable_aaaa; then
                TG_DOMAIN_TEXT="${TG_DOMAIN_TEXT}
IPv6：$(ddns_cfg_domain6)"
            fi
            if ! RESP=$(curl -fsS --max-time 10 \
                "https://api.telegram.org/bot${BOT}/sendMessage" \
                --data-urlencode "chat_id=${CHAT}" \
                --data-urlencode "text=🔔 DDNS 通知测试
${TG_DOMAIN_TEXT}
时间：$(date '+%Y-%m-%d %H:%M:%S')
✅ 通知配置成功！" \
                --data-urlencode "parse_mode=HTML" 2>/dev/null); then
                error "发送失败：网络或 HTTP 错误"
                return 1
            fi
            if echo "$RESP" | python3 -c 'import json,sys; raise SystemExit(0 if json.load(sys.stdin).get("ok") is True else 1)' 2>/dev/null; then
                info "发送成功 ✓"
            else
                local TG_DESC
                TG_DESC=$(echo "$RESP" | python3 -c 'import json,sys; print(str(json.load(sys.stdin).get("description") or "API 返回异常").replace("\n", " "))' 2>/dev/null || echo "API 返回异常")
                error "发送失败：${TG_DESC}"
                return 1
            fi
            ;;
        3)
            rm -f "$DDNS_TG_FILE" && info "Telegram 通知已关闭 ✓"
            ;;
        0) return ;;
        *) warn "无效选项" ;;
    esac
}

ddns_uninstall() {
    print_header "卸载 DDNS"
    warn "将移除 crontab 定时任务、DDNS 脚本和 API 凭据文件"
    echo ""
    read -rp "  确认卸载？(Y/n，默认Y): " CONFIRM
    [ -z "$CONFIRM" ] && CONFIRM="y"
    if ! echo "$CONFIRM" | grep -qiE '^y(es)?$'; then warn "已取消"; return; fi
    if ! ddns_remove_cron_job; then
        error "卸载已中止：定时任务移除失败，脚本和凭据均未删除"
        return 1
    fi
    info "crontab 定时任务已移除 ✓"
    rm -f "$DDNS_SCRIPT" && info "DDNS 脚本已删除 ✓"
    rm -f "$DDNS_TOKEN_FILE" && info "Token 文件已删除 ✓"
    rm -f "$DDNS_HUAWEI_KEY_FILE" && info "华为云 AK/SK 文件已删除 ✓"
    rm -f "$DDNS_ZONE_FILE"
    rm -f "${DDNS_STATE_DIR:-/root}/.cf_last_change" "${DDNS_STATE_DIR:-/root}/.cf_last_change_A" "${DDNS_STATE_DIR:-/root}/.cf_last_change_AAAA"
    rm -f "${DDNS_STATE_DIR:-/root}/.cf_last_status_A" "${DDNS_STATE_DIR:-/root}/.cf_last_status_AAAA"
    rm -f "${DDNS_STATE_DIR:-/root}/.cf_last_ip" "${DDNS_STATE_DIR:-/root}/.cf_last_ip_A" "${DDNS_STATE_DIR:-/root}/.cf_last_ip_AAAA"
    warn "日志文件保留：${DDNS_LOG}"
}

# ── 查看日志 ──────────────────────────────────────────────
ddns_view_logs() {
    while true; do
        print_header "DDNS 日志"
        local LOG; LOG=$(ddns_log_path)
        if [ ! -f "$LOG" ]; then warn "日志文件不存在"; return; fi
        echo -e "  ${DIM}${LOG}${NC}"
        menu_div
        tail -20 "$LOG" | while IFS= read -r line; do
            if echo "$line" | grep -q "ERROR"; then
                echo -e "  ${RED}$line${NC}"
            elif echo "$line" | grep -q "OK:.*更新成功"; then
                echo -e "  ${GREEN}$line${NC}"
            else
                echo -e "  ${DIM}$line${NC}"
            fi
        done
        echo ""
        menu_div
        menu_item "1" "实时跟踪  ${DIM}Ctrl+C 返回${NC}"
        menu_item "2" "查看完整日志"
        menu_item "0" "返回上级" "$RED"
        echo ""
        read -rp "$(ui_prompt '选择查看方式: ')" CH
        case "$CH" in
            1)
                # 设置 trap 后再 tail -f；trap 仅在 tail 进程内生效
                trap "echo ''; info '已退出实时跟踪'" INT
                tail -f "$LOG"
                trap - INT
                ;;
            2)
                LANG=C.UTF-8 LESSCHARSET=utf-8 less -R "$LOG"
                ;;
            0|"")
                return
                ;;
            *)
                warn "无效选项"; sleep 1
                ;;
        esac
    done
}

ddns_runtime_cfg_get() {
    local key="$1"
    [ -f "$DDNS_SCRIPT" ] || return 1
    sed -n "s/^${key}=\"\(.*\)\"$/\1/p" "$DDNS_SCRIPT" 2>/dev/null | head -1
}

ddns_runtime_config_matches() {
    local expected_a="false" expected_aaaa="false"
    local runtime_a runtime_aaaa expected_domain runtime_domain
    ddns_cfg_enable_a && expected_a="true"
    ddns_cfg_enable_aaaa && expected_aaaa="true"
    runtime_a=$(ddns_runtime_cfg_get ENABLE_A 2>/dev/null || true)
    runtime_aaaa=$(ddns_runtime_cfg_get ENABLE_AAAA 2>/dev/null || true)
    ddns_truthy "$runtime_a" && runtime_a="true" || runtime_a="false"
    ddns_truthy "$runtime_aaaa" && runtime_aaaa="true" || runtime_aaaa="false"
    [ "$runtime_a" = "$expected_a" ] && [ "$runtime_aaaa" = "$expected_aaaa" ] || return 1
    if [ "$expected_a" = "true" ]; then
        expected_domain=$(ddns_cfg_domain4)
        runtime_domain=$(ddns_runtime_cfg_get DOMAIN4 2>/dev/null || true)
        [ -n "$expected_domain" ] && [ "$runtime_domain" = "$expected_domain" ] || return 1
    fi
    if [ "$expected_aaaa" = "true" ]; then
        expected_domain=$(ddns_cfg_domain6)
        runtime_domain=$(ddns_runtime_cfg_get DOMAIN6 2>/dev/null || true)
        [ -n "$expected_domain" ] && [ "$runtime_domain" = "$expected_domain" ] || return 1
    fi
}

ddns_print_run_result() {
    local marker="$1" label="$2" type="$3" domain="$4"
    local state_file line
    state_file=$(ddns_type_status_file "$type")
    if [ ! -f "$state_file" ] || [ ! "$state_file" -nt "$marker" ]; then
        echo -e "  ${YELLOW}本次 ${label}: 未执行或状态写入失败${NC}"
        return 1
    fi
    line=$(ddns_line_from_state_file "$type" "$domain" 2>/dev/null || true)
    if [ -z "$line" ]; then
        echo -e "  ${YELLOW}本次 ${label}: 状态与当前域名不匹配${NC}"
        return 1
    fi
    case "$line" in
        *" ERROR: "*) echo -e "  ${RED}本次 ${label}: ${line}${NC}" ;;
        *" WARN: "*)  echo -e "  ${YELLOW}本次 ${label}: ${line}${NC}" ;;
        *)             echo -e "  ${GREEN}本次 ${label}: ${line}${NC}" ;;
    esac
}

ddns_print_run_results() {
    local marker="$1" failed=0 domain
    if ddns_cfg_enable_a; then
        domain=$(ddns_cfg_domain4)
        ddns_print_run_result "$marker" "IPv4" A "$domain" || failed=1
    fi
    if ddns_cfg_enable_aaaa; then
        domain=$(ddns_cfg_domain6)
        ddns_print_run_result "$marker" "IPv6" AAAA "$domain" || failed=1
    fi
    return "$failed"
}

# ── 手动立即更新 ──────────────────────────────────────────
ddns_run_now() {
    print_header "手动更新 DDNS"
    [ ! -f "$DDNS_SCRIPT" ] && { error "DDNS 未安装"; return; }
    if ! ddns_runtime_config_matches; then
        error "DDNS 运行脚本与当前配置不一致，已停止更新"
        echo -e "  ${DIM}请进入修改配置，重新确认并生成 A / AAAA 更新脚本${NC}"
        return 1
    fi
    local RUN_MARK
    RUN_MARK=$(mktemp /tmp/vps-tools-ddns-run.XXXXXX) || {
        error "无法创建 DDNS 运行状态标记"
        return 1
    }
    info "正在更新..."
    local RC
    if bash "$DDNS_SCRIPT"; then
        RC=0
    else
        RC=$?
    fi
    if [ "$RC" -eq 0 ]; then
        if ! ddns_print_run_results "$RUN_MARK"; then
            error "未检测到全部启用记录的本次状态，请重新生成 DDNS 配置"
            rm -f "$RUN_MARK"
            return 1
        fi
    elif [ "$RC" -eq 75 ]; then
        warn "已有一次 DDNS 更新正在运行，请稍后再试"
    else
        ddns_print_run_results "$RUN_MARK" || true
        error "更新失败，请查看日志"
    fi
    rm -f "$RUN_MARK"
}

# ── DDNS 主菜单 ───────────────────────────────────────────
ddns_menu() {
    while true; do
        local D_ST; D_ST=$(ddns_status)
        local D_COLOR D_LABEL
        case "$D_ST" in
            running)       D_COLOR="$GREEN";  D_LABEL="运行中" ;;
            stopped)       D_COLOR="$RED";    D_LABEL="已停止（cron任务未设置）" ;;
            no_cron)       D_COLOR="$RED";    D_LABEL="已停止（cron未安装）" ;;
            cron_stopped)  D_COLOR="$RED";    D_LABEL="已停止（cron服务未运行）" ;;
            not_installed) D_COLOR="$YELLOW"; D_LABEL="未安装" ;;
        esac

        local D_PROVIDER_LABEL D_TITLE
        if [ -f "$DDNS_ZONE_FILE" ]; then
            D_PROVIDER_LABEL=$(ddns_provider_label)
            D_TITLE="${D_PROVIDER_LABEL} DDNS"
        else
            D_PROVIDER_LABEL="DDNS"
            D_TITLE="DDNS"
        fi
        print_header "$D_TITLE"

        if [ "$D_ST" != "not_installed" ] && [ -f "$DDNS_ZONE_FILE" ]; then
            local D_DOMAIN4 D_DOMAIN6 D_MODE_LABEL D_PROVIDER D_PROXIED D_ENDPOINT D_TTL D_INTERVAL D_LOG
            D_DOMAIN4=$(ddns_cfg_domain4)
            D_DOMAIN6=$(ddns_cfg_domain6)
            D_MODE_LABEL=$(ddns_mode_label)
            D_PROVIDER=$(ddns_provider)
            D_PROXIED=$(ddns_cfg_get PROXIED)
            D_ENDPOINT=$(ddns_cfg_get ENDPOINT)
            D_TTL=$(ddns_cfg_get TTL)
            D_INTERVAL=$(ddns_interval_min)
            D_LOG=$(ddns_log_path)
            echo -e "  状态 : ${D_COLOR}${BOLD}${D_LABEL}${NC}"
            echo -e "  服务商 : ${BOLD}${D_PROVIDER_LABEL}${NC}"
            echo -e "  模式 : ${BOLD}${D_MODE_LABEL}${NC}"
            if ddns_cfg_enable_a; then
                echo -e "  IPv4 : ${BOLD}${D_DOMAIN4:-未配置}${NC} ${DIM}(A)${NC}"
            else
                echo -e "  IPv4 : ${DIM}未启用${NC}"
            fi
            if ddns_cfg_enable_aaaa; then
                echo -e "  IPv6 : ${BOLD}${D_DOMAIN6:-未配置}${NC} ${DIM}(AAAA)${NC}"
            else
                echo -e "  IPv6 : ${DIM}未启用${NC}"
            fi
            if [ "$D_PROVIDER" = "huawei" ]; then
                echo -e "  Endpoint : ${BOLD}${D_ENDPOINT:-https://dns.myhuaweicloud.com}${NC}"
            else
                echo -e "  代理 : ${BOLD}$([ "$D_PROXIED" = "true" ] && echo '开启' || echo '关闭')${NC}"
            fi
            echo -e "  TTL  : ${BOLD}${D_TTL:-60}${NC}"
            echo -e "  定时 : ${DIM}每 ${D_INTERVAL} 分钟自动更新${NC}"
            ddns_cfg_enable_a && ddns_print_record_summary "IPv4" A "$D_DOMAIN4" "$D_LOG"
            ddns_cfg_enable_aaaa && ddns_print_record_summary "IPv6" AAAA "$D_DOMAIN6" "$D_LOG"
        elif [ -f "$DDNS_ZONE_FILE" ]; then
            local D_DOMAIN4 D_DOMAIN6 D_MODE_LABEL D_PROVIDER D_TOKEN_HINT
            D_DOMAIN4=$(ddns_cfg_domain4)
            D_DOMAIN6=$(ddns_cfg_domain6)
            D_MODE_LABEL=$(ddns_mode_label)
            D_PROVIDER=$(ddns_provider)
            if [ "$D_PROVIDER" = "huawei" ]; then
                [ -f "$DDNS_HUAWEI_KEY_FILE" ] && D_TOKEN_HINT="${DIM}AK/SK 已保存${NC}" || D_TOKEN_HINT="${YELLOW}AK/SK 未找到${NC}"
            else
                [ -f "$DDNS_TOKEN_FILE" ] && D_TOKEN_HINT="${DIM}Token 已保存${NC}" || D_TOKEN_HINT="${YELLOW}Token 未找到${NC}"
            fi
            echo -e "  状态 : ${D_COLOR}${BOLD}${D_LABEL}${NC}"
            echo -e "  服务商 : ${BOLD}${D_PROVIDER_LABEL}${NC}"
            echo -e "  模式 : ${BOLD}${D_MODE_LABEL}${NC}"
            ddns_cfg_enable_a && echo -e "  IPv4 : ${BOLD}${D_DOMAIN4:-未配置}${NC} ${DIM}(A)${NC}"
            ddns_cfg_enable_aaaa && echo -e "  IPv6 : ${BOLD}${D_DOMAIN6:-未配置}${NC} ${DIM}(AAAA)${NC}"
            echo -e "  凭据 : $D_TOKEN_HINT"
            echo ""
            echo -e "  ${DIM}检测到历史配置，可重新安装恢复定时任务${NC}"
        else
            echo -e "  状态 : ${D_COLOR}${BOLD}${D_LABEL}${NC}"
            echo ""
            echo -e "  ${DIM}将动态 DNS 解析到本机 IP，适合家宽/动态 IP 场景${NC}"
            echo ""
            echo -e "  ${BOLD}安装前准备：${NC}"
            menu_div
            echo -e "  ${GREEN}①${NC} 域名已托管到 Cloudflare 或华为云 DNS"
            echo -e "     将域名 NS 记录指向对应服务商提供的 nameserver"
            echo ""
            echo -e "  ${GREEN}②${NC} 准备 API 凭据"
            echo -e "     ${DIM}Cloudflare：API Token，权限 Zone / DNS / Edit${NC}"
            echo -e "     ${DIM}华为云：Access Key ID（AK）和 Secret Access Key（SK），账号需有 DNS 写权限${NC}"
            echo ""
            echo -e "  ${GREEN}③${NC} 准备子域名（如 home.example.com 的 home 部分）"
            menu_div
        fi

        echo ""
        menu_div
        if [ "$D_ST" = "not_installed" ]; then
            menu_item "1" "开始安装并配置 DDNS"
            menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
        else
            menu_pair "1" "立即更新" "2" "查看日志"
            menu_pair "3" "修改配置" "6" "Telegram 通知"
            if [ "$D_ST" = "running" ]; then
                menu_pair "4" "暂停自动更新" "5" "卸载 DDNS" "$YELLOW" "$YELLOW"
            elif [ "$D_ST" = "no_cron" ]; then
                menu_pair "4" "安装 cron 并恢复" "5" "卸载 DDNS" "$GREEN" "$YELLOW"
            else
                menu_pair "4" "恢复自动更新" "5" "卸载 DDNS" "$GREEN" "$YELLOW"
            fi
            menu_item "7" "替换分享链接地址"
            menu_pair "0" "返回主菜单" "00" "退出脚本" "$RED" "$RED"
        fi
        menu_div
        echo ""
        read -rp "$(ui_prompt '选择操作: ')" CH

        if [ "$D_ST" = "not_installed" ]; then
            case "$CH" in
                1) ddns_install ;;
                0) return ;;
                00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
                *) warn "无效选项"; sleep 1; continue ;;
            esac
        else
            case "$CH" in
                1) ddns_run_now ;;
                2) ddns_view_logs ;;
                3) warn "修改配置将重新安装 DDNS"
                   read -rp "  确认继续？(Y/n，默认Y): " C
                   [ -z "$C" ] && C="y"
                   if echo "$C" | grep -qiE '^y(es)?$'; then
                       ddns_install
                   else
                       warn "已取消"
                   fi ;;
                4)
                   if [ "$D_ST" = "running" ]; then
                       ddns_pause
                   else
                       ddns_resume
                   fi ;;
                5) ddns_uninstall ;;
                6) ddns_tg_config ;;
                7) ddns_share_link_tool ;;
                0) return ;;
                00) safe_clear; echo -e "${GREEN}已退出。${NC}"; exit 0 ;;
                *) warn "无效选项"; sleep 1; continue ;;
            esac
        fi

        # 日志查看后不需要再 Enter 一次（内部已有循环）
        if [ "$CH" != "0" ] && [ "$CH" != "2" ]; then
            ui_pause
        fi
    done
}
